WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[35031] = { title = "A Heartfelt Search", description = "I can feel a powerful presence in the marsh {name}.  I feel drawn to it.  We must go and take what is there.  Go on ahead, I must finish consuming these mushrooms.", objectives = "Investigate the strange presence at Crimson Fen.", completion = "We are so close I can almost touch it!  We will have to go deeper, much deeper!" }
WordHunterWoW_QuestEN[35032] = { title = "Into Anguish", description = "Rulkan's gift to you, the Fragment of Anguish, will allow you to pass into the fortress unhindered. Go up these stairs to the doorway, then use the fragment to enter the compound.\n\nOnce you are inside, you will find three altars powering the magical barrier around their stronghold.\n\nDestroy these runes, and Yrel and I will be able to join you in finding Ner'zhul.", objectives = "Use the Fragment of Anguish at the main doorway. Then destroy the Mark of Darkness, Mark of Shadows, and Mark of Anguish.", completion = "<You hear Prophet Velen's voice in your mind.>\n\nGood work, <name>! The barriers are down. We are on our way." }
WordHunterWoW_QuestEN[35033] = { title = "Welcome to Gorgrond", description = "Gorgrond is one of the most untamed landscapes in all of Draenor.\n\nOnly the most skilled of rangari venture this deep into the wilds.\n\nIt is their camp we are heading for. If you wish to travel ahead, it can be found down this path and to the right.\n\nMaraad and I shall follow after you momentarily. We still have some logistics to work out before we leave the landing.", objectives = "Follow the Wildwood Wash to Naielle's Watch.", progress = "I am a fan of the temple gardens but this place is just too far gone for my tastes.", completion = "You have chosen a very unfortunate time to visit our camp, my friend." }
WordHunterWoW_QuestEN[35035] = { title = "Seedbearers of Bad News", description = "When these seedbearers are slain their seeds survive. From them spring new seedbearers, not over years, but hours.\n\nLeaving their remains here would soon cause your camp to be overrun.\n\nBurn them, outsider, if you wish your camp to endure.", objectives = "Burn 5 Ancient Seedbearer corpses.", completion = "Watch them burn!" }
WordHunterWoW_QuestEN[35036] = { title = "Is This One of Yours?", description = "I found this one skulking nearby. He claims to be an ally of yours.\n\nIs this true? Or does he cook slowly over my fire?", objectives = "Talk to Rexxar and vouch for Bony Xuk.", completion = "That half-orc burned my toes!" }
WordHunterWoW_QuestEN[35037] = { title = "Bad at Breaking", description = "Screams and growls echo from the canyon below - even more than usual.\n\nI don't dare leave Nisha here alone yet.\n\nWill you investigate those noises, {name}?", objectives = "Search the Iron Horde camp at Crushfang's End.", completion = "They are enslaving gronn? This is an even bigger problem than it might seem." }
WordHunterWoW_QuestEN[35038] = { title = "What the Bony Xuk?", description = "Good to see your bones are still intact, {name}. Xuk's too.\n\nWhen you set off into the heart of the canyon, Xuk came to offer my services. Xuk not letting you take all of the skulls!\n\nXuk will share with you powerful spirit magics my clan has passed down for many generations. While Xuk make preparations, you must gather the reagents.\n\nFirst, we'll need crystals from husks of goren corpses. You can find their bodies in the canyon.", objectives = "Collect 25 Goren Crystals from Longtooth Gorgers.", progress = "Laughing Skull have some dirty tricks behind our masks.", completion = "Yes... we don't need their bones, but we do need their crystals." }
WordHunterWoW_QuestEN[35040] = { title = "Heart of the Fen", description = "If only the trees here weren't screaming at me I could concentrate better. Never mind, they are only trees.\n\nThis spot is used up but now I can feel a much stronger presence deeper in the marsh.  I will go there now and take what is rightfully mine!\n\nThen I will share it... with everyone...", objectives = "Follow Grulkor deeper into the Crimson Fen and deal with what comes.", completion = "Grulkor was crazy to think he could harness the power of those mushrooms, but then, most Laughing Skull are crazy.\n\nStill, not a complete waste of time." }
WordHunterWoW_QuestEN[35041] = { title = "Xuk It!", description = "It is done.\n\nWith this enchantment, not only can you roam amongst the goren freely, but you can move as they do.\n\nYour travels through Gorgrond are now made simple. You have safe access to places otherwise impossible to reach.\n\nXuk's ancestors have made it so.", objectives = "Use the goren disguise to explore locations in Gorgrond.", progress = "What has that orc done to you?!", completion = "It is good that you still have your wits about you. You do... have your wits about you?" }
WordHunterWoW_QuestEN[35044] = { title = "Cordana Summon", description = "", objectives = "" }
WordHunterWoW_QuestEN[35045] = { title = "In Ared's Memory", description = "My master has gone on to the Light, but I will continue his work.\n\n<Miall looks to Ared >\n\nShanai ortar, Ared.\n\nI will have his body sent to Auchindoun. For now, show me this artillery tower of yours.", objectives = "Speak to Miall inside of Fort Wrynn in Talador.", completion = "This is a beautiful and well equipped structure. Thank you for allowing me to work here.\n\nI am positive with this place I can carry on my master's legacy. You will not regret this!" }
WordHunterWoW_QuestEN[35047] = { title = "Dropping Bombs Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[35049] = { title = "Lumber Mill", description = "", objectives = "" }
WordHunterWoW_QuestEN[35050] = { title = "Rescue Rangari", description = "Many of our rangari have not been accounted for. It would seem the followers of Iyu have taken captives.\n\nWe will continue to search the area for survivors.\n\nIn the meantime, follow the Wildwood Wash west toward Highpass and look for any signs of our rangari comrades.\n\nOur people are stout and capable survivors. You may find more than you expect. Have them stay near the road and we will follow as soon as this... dwarf creature... has fixed his mechanical vessel.", objectives = "Find Rangari Rajess, Rangari Kolaan, and Rangari Jonaa.", progress = "It is no small thing for us to welcome so many strangers into our camps. Gorgrond is not the sort of place that breeds trust easily.", completion = "The rangari are stout survivalists. I knew they would not go down without a fight.\n\nThank you, <name>, for your help in this. You have done us a great honor." }
WordHunterWoW_QuestEN[35051] = { title = "Mage Tower Complete", description = "", objectives = "" }
WordHunterWoW_QuestEN[35055] = { title = "Lost Mole Machines", description = "Few people know the Blackrock clan better than Dark Iron dwarves.\n\nSo after Tanaan, we sent a bunch of mole machines to Gorgrond to build a listenin' post to keep an eye on them.\n\nMe own mole machine got way off course an' I got separated. It didn't take long to figure out all the other mole machines got off course as well.\n\nAccordin' to the readin's in me tank, a mole machine surfaced somewhere way to the west of here.\n\nMind scoutin' ahead while we get this tank operational?", objectives = "Find the Missing Mole Machine.", completion = "Well, that's one down, and about a dozen others to go. We best get a base goin'. Sounds like we might be here a while." }
WordHunterWoW_QuestEN[35056] = { title = "Tracking Flag - Horned Skull", description = "", objectives = "" }
WordHunterWoW_QuestEN[35057] = { title = "Vignette XP reward - Frostfire", description = "This quest is a placeholder until Task 67719 is complete.Upon completion of this quest you will gain:", objectives = "" }
WordHunterWoW_QuestEN[35058] = { title = "The Mysterious Flask", description = "The liquid swirling around inside the flask clearly has strong alchemical properties, but its nature is beyond your training.\n\nYou have heard that one of the Stonefang refugees at your garrison has some knowledge of the alchemy of Draenor. Perhaps he could tell you more?", objectives = "Speak to Lo'nash at your garrison.\n\nProvided item:", completion = "Ah. I see you have found a creation of Draenor alchemy." }
WordHunterWoW_QuestEN[35059] = { title = "Along the Riverside", description = "Vindicator Yrel has taken most of our forces north. She's establishing a forward base along the Skysong River.\n\nShe'll want to know that we're almost ready to move against Grommashar.\n\nI'm sure she can also use your help dealing with the Warsong orcs at Lok-rath.", objectives = "Speak with Vindicator Yrel at Yrel's Watch.", completion = "It's good to see you, commander. When I'd heard about your garrison caravan being destroyed....\n\nWell, let's just say that I feared the worst.\n\nWhat word from Telaari Station?" }
WordHunterWoW_QuestEN[35060] = { title = "Terms of Surrender", description = "Believe it or not, I have good news: we've already taken Lok-rath.\n\n<The vindicator beams with pride.>\n\nOur soldiers have captured most of the Warsong, including their leader, Uruk Foecleaver.\n\nI saved the honor of accepting his surrender for you. They're waiting for you inside, commander.", objectives = "Address Uruk Foecleaver at Lok-rath.", completion = "Commander <name>.\n\n\n\nTerms of surrender? Hmm... let me think." }
WordHunterWoW_QuestEN[35061] = { title = "The Pride of Lok-rath", description = "You think the Warsong are so easily defeated?\n\n<There's a rasping sound, like rope on metal.>\n\nI'm already tired of you Alliance, and you've just invaded my homeland.\n\n<The sound becomes more pronounced as Uruk Foecleaver looks you straight in the eye.>\n\nThere will be no surrender. The Warsong bow to no one!", objectives = "Kill Uruk Foecleaver.", completion = "Unfortunate, but I'm glad you made it out of that trap alive." }
WordHunterWoW_QuestEN[35062] = { title = "Lok-rath is Secured", description = "With their leader dead, the remaining Warsong will be easier to finish.\n\nAs soon as that's done, I'll pull our soldiers out of Lok-rath and head for Grommashar.\n\nIf you're heading back to Telaari Station, would you please inform D'kaan?", objectives = "Speak with Rangari D'kaan at Telaari Station.", completion = "If you hadn't gone to Lok-rath, our forces would have been decimated.\n\nI'm sorry to hear they laid a trap for you. I guess you have a reputation now." }
WordHunterWoW_QuestEN[35063] = { title = "We Need An Outpost", description = "Commander, we've gathered enough materials to build an outpost that will support our mission against the Iron Horde.\n\nHow shall we proceed?\n\nA lumber yard would be valuable for gathering resources in the dense overgrowth to the south, and in confronting the plant monstrosities that defend it.\n\nOn the other hand, a sparring arena would provide us the brutish forces we'd need to push through the magnaron wastelands to the north.\n\nWhen you're ready, make your choice on the table.", objectives = "Use the Drafting Table to craft a Lumber Yard or a Sparring Arena.", progress = "Buildin' an outpost out here requires a certain kind o' crazy.", completion = "Well, that is one thing ta pick. Tell you what, you get this building up and running at full steam and I'll see if I can't adapt these blueprints to work for the space in your garrison." }
WordHunterWoW_QuestEN[35064] = { title = "Sparring Arena", description = "", objectives = "" }
WordHunterWoW_QuestEN[35065] = { title = "A Harvester Has Come", description = "This is what happens when one stands in the path of a genesaur. And where a genesaur walks, the botani follow.\n\nI saw one entering our shelter cave along the northern side of the camp.\n\nIt is commanding the podlings to gather the corpses of our fallen brethren and must be stopped.\n\nI must tend to our wounded, and gather supplies for our departure.\n\nIf you are serious about being a hero, venture into the cave and slay this botani.", objectives = "Slay Harvester Ommru.", completion = "I dread to think what the botani had intended to do with the corpses of our fallen." }
WordHunterWoW_QuestEN[35066] = { title = "Fire Ammonite", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Frostfire Ridge for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", objectives = "Mak'jin wants you to collect 10 Fire Ammonite Eggs from Frostfire Ridge.", progress = "Anything biting?", completion = "These will do nicely, <name>!  Thank you!" }
WordHunterWoW_QuestEN[35067] = { title = "Silence the War Machines", description = "The Iron Horde supplied Lok-rath with war machines from Ironfist Harbor. It won't take long for them to level Yrel's Watch.\n\nSomeone has to silence those war machines!", objectives = "Destroy the 3 Iron Horde War Machines.", completion = "Thank you, commander. I thought we were done for sure." }
WordHunterWoW_QuestEN[35068] = { title = "If They Won't Surrender...", description = "This is the backbone of the army we intend to send against Garrosh Hellscream and Grommashar.\n\nIf they won't surrender, we have no choice but to eliminate the Warsong.", objectives = "Kill 10 enemy forces at Lok-rath.", completion = "Regrettable, but I understand the pride of the Warsong. I would never surrender." }
WordHunterWoW_QuestEN[35069] = { title = "Terror of Nagrand", description = "<The body of a fallen soldier lies here. Blood and gore trail back from the corpse to the entrance of the cave just to the north.>\n\n<Judging by the howls and the carnage surrounding the den, something truly terrifying must be in there.>", objectives = "Collect Shagor's Collar from Shagor.", progress = "Commander. How may I help you?", completion = "That's the beast's collar? I heard its howls all the way over here!" }
WordHunterWoW_QuestEN[35070] = { title = "Shut 'er Down", description = "Burrowing native creatures known as \"goren\" have tunneled into our crystal mines. Judging from our experience at the gates, I suspect my own experimental resonance crystal is whipping the native wildlife into a frenzy.\n\nEnter the Elodor Dig to the north and disable the malfunctioning resonance crystal!\n\nBe careful - my earthworkers report that the mine is crawling with those beasts.", objectives = "Disable the Malfunctioning Resonance Crystal in the Elodor Dig.", completion = "Excellent. I will send in some peacekeepers to quell any remaining problems.\n\nExarch Naielle may be right - perhaps I am too aggressive in adapting our technology to this world. Still, I will never quit. Our civilization must move forward!" }
WordHunterWoW_QuestEN[35071] = { title = "Jawless Skulker", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Gorgrond for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", objectives = "Mak'jin wants you to collect 10 Jawless Skulker Eggs from Gorgrond.", progress = "Anything biting?", completion = "These will do nicely, <name>!  Thank you!" }
WordHunterWoW_QuestEN[35072] = { title = "Fat Sleeper", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Nagrand for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", objectives = "Mak'jin wants you to collect 10 Fat Sleeper Eggs from Nagrand.", progress = "Anything biting?", completion = "These will do nicely, <name>!  Thank you!" }
WordHunterWoW_QuestEN[35073] = { title = "Blind Lake Sturgeon", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Shadowmoon Valley for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", objectives = "Mak'jin wants you to collect 10 Blind Lake Sturgeon Eggs from Shadowmoon Valley.", progress = "Anything biting?", completion = "These will do nicely, <name>!  Thank you!" }
WordHunterWoW_QuestEN[35074] = { title = "Blackwater Whiptail", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Talador for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", objectives = "Mak'jin wants you to collect 10 Blackwater Whiptail Eggs from Talador.", progress = "Anything biting?", completion = "These will do nicely, <name>!  Thank you!" }
WordHunterWoW_QuestEN[35075] = { title = "Abyssal Gulper Eel", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Spires of Arak for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", objectives = "Mak'jin wants you to collect 10 Abyssal Gulper Eel Eggs from Spires of Arak.", progress = "Anything biting?", completion = "These will do nicely, <name>!  Thank you!" }
WordHunterWoW_QuestEN[35077] = { title = "Defungination", description = "Have you seen the fungus out there in the water? It's growing faster than a baby ravasaur from Un'goro, and if we don't get it under control, the Gearworks is gonna be ruined like our last village.\n\nUncle Krixel used to tell me to burn away the red fungus because that's what makes it grow so fast.\n\nYou could help us out by taking a flame blaster and clearing out some of those spores down in the shallows.", objectives = "Use the QR58 Flame Blaster to destroy 20 Spore Pustules.", completion = "Hey good job out there! I couldn't have done it any better myself." }
WordHunterWoW_QuestEN[35079] = { title = "Spore-be-Gone", description = "We got an emergency!\n\nA bunch of spore drifters have infested the shore and tore up our Spore-B-Gone turrets.\n\nWe're caught with our armor off here! If we don't get those turrets back online then those spores are going to float right in to town and then we'll have another Pinchwhistle Point on our hands!\n\nWe need to get out there and manually activate them.\n\nWell? Are you in?", objectives = "Activate 6 Spore-be-Gone Turrets.", completion = "Hey you got the dispensers going again.\n\nNice job pal!" }
WordHunterWoW_QuestEN[35080] = { title = "The Mother Lode", description = "Hey we got ourselves a crisis here! Our zeppelin \"The Mother Lode\" crashed onto the south mountain range.\n\nIt was supposed to only be on an observation mission, what could have happened?\n\nWe got to get down there quick and I'm going to need your help on this.\n\nAre you with me?", objectives = "Meet up with Kimzee Pinchwhistle at the Wreck of the Mother Lode.", completion = "Oh my gosh, this is way worse than I thought it was gonna be. I'm really going to need a hand with getting these survivors out of here.\n\nGood thing I have you on the payroll." }
WordHunterWoW_QuestEN[35081] = { title = "Clearing Out Before Cleaning Up", description = "Here's the situation.\n\nWe need to get this salvage operation moving ASAP, but the ship went down right in the middle of the wasp nests.\n\nThe ugly bugs are all over the place, and I can't call my team in here to start work until they're taken care of.\n\nGo kill as many of 'em as you can and I'll cut you in on some of the haul.", objectives = "Kill 8 Crimsonwing Wasps.", progress = "I still see a mess of wasps down there.\n\nWe need to clear those wasps out before I can get the salvage operation started.", completion = "That's how ye do it! As soon as my crew gets here we can start work.\n\nHere's your pay. Thanks for doing the job." }
WordHunterWoW_QuestEN[35082] = { title = "Getting the Crew Back Together", description = "Oh wow, the debris is all over the mountainside! The survivors won't make it if we don't do something quick. They need healing NOW!\n\nHere, take my bandages and go patch them up.", objectives = "Revive 6 Injured Crewmen.", completion = "Good work, <name>.\n\nOnce Gazwitz gets his team up here we can get the crewmen back to the Gearworks." }
WordHunterWoW_QuestEN[35083] = { title = "Disrupt the Rituals", description = "No longer do the Warsong seek to be one with the elements; instead they abuse their power by using it to channel the darkness of the void.\n\nI will not tolerate these rituals to continue. Locate the ritual totems the Warsong use to channel the void and destroy them.\n\nThe gift of the elements was not given to the orcs only to be defiled and used as a plaything.", objectives = "Destroy the Ritual Totems.", progress = "Have you destroyed the ritual totems?", completion = "Dark shamanism is a dangerous practice, <name>.\n\nIt is true that the void can be a source of terrible power, but it is the kind of power that comes at a price.\n\nThese woods are safer now that you have put an end to the rituals." }
WordHunterWoW_QuestEN[35084] = { title = "Silence the Call", description = "The Warsong clan, in their lust for dominance, have turned to the darkness of the void for power. Dark shamanism is a loathsome, dangerous practice that abuses the elemental gift I have bestowed upon them.\n\nThere is one among the Warsong that calls out the loudest to the void, an elder shaman named Kuhlrath. Slay him and the rest of his dark shaman.\n\nI will not allow the Warsong to abuse the elements and desecrate tradition.", objectives = "Slay Kuhlrath and 10 Warsong shaman.", progress = "Have you put an end to the Warsong ritualists?", completion = "The gift of shamanism is not one to be taken lightly. When the gift is abused, the elements will rise up in indignation and smite the shaman." }
WordHunterWoW_QuestEN[35085] = { title = "Through the Nether", description = "The rituals have been disrupted, yet the nether beacons still glow with power....\n\nThis can only mean that the beacons are powered from within the Twisting Nether itself!\n\nThe connection to the void must be severed! There is but one way to accomplish this; you must slay the void creature that maintains the connection with our world.\n\nLay your hands upon a beacon and travel into the Twisting Nether. When you have arrived on the other side, locate a Shamanstone and use it to contact me.", objectives = "Use a Void Beacon to travel to the Twisting Nether.", progress = "The veil between dimensions is thin. Do you hear my words through the shaman stone?", completion = "The Shamanstone appears to be working, even from within the Twisting Nether.\n\nThere is much that needs to be done, <name>. The monsters of the void are gathering upon Oshu'gun and must be stopped, else they invade our realm." }
WordHunterWoW_QuestEN[35086] = { title = "The Void March", description = "Hidden behind the veil of the Twisting Nether, the abominations of the void march upon Oshu'gun. The great void growing deep within the mountain has drawn them like moths to a flame.\n\nWave upon wave, the creatures of the void march upon the mountain and sacrifice themselves to Invalidus. The void lord Invalidus cannot be allowed to feast upon the other void creatures, else it will become too powerful to stop.", objectives = "Destroy 10 Void Terrors and 15 Void Tendrils.", completion = "The void lord must be stopped. Thanks to your effort, the tide of void creatures has waned... but if we are to defeat Invalidus we must act swiftly." }
WordHunterWoW_QuestEN[35087] = { title = "The Nether Approaches", description = "By connecting with the Twisting Nether, the Warsong shaman have created a ripple effect that they could not have anticipated.\n\nLook around and you will see countless portals beginning to open, signs that the Twisting Nether seeks to connect to Draenor.\n\nShould these portals successfully open, the path will be clear for all manner of demons and void creatures to rampage across this valley.", objectives = "Collapse 6 Void Portals.", completion = "If those portals were to fully expand and open, the path would have been clear for the horrors of the Twisting Nether to march upon Nagrand.\n\nThe Warsong have been careless in their mad pursuit of power and glory." }
WordHunterWoW_QuestEN[35088] = { title = "The Shadow of the Void", description = "The moment has come to take on the void lord. Invalidus grows more powerful by the minute, so you must move with haste if you are to defeat the monster.\n\nAt each of the Warsong ritual locations there is a void crystal; these crystals are used to channel the energy of the void from within the Twisting Nether.\n\nDisturb the crystal, and Invalidus will sense your presence below.\n\nBe ready, as soon as the crystal is disturbed, Invalidus will waste no time hunting you down.", objectives = "Summon and defeat Invalidus.", progress = "Have you defeated Invalidus?", completion = "With Invalidus destroyed and the Warsong rituals halted, the threat of the Twisting Nether has subsided." }
WordHunterWoW_QuestEN[35089] = { title = "Skimming Off the Top", description = "That flying machine is our ticket out of here but its fuel tank is bone dry!\n\nWe're right next to the oil fields but with the infected out there we don't have time to run a line up here so we need to improvise.\n\nThe oil creatures moving next to the pumps out there are full of a highly potent mixture that I can drop right into the tank. Grab some of that oil for me and we'll be one step closer to getting out of here.", objectives = "Collect 4 Volatile Oil.", progress = "Do ya have that oil for me yet?", completion = "Yea that's the stuff!\n\nNow I just need to connect the spark plugs and patch up a few holes and it'll be nearly in working order!" }
WordHunterWoW_QuestEN[35090] = { title = "The Right Parts for the Job", description = "Uncle Krixel's a tough one but he won't be going anywhere on foot with his leg broken.\n\nHe has a flying machine he brought from Azeroth that can fly us out of here. Problem is, the engine's busted.\n\nI'll need some parts to fix the thing. My car's wasted but those broken shredders just outside of town should have what we need. We don't have time to break them down by hand so just use this rocket launcher and blow 'em apart. Anything that survives the blast should be strong enough to use on the engine.", objectives = "Use the G-14 Buster Rocket near Broken Shredders to retrieve Serviceable Gears.", progress = "Got any parts for me?", completion = "Great work <name>!\n\nGive me some time and I'll have this thing ready to roll out!" }
WordHunterWoW_QuestEN[35091] = { title = "Sporicide", description = "It's revolting, absolutely disgusting, infuriating even!\n\nI'm talking about seeing those spore creatures walking around Pinchwhistle Point.\n\nWhile I'm working on the machine here how about you go out and kill off some of those spore creatures? I'll feel a bit better knowing there are less of those things moving around.", objectives = "Kill 6 Spore Shamblers in Pinchwhistle Point.", progress = "Did you put down those spore creatures yet?", completion = "Thank you, <name>.\n\nThe less of those spore beasts around the safer we all are." }
WordHunterWoW_QuestEN[35092] = { title = "The Portal's Power", description = "The mana bombs were not enough. This was always a risk.\n\nThis is unfortunate.\n\nGul'dan, the orc beneath these grates, says he can shut down this portal. Find a way in there, and do whatever it takes to slow this portal down.\n\n<The archmage's eyes lock with yours.>\n\nWHATEVER IT TAKES.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Gul'dan underneath the Dark Portal.The mana bombs were not enough. This was always a risk.\n\nThis is unfortunate.\n\nGul'dan, the orc beneath these grates, says he can shut down this portal. Find a way in there, and do whatever it takes to slow this portal down.\n\n<The archmage's eyes lock with yours.>\n\nWHATEVER IT TAKES.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[35093] = { title = "The Dark Side of the Moon", description = "Yrel and I have located Warlord Ner'zhul. He is meeting with Grommash Hellscream atop the highest altar overlooking Anguish Fortress.\n\nMeet us there. We must stop him.", objectives = "Find Ner'zhul.", progress = "Ner'zhul will pay for what he has done.", completion = "We saved everyone we could, <name>. We were too late for the others... including my sister.\n\nProphet Velen is right. When it is asked of us, we ALL must fight. I promise this: I will never again let my loved ones suffer.\n\nNer'zhul is close to calling down the Dark Star. We are the only ones who can stop him." }
WordHunterWoW_QuestEN[35094] = { title = "A Deal with Darkness", description = "<With Gul'dan gone, the Dark Portal is disabled, and the threat to Azeroth is suspended.>You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Report back to Archmage Khadgar atop the Dark Portal.<With Gul'dan gone, the Dark Portal is disabled, and the threat to Azeroth is suspended.>You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[35095] = { title = "Along the Riverside", description = "Durotan has taken most of our forces west. He's establishing a forward base along the Skysong River.\n\nHe'll want to know that we're almost ready to move against Grommashar.\n\nI'm sure he'll also appreciate your help dealing with the Warsong orcs at Lok-rath.", objectives = "Speak with Durotan at Riverside Post.", completion = "It's good to see you, commander. When I'd heard about your garrison caravan being destroyed....\n\nWell, let's just say that I feared the worst.\n\nWhat word from Wor'var?" }
WordHunterWoW_QuestEN[35096] = { title = "Terms of Surrender", description = "I have good news, commander: we've already taken Lok-rath.\n\n<The warchief grins.>\n\nThe Horde's soldiers have captured most of the Warsong, including their leader, Uruk Foecleaver.\n\nI saved the honor of accepting his surrender for you. They're waiting for you inside, commander.", objectives = "Address Uruk Foecleaver at Lok-rath.", completion = "Commander <name>.\n\n\n\nTerms of surrender? Hmm... let me think." }
WordHunterWoW_QuestEN[35097] = { title = "The Pride of Lok-rath", description = "You think the Warsong are so easily defeated?\n\n<There's a rasping sound, like rope on metal.>\n\nI'm already tired of you Horde, and you've just invaded my homeland.\n\n<The sound becomes more pronounced as Uruk Foecleaver looks you straight in the eye.>\n\nThere will be no surrender. The Warsong bow to no one!", objectives = "Kill Uruk Foecleaver.", completion = "Unfortunate, but you made it out of the trap alive and Lok-rath is dealt with." }
WordHunterWoW_QuestEN[35098] = { title = "Lok-rath is Secured", description = "With their leader dead, the remaining Warsong will be easy pickings.\n\nAs soon as that's done, I'll pull our soldiers out of Lok-rath and head for Grommashar.\n\nIf you're heading back to Wor'var, inform Thrall that we'll be ready soon.", objectives = "Speak with Thrall at Wor'var.", completion = "If you hadn't gone to Lok-rath, our forces would have been decimated.\n\nI'm sorry to hear they laid a trap you. You have a reputation now." }
WordHunterWoW_QuestEN[35099] = { title = "Silence the War Machines", description = "The Iron Horde supplied Lok-rath with war machines from Ironfist Harbor. It won't take long for them to level Riverside Post.\n\nSomeone has to silence those war machines!", objectives = "Destroy the 3 Iron Horde War Machines.", completion = "Thank you, commander. I thought we were done for sure." }
WordHunterWoW_QuestEN[35100] = { title = "If They Won't Surrender...", description = "This is the backbone of the army we intend to send against Garrosh Hellscream and Grommashar.\n\nIf they won't surrender, we have no choice but to eliminate the Warsong.", objectives = "Kill 10 enemy forces at Lok-rath.", completion = "Regrettable, but I understand the pride of the Warsong. I would never surrender." }
WordHunterWoW_QuestEN[35101] = { title = "Terror of Nagrand", description = "<The body of a fallen soldier lies here. Blood and gore trail back from the corpse to the entrance of the cave just to the north.>\n\n<Judging by the howls and the carnage surrounding the den, something truly terrifying must be in there.>", objectives = "Collect Shagor's Collar from Shagor.", progress = "Commander. How may I help you?", completion = "That's the beast's collar? I heard its howls all the way over here!" }
WordHunterWoW_QuestEN[35102] = { title = "Unleashed Steel", description = "Thank you... boss.\n\nI won't let you down! I didn't even try to sneak one of those low quality blades here that one of your peons placed right next to the cage. Which by the way was a pretty terrible idea and that thing should be moved before you get anyone less honorable in here.\n\nEnough talk, lets check this place out!", objectives = "Speak to Morketh Bladehowl inside of Vol'jin's Pride in Talador.", completion = "We have a lot of basic arms here but I'll get them improved in no time.\n\nThanks for giving me this chance." }
WordHunterWoW_QuestEN[35103] = { title = "The Alchemist", description = "I know a little about alchemy from my cousin Kadar. She is the alchemist at Stonefang Outpost. If you wish to learn more, she is the one with whom to speak.\n\nI only hope she has survived the attack.", objectives = "Find Kadar at the Boneslag.", completion = "My apprentice... Inside... (She dies in your arms.)" }
WordHunterWoW_QuestEN[35104] = { title = "The Apprentice", description = "Kadar's last words... Is there someone still inside the hut?", objectives = "Remove the rubble and speak with Ang'kra.", progress = "She is unconscious and pinned under heavy, broken shelves, but she is still breathing.", completion = "What... happened? Where is my master?" }
WordHunterWoW_QuestEN[35105] = { title = "Honor and Remember", description = "So she is dead.\n\nShe took me in when I had no one. She taught me everything I know. She gave me everything I have. And now, she is dead.\n\nI owe you my life, stranger, but I wish you had saved hers, not mine. Please, help me bury her.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Gather Frostweed and Fireweed seeds." }
WordHunterWoW_QuestEN[35106] = { title = "Avenge and Reclaim", description = "I will avenge my master and retrieve her life's work. Honor demands it. My heart yearns for it. If I die trying, so be it. The murderer will pay.", objectives = "Slay Kadar's killer and retrieve the book.", progress = "The murderer will pay.", completion = "My heart is furious with you for stealing my kill, but my mind knows that I did not have the strength to avenge my master myself. I will forgive you, if you allow me to pay my debt of honor." }
WordHunterWoW_QuestEN[35107] = { title = "Book of Alchemical Secrets", description = "The writing in the leather-bound tome is undecipherable, except for the inscription inside the cover: \"For my daughter, Ang'kra.\"You will receive:", objectives = "Return the Book of Alchemical Secrets to Ang'kra." }
WordHunterWoW_QuestEN[35128] = { title = "Fair Warning", description = "The ogron here are far from brilliant, but they are more intelligent than the gronn. They're large, and even stronger than they look.\n\nTheir leader, Borogahn, is especially formidable. Despite several fights, I have not yet managed to kill him.\n\nHeed my words, friend. Take caution as you explore their lair.\n\nNisha is ready to move. Ask her to take you to the mouth of the cave, and I'm sure she would be happy to.", objectives = "Kill 8 Ogron Spinecrushers and Borogahn.", completion = "Most people cannot handle ogron in single combat." }
WordHunterWoW_QuestEN[35129] = { title = "Leave Every Soldier Behind", description = "Hmmm.\n\nThe ogron possess something of value to the Iron Horde. I'm sure they're unaware, likely just bored and in  need of something to torture.\n\nI'd be inclined to just let them be, it's a fate they deserve. But we can't afford not to follow up on this clue. With any luck, it will help us stop the Iron Horde from turning Gorgrond's most fearsome creatures into weapons.\n\nTry to find this Corporal Thukmar and his notes. We'll meet you there.", objectives = "Find Corporal Thukmar and recover his intel.", progress = "Again you've done well, friend.", completion = "We have the notes. Let us see what they reveal about our enemy's strategy." }
WordHunterWoW_QuestEN[35136] = { title = "Chains of Iron", description = "The artifact we seek is within our grasp.\n\nBe prepared for a fight. If they truly have learned how to control gronn, this may be more difficult than I anticipated.\n\nI will join you in this battle as soon as you arrive.", objectives = "Defeat Captain Brak and find the Heart of the Magnaron.", progress = "The artifact is yours, and is well earned.", completion = "Good work, <name>. We can use this artifact against the Iron Horde when the time is right." }
WordHunterWoW_QuestEN[35137] = { title = "The Sparring Arena", description = "We owe you our freedom, and more. I have spoken to the others, we are willing to return with you to your garrison and teach those pitiful creatures you call \"soldiers\" how to properly fight.\n\nWe will also do our best to impart our knowledge to you, Commander. Should you have need of us when in the wilds of Gorgrond, simply call us.\n\nYou may wish to warn Rangari Jonaa of our coming.", objectives = "Speak with Rangari Jonaa at Highpass in Gorgrond.", completion = "Now that we have the trainers, we can start training your forces to do something other than chop lumber. Heh heh." }
WordHunterWoW_QuestEN[35139] = { title = "Eye in the Sky", description = "The notes you recovered tell of a device capable of subjugating even a magnaron.\n\nAncient legends speak of such artifacts, crafted by the worldbuilders to keep these creatures in check. I had discounted them as silly stories, but if they are true...\n\n{name}, Draenor is doomed.\n\nNo army will be able to stop them if they harness this power. We must stop them or die trying.\n\nHere, I shall bind our sight to Nisha and hope she can locate this artifact.", objectives = "Speak to Nisha.", progress = "We are in luck! The artifact is still within reach.", completion = "Good. We know where we must go to acquire the artifact." }
WordHunterWoW_QuestEN[35140] = { title = "THAELIN!", description = "That little...!\n\n<Yrel tries to maintain her composure.>\n\nThaelin Darkanvil sent us a shipment. It was supposed to be engineering parts.\n\nInstead, when we just opened one of the crates, out popped a baby goren. Do you know how destructive those things are?\n\nAnd, of course, the one baby immediately set about letting all the other ones loose.\n\nWant to help me get some revenge?", objectives = "Capture 15 Baby Goren.", progress = "Did you round them all up?", completion = "Outstanding.\n\n<Vindicator Yrel beckons you closer so that the two of you can conspire.>" }
WordHunterWoW_QuestEN[35141] = { title = "Carrier Has Arrived", description = "We're going to get some payback on that little stinker.\n\nPut the baby goren into one of those carriers and then make a special delivery to Thaelin.", objectives = "Deliver the Baby Goren Carrier to Thaelin Darkanvil at Telaari Station.\n\nProvided item:", completion = "Wait a minute, <name>... let's be reasonable. I can hear what's in that carrier.\n\nIt was just a harmless prank.\n\nDon't do it, please!\n\nStop!\n\nDon't open that carrier!" }
WordHunterWoW_QuestEN[35142] = { title = "Goren Invasion!", description = "The earth quakes beneath us, Commander. Our scouts are not returning. I can feel an attack creeping up on us, but from where?", objectives = "Repel the goren invasion of your garrison.\n\n(Speak with Sergeant Grimjaw again to begin)", progress = "We must hold the line!", completion = "The peons will clean this mess, Commander. Rubble and holes everywhere. The rest of us will look for hiding goren so that we may apologize to them for butchering their warleader." }
WordHunterWoW_QuestEN[35143] = { title = "Blood of the Burning Blade", description = "Hallvalor is the ancestral home of my clan, the Burning Blade. When the new warlord and his family came to power, I was exiled for being a half-breed.\n\nI want justice.\n\nI suspect you won't mind killing along the way. Not that you'll have any choice.", objectives = "Kill 15 Burning Blade forces at Hallvalor.", completion = "A great victory over the Burning Blade!\n\nThis Flamebender Ka'graz sounds formidable. We shall have to keep an eye on her and her blademasters." }
WordHunterWoW_QuestEN[35144] = { title = "Dark Binding", description = "Even as we speak, the pale within Shadowfall Canyon are enslaving the elements to their will. Many elemental spirits have already been enthralled, and more will follow.\n\nThe pale must be stopped and the elementals they enslave set free.\n\nJourney into Shadowfall Canyon and set free those elemental spirits which are not fully enthralled by the pale. As for the elementals already enslaved by the pale, the only mercy we can give them now is to release their bonds through death.", objectives = "Free 10 elemental spirits.", progress = "Have you freed the elemental spirits of Shadowfall Canyon from the dark bonds of the pale?", completion = "The pale have been taught by Cho'gall to enslave the elemental spirits of this land. When an elemental is enthralled in this manner, it cannot be reversed even by a Farseer such as myself." }
WordHunterWoW_QuestEN[35145] = { title = "The Pale Threat", description = "The Pale are wretched creatures that hide beneath the ground, ever plotting against those who dwell upon the surface. They stalk the Underpale, a twisted and dark cavern beneath Oshu'gun.\n\nIf we are to succeed in stopping Cho'gall we must fight our way through their ranks beneath the earth.\n\nMake your way into the cavern, slay the vile creatures within and take out the Pale leader... the one known as Greyseer.", objectives = "Kill Greyseer and 6 Pale orcs.", completion = "I have encountered evil in many places, <name>. Even deep within my own soul, I have seen dark shadows of what could be.\n\nHowever, the evil within the hearts of the Pale defies explanation. It is dark, loathing, and miserable in a way I have never encountered." }
WordHunterWoW_QuestEN[35146] = { title = "The Good Doctor", description = "Our expedition biologist has been kidnapped by podlings!\n\nWe came to Nagrand to explore, to slay the mightiest of beasts, and test our mettle alongside the great Hemet Nesingwary.\n\nAs soon as we arrived, Hemet's hunting prowess was needed to combat the Warsong. Rather than sit around twiddling our thumbs, we decided to continue the expedition!\n\nWe were exploring Spiteleaf Thicket when podlings ambushed us! In the chaos, Dr. Hadley Ricard was taken captive.\n\nPlease, we can't just leave him there!", objectives = "Rescue Dr. Hadley Ricard.", completion = "Your timely arrival to rescue me from the podlings was most appreciated!\n\nThis research station has seen better days... my equipment and belongings were damaged in the ambush.\n\nHowever, with your aid, I'm sure we'll be up and running again in no time!" }
WordHunterWoW_QuestEN[35147] = { title = "Fragments of the Past", description = "", objectives = "What these ogres see as junk, we see as money!", progress = "What these ogres see as junk, we see as money!", completion = "<Sallee Silverclamp examines the fragments you've retrieved>\n\nThese will do nicely! Great work, kiddo!" }
WordHunterWoW_QuestEN[35148] = { title = "Trouble at the Overwatch", description = "Ya know, we sent a couple o' scouts ta check out those big, smelly, 'civilized' ogres at Mar'gok's Overwatch.\n\nHaven't heard from 'em in a bit. Matter o' fact, not since I saved yer bacon up at Telaar.\n\nHave some time ta ride over there and check up on 'em, boyo?", objectives = "Locate Rangari Eleena at Mar'gok's Overwatch.", completion = "I'm afraid we have some trouble." }
WordHunterWoW_QuestEN[35149] = { title = "Sparring Arena", description = "", objectives = "" }
WordHunterWoW_QuestEN[35150] = { title = "Trouble at the Overwatch", description = "Yesterday, I sent two of my best scouts to spy on the ogres at Mar'gok's Overwatch.\n\nI haven't heard back from them.\n\n{name}, would you do me the honor of checking on them? I'm sure it's nothing; the Overwatch is a large fortification.\n\nI'd feel better knowing they're okay.", objectives = "Find Akrosh at Mar'gok's Overwatch.", completion = "I'm honored you're here to help, wolf-brother. Things here are worse than we thought." }
WordHunterWoW_QuestEN[35151] = { title = "Your Base, Your Choice", description = "You have already constructed an impressive garrison in Frostfire. I believe I should defer this next choice to you.\n\nOne region of Gorgrond is rich in resources. A lumber mill could help us make the most of them.\n\nAnother region harbors hardened gladiators. A sparring arena would help persuade them to fight for our cause.\n\nEither path will strengthen us as we seek to find and weaken the Iron Horde.\n\nWhich do you choose, Commander?", objectives = "Choose to construct either a Lumber Mill or a Sparring Arena at Beastwatch.", completion = "A fine choice. It will need more work before such a structure could be built in your garrison, but this is a start." }
WordHunterWoW_QuestEN[35152] = { title = "The Sparring Arena", description = "We owe you our freedom, and more. I have spoken to the others, we are willing to return with you to your garrison and teach those pitiful creatures you call \"soldiers\" how to properly fight.\n\nWe will also do our best to impart our knowledge to you, Commander. Should you have need of us when in the wilds of Gorgrond, simply call us.\n\nYou may wish to warn Limbflayer of our coming.", objectives = "Speak with Limbflayer at Beastwatch in Gorgrond.", completion = "Kash'drakor is coming here?! Ha! I once saw him cut through a dozen Laughing Skulls because they had his son.\n\nHe is the purist expression of destruction." }
WordHunterWoW_QuestEN[35153] = { title = "Vignette: Fungal Praetorian", description = "", objectives = "" }
WordHunterWoW_QuestEN[35154] = { title = "Things Are Not Goren Our Way", description = "The abandoned mine shaft has been overrun with goren!  They seem to be responding to commands from a big one further down in the mine.  If you can take him out, the rest will probably retreat.\n\nOnce you have those goren cleared out, we can get that mine up and working!", objectives = "Kill Stonetooth in the Garrison Mine.", progress = "Were you able to take out the leader?", completion = "Nice job, <name>! Let's get this mining operation started!" }
WordHunterWoW_QuestEN[35155] = { title = "Obliterating Ogres", description = "We got more of those magic tossing ogres here which is never a good thing.\n\nThese new ogres are especially bossy and have increased work being done here.\n\nDo you know what stops ogres from working hard? Dying.\n\nKill some ogres here and get this camp back to its normal boring self.", objectives = "Kill 15 ogres at Mar'gok's Overwatch.", completion = "Great! They are pretty scared now. Its hard to do research when you are afraid of being stabbed in the back at any time!" }
WordHunterWoW_QuestEN[35156] = { title = "Removing the Paper Trail", description = "This box is filled with writings and diagrams that oddly resemble research into the nullification of magic.  It would be best to ruin these efforts by destroying any research found.", objectives = "Destroy 8 Boxes of Ogre Research at Mar'gok's Overwatch.", progress = "Hey, do you smell smoke?", completion = "Burning magical paper smells pretty bad!  Good thinking <name>, keeping these ogres dumb is a solid plan!" }
WordHunterWoW_QuestEN[35157] = { title = "Obtaining Ogre Offensive Orders", description = "The upper bluff must be really important to the ogres. Two fancy looking ogre mages came down from there and starting ordering all the others around.\n\nGo get those orders and meet up with my scout Dalgorsh on the upper bluff. They will be more useful to him up there.", objectives = "Collect Crulgorosh's Orders and Thulgork's Orders at Mar'gok's Overwatch.", progress = "Don't forget! Get the orders and take 'em to Dalgorsh further in.", completion = "Finally some help! I barely got out alive!\n\nYou have some ogre orders? Let me see...\n\nWell that's not good news." }
WordHunterWoW_QuestEN[35158] = { title = "Reglakk's Research", description = "Okay so these orders say Reglakk is in charge of something called Breaker research, which makes super powerful ogres. I don't know about you but that sounds bad.\n\nI'm pretty hurt, do you think you can go up there alone and make Reglakk rethink his research?", objectives = "Stop Grand Magister Reglakk's research.", completion = "We stopped him for the time being, but I think we'll have to come up with a more permanent solution. No doubt he's back in Highmaul plotting new versions of Breakers.\n\nI think a visit to ogre capital is far overdue." }
WordHunterWoW_QuestEN[35159] = { title = "Removing the Reinforcements", description = "Its not good {name}, these smart ogres have got a portal working up there and they are bringing in more ogres from somewhere else.\n\nIt looks like it takes a lot of effort to keep it open though. If you take it down I'm guessing they will be delayed quite a while.", objectives = "Destroy the Portal to Highmaul.", completion = "Good, hopefully they will give up on making a portal here." }
WordHunterWoW_QuestEN[35161] = { title = "Vignette XP reward - Talador", description = "This quest is a placeholder until Task 67719 is complete.Upon completion of this quest you will gain:", objectives = "" }
WordHunterWoW_QuestEN[35162] = { title = "Treasure: Grovestrider Nest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35166] = { title = "Ship Salvage", description = "Commander, we are running low on supplies.\n\nMaybe we can salvage materials from that ship you arrived on?\n\nAt the rate folks are coming through the portal we are going to be out of everything by sundown... or moondown?\n\nI'm still getting used to this place.", objectives = "Collect 15 crates of Drudgeboat Salvage.", progress = "Supplies are getting really low, commander.", completion = "Wow... with all these supplies, we should be back on track.\n\nWe are blessed to have you protecting us, commander." }
WordHunterWoW_QuestEN[35167] = { title = "Lost in Nagrand", description = "Hey, mister, could you help me?\n\nThere's this girl I know. Her name's Olgra. Her and her parents went back to Wor'var yesterday. Only, they never got there and no one's seen them.\n\nIf you're heading back out, would you look for her?\n\nShe's kinda my girlfriend.", objectives = "Find Mankrik's girlfriend, Olgra.", completion = "Skytooth! My mama and papa....\n\n<The little girl continues to cry over the corpses of her family.>" }
WordHunterWoW_QuestEN[35168] = { title = "Your First Blacksmithing Work Order", description = "Now that the forge is complete, we can start producing truesteel ingots for you. When you have the ingredients, please speak with my assistant to start the first work order.", objectives = "Start and collect your first Blacksmithing work order at the Forge.", progress = "Yes?", completion = "Let me unpack that for you.\n\nI should let you know - while we managed to expedite this one, future work orders will take longer." }
WordHunterWoW_QuestEN[35169] = { title = "And Justice for Thrall", description = "The time has come, commander. You've dealt with all of the Warsong's allies and holdings.\n\nOur troops are massing at the gates of Grommashar. The rangari have reliable intel that Garrosh is holed up inside the Warsong fortress.\n\nAll of our efforts have led to this moment. Let's take out Garrosh.", objectives = "Speak with Vindicator Yrel at the Gates of Grommashar and lead the assault on the Warsong.", completion = "It's over. The Warsong are broken. Garrosh Hellscream is finally dead.\n\nSomehow, I sense it's only a matter of time before Grommash seeks vengeance." }
WordHunterWoW_QuestEN[35170] = { title = "Consumed by Vengeance", description = "They... they came out of nowhere. From that direction.\n\n<The young girl points vaguely west through her tears.>\n\nThey were on their nasty wolves.\n\nPlease, commander, my family's honor is at stake. Will you get vengeance for me?", objectives = "Kill Worgskin the Savage.", completion = "Thank you, commander. You really are the greatest <class> like everyone says!" }
WordHunterWoW_QuestEN[35171] = { title = "And Justice for Thrall", description = "The time has come, commander. You've dealt with all of the Warsong's allies and holdings.\n\nOur troops are massing at the gates of Grommashar. The shadow hunters have reliable intel that Garrosh is holed up inside the Warsong fortress.\n\nAll of our efforts have led to this moment. Let's put an end to this once and for all.", objectives = "Speak with Durotan at the Gates of Grommashar and lead the assault on the Warsong.", completion = "It's over. The Warsong are broken. Garrosh Hellscream is finally dead.\n\nIt's just a matter of time before Grommash seeks vengeance." }
WordHunterWoW_QuestEN[35172] = { title = "Your Second Blacksmithing Work Order", description = "Place another work order with my assistant. Once it is complete, we will leave it out here for you to collect.", objectives = "Place a work order, then collect it once it completes. \n\nProgress can be monitored through the Garrison Report pane accessible through the button on your minimap.", completion = "We look forward to serving you again." }
WordHunterWoW_QuestEN[35174] = { title = "Pale Moonlight", description = "We are getting strange reports of an orc attack on a nearby draenei settlement called Eventide Landing.\n\nI'm hearing these particular orcs are unlike any we have encountered before.\n\nThey seem... sickly, and are pale in color.\n\nThe locals could use our help, commander. This seems like the perfect opportunity to test our garrison's capabilities.", objectives = "Kill Gnaw Bloodseeker and 8 Pale Devourers.", progress = "Did you see the pale orcs, commander?", completion = "This is unnerving to say the least.\n\nThose things must have come from underground.\n\nHopefully we have seen the last of them." }
WordHunterWoW_QuestEN[35176] = { title = "Keeping it Together", description = "So much work to do... I don't even know where to start.\n\nMaking sure this garrison is operational is not an easy task.\n\nShelly still hasn't reported back to me, my assistant Brightstone and her crew are who knows where, ugh... I'm so caught up I haven't even had time to check our cache for resources.\n\nIf I were a mage, do you think I could use mirror images to do all of this at once?", objectives = "Speak with Shelly, find Assistant Brightstone, and check the Garrison Cache.", progress = "Can we speak a little later, Sir? I don't really have time to talk at the moment.", completion = "You did what? You are a life saver, commander.\n\nWith those tasks out of the way my job will be much easier." }
WordHunterWoW_QuestEN[35185] = { title = "Garrison Campaign: The Sargerei", description = "Greetings, {name}.\n\nArchmage Khadgar wishes you to hear an important message.\n\nThe draenei suffered a great betrayal when one of their leaders, Exarch Othaar, revealed himself to be working with the Legion.\n\nIn the hills above Shadowmoon Valley, Othaar, who now goes by the name Socrethar, gathers new recruits to his cause.\n\nArchmage Modera is in charge of this covert operation, which we need your help carrying out.\n\nMeet her in the field, and she will give you the details.", objectives = "Speak to Archmage Modera at Socrethar's Rise in Shadowmoon Valley.", completion = "Greetings, <class>. Khadgar told me to expect you." }
WordHunterWoW_QuestEN[35186] = { title = "Garrison Campaign: The Sargerei", description = "Greetings, {name}.\n\nArchmage Khadgar wishes you to hear an important message.\n\nThe draenei suffered a great betrayal when one of their leaders, Exarch Othaar, revealed himself to be working with the Legion.\n\nIn the hills above Shadowmoon Valley, Othaar, who now goes by the name Socrethar, gathers new recruits to his cause.\n\nArchmage Modera is in charge of this covert operation, which we need your help carrying out.\n\nMeet her in the field, and she will give you the details.", objectives = "Speak to Bron Skyhorn for a ride to Shadowmoon Valley.", completion = "Greetings, <class>. Khadgar told me to expect you." }
WordHunterWoW_QuestEN[35187] = { title = "Infiltrating the Sargerei", description = "One of my men has already infiltrated the Sargerei's ranks, but I need you to help him.\n\nIn order to protect his cover, you will need to disguise yourself as one of the enemy.\n\nKill Sargerei until you collect a cowl, robe, and slippers to create a disguise.\n\nAfter donning the disguise, introduce yourself to Soulbinder Zamaya as a new student, then tell Anchorite Laanda that 'the rain falls on Shadowmoon.'\n\nThe secret phrase will identify yourself as an ally.", objectives = "Collect a Sargerei Robe, Sargerei Cowl, and Sargerei Slippers to create a Sargerei Disguise. Don the disguise, then speak to Soulbinder Zamaya and Anchorite Laanda.", progress = "Yes, initiate?", completion = "Welcome, my friend. I have managed to earn a bit of favor with the Sargerei, but they still guard their secrets closely.\n\nOnly the strongest will be accepted in the ranks of the Sargerei.\n\nSoulpriest Zamaya is the leader of our operations here. To secure our objectives, you must first win her trust." }
WordHunterWoW_QuestEN[35188] = { title = "Pesky Podlings", description = "Ah, initiate. Are you ready for your first task?\n\nThe woods to the south are filled with pesky podlings. The filthy things dig up our farms, steal supplies, and prey on unwitting trainees.\n\nThey are disgusting, horrible creatures which need to be eliminated.\n\n<Zamaya gives you a skeptical look.>\n\nI will require their spears as proof that you finished this task.", objectives = "Collect 8 Wooden Spears.\n\nIf you lose your disguise, kill Sargerei enemies to collect a Sargerei Cowl, Sargerei Robe, and Sargerei Slippers to create a Sargerei Disguise.", progress = "Those filthy creatures don't deserve to live.", completion = "I expect no less from an initiate." }
WordHunterWoW_QuestEN[35189] = { title = "The Word of Socrethar", description = "The Sargerei follow Socrethar zealously. From what I can gather, he is a persuasive and compelling leader.\n\nMany of the initiates carry books of his writings.\n\nI need you to read these works and report back to me. If we can understand the Sargerei's motivations, perhaps we can undermine them.\n\nI last saw these books near the lake, on a table near the fountain, and in the house near the gardens.", objectives = "Read \"The Eredar Destiny,\" \"The Purpose of Unity,\" and \"The Promise of Eternity.\"", completion = "I see... Socrethar is purely mad, but his reasoning is logical. No wonder so many draenei are turning to his cause." }
WordHunterWoW_QuestEN[35190] = { title = "An Ancient Threat", description = "To the northwest, an Ancient has settled into a forest glade.\n\nI need someone to take care of this nuisance.\n\nThis should be a simple matter, even for an initiate like you.", objectives = "Kill Eldermoss.\n\nIf you lose your disguise, kill Sargerei enemies to collect a Sargerei Cowl, Sargerei Robe, and Sargerei Slippers to create a Sargerei Disguise.", completion = "Not bad." }
WordHunterWoW_QuestEN[35191] = { title = "Shattering the Enemy", description = "While you carry out the pretense of obeying Zamaya's orders, we're going to sabotage the Sargerei under their very noses.\n\nAll around this village, you can find Felstorm Crystals. The enemy uses these objects to magnify their power.\n\nDestroy these crystals, and we'll slow their operations.", objectives = "Destroy 6 Felstorm Crystals.", completion = "Very good. Our mission continues, undetected." }
WordHunterWoW_QuestEN[35192] = { title = "See Reinforcements Teleport", description = "", objectives = "" }
WordHunterWoW_QuestEN[35193] = { title = "Weapons Of Our Enemies", description = "We are doing well, initiate. We are close to gaining access to the council's chambers.\n\nMeanwhile, our subterfuge will continue. Atop the hill to the northeast, you will find the Sargerei training grounds.\n\nFor months they have been hammering, forging, and crafting the finest weapons to equip into battle.\n\nWe can undo their work in only moments, <name>.\n\nSteal their weapons. Let us see if they can still strike, then.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 4 Sargerei Weapons.\n\nIf you lose your disguise, kill Sargerei enemies to collect a Sargerei Cowl, Sargerei Robe, and Sargerei Slippers to create a Sargerei Disguise." }
WordHunterWoW_QuestEN[35194] = { title = "Facing Demons", description = "Time is running out, {name}. The Sargerei have opened a summoning portal on the hill to the west.\n\nI believe they are going to use this portal to bring an army of demons here, to Shadowmoon Valley.\n\nWe must stop them before this happens, no matter what the cost. Use this arcane bomb to destroy the portal.\n\nWe may blow our cover, but stopping the portal is more important right now.", objectives = "Defeat Invokaz, and destroy the demon gate.", completion = "<Mysteriously, Anchorite Laanda is gone. Did something happen here?>" }
WordHunterWoW_QuestEN[35195] = { title = "Socrethar's Fury", description = "<Upon opening the scroll, you find a message from Anchorite Laanda.>\n\nI write this message hastily. I've been discovered. I'm being taken in front of Socrethar.\n\nYou must carry on our mission. I've learned that Soulbinder Zamaya holds a detailed plan of Socrethar's next attack.\n\nShe still trusts you, so you should be able to enter the main building. Please, find those plans, {name}!", objectives = "Confront Socrethar, then collect the Sargerei Battle Plans from Soulbinder Zamaya.", progress = "Don't worry about me.", completion = "<Anchorite Laanda looks pale. He is not going to make it.>\n\n<name>... thank you for all that you have done." }
WordHunterWoW_QuestEN[35196] = { title = "Forging Ahead", description = "<Anchorite Laanda's voice is barely a whisper.>\n\nYou must report back... to Khadgar.\n\nSocrethar means to take Shattrath. He will... continue to recruit followers... to his side...\n\nThank you for... helping me... in my final hour...\n\nLeave me... I would like to rest...", objectives = "Return to Khadgar's Servant at your garrison.", completion = "I see... Socrethar's ambitions begin with Shattrath and Auchindoun, but they do not end there.\n\nThank you for bringing this information to me, <name>.\n\nI will relay it to Archmage Khadgar immediately." }
WordHunterWoW_QuestEN[35197] = { title = "Forging Ahead", description = "<Anchorite Laanda's voice is barely a whisper.>\n\nYou must report back... to Khadgar.\n\nSocrethar means to take Shattrath. He will... continue to recruit followers... to his side...\n\nThank you for... helping me... in my final hour...\n\nLeave me... I would like to rest...", objectives = "Return to Khadgar's Servant at your garrison in Frostfire Ridge.", completion = "I see... Socrethar's ambitions begin with Shattrath and Auchindoun, but they do not end there.\n\nThank you for bringing this information to me, <name>.\n\nI will relay it to Archmage Khadgar immediately." }
WordHunterWoW_QuestEN[35201] = { title = "Krixel", description = "", objectives = "" }
WordHunterWoW_QuestEN[35202] = { title = "Shells for Xuk", description = "The magics Xuk is weaving will let you perform great acts, but preparations must be made before the spirits will bless us with their power.\n\nXuk needs many shells from the pesky goren. To gather them, Xuk will share a secret.\n\nApproach their tunnel craters and the goren will pour out. This way, you kill many at once.", objectives = "Collect 9 Goren Shells from Boneyard Gorgers.", progress = "Xuk Xuk.", completion = "Ahh, yes. Xuk is one step closer to performing a miracle." }
WordHunterWoW_QuestEN[35203] = { title = "More Materials", description = "Building a garrison is no simple task, and it does not happen without the proper resources.\n\nWe need a lot more materials.\n\nIf you find anything in the field let me know. We need all the help we can get.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 50 Garrison Resources." }
WordHunterWoW_QuestEN[35204] = { title = "Pollen Power", description = "The botani use monstrous insect-like creatures to pollinate their bloom.\n\nThe pollen they carry has a number of powerful properties that would be of use to your garrison forces.\n\nIf you bring me a reserve of this pollen I should be able to convert it to something of value.", objectives = "Collect 20 Potent Pollen.", progress = "Do you have the pollen?", completion = "Keep this up and we'll make a survivalist out of you yet." }
WordHunterWoW_QuestEN[35205] = { title = "Burn the Bodies", description = "You don't understand. Anythin' these plant people don't infest they fatten up and then turn inta mulch.\n\nI say we take out their food source.\n\nThese botani got a few corpses lying around that I saw. Might be a good idea to burn those bodies.\n\nLet's find out if they can infest ash.", objectives = "Burn 6 Mulching Bodies.", progress = "If I survive this, I'm gonna get even by becomin' a vegetarian.", completion = "Normally I'm not a violent dwarf, but I ain't about to sit by and get turned into a bush. And I ain't about to let others do the same." }
WordHunterWoW_QuestEN[35206] = { title = "Bushwhacker", description = "We are continuing the search for Thaelin's people, but these botani, they are a larger threat than we ever realized.\n\nTo infest their victims... monstrous.\n\nPlease, commander, if you find yourself in Evermorn Springs to our west, slay as many of those creatures as you can.\n\nStop them from committing such acts of horror. Bring them to justice.", objectives = "Slay 7 Bloom Weavers.", completion = "Well done, commander. At every turn you seem to demonstrate an efficiency with war that even our most seasoned exarchs might fight to be challenging." }
WordHunterWoW_QuestEN[35207] = { title = "Coalpart's Revenge", description = "I'm so full I can't swing an axe even if I had one.\n\nTell ya what, we got a mutual interest here. I need yer help to get a little vengeance on the big botani at the back of this bloom. In return, I'll point ya in the right direction fer gettin' a secret weapon the botani keep.", objectives = "Slay 3 Dew Masters.", progress = "Me mother always said: \"Burrian! Eat yer veggies!\"\n\nGoing to make her proud today.", completion = "Me mother always told me to eat me vegetables. I dunna think this is what she had in mind." }
WordHunterWoW_QuestEN[35208] = { title = "Dark Iron Down", description = "While you were away our rangari here found more clues leadin' to some of me other friends.\n\nBurrian Coalpart and Scorchbrow.\n\nProblem is, their trail heads right for Evermorn Springs to the west.\n\nPlease Commander, will ya get in there and save them from mulching?", objectives = "Find Burrian Coalpart in Evermorn Springs.", completion = "Ah! It was terrible! They made me eat an' eat an' eat.\n\nDon' get me wrong, I enjoy a good meal but these plant people had me eatin' nuthin' but fruit.\n\nI canno' take it anymore." }
WordHunterWoW_QuestEN[35209] = { title = "The Life Spring", description = "So we came here cause we needed a weapon we saw the botani using.\n\nHansel grabbed the artifact an' Scorchbrow an' I were supposed to grab the special water the thing runs on.\n\nWe didn't know that water so full of life forms an elemental.\n\nIf ya mosey up to the cauldron at the base of that fancy lookin' ancient artifact in Evermorn Springs, you'll be findin' this beast. If ya can kill it and get its water, we can use it when we get the rest of the artifact.", objectives = "Collect Waters of Utrophis.", progress = "Now I see why some become Rangari. This is exciting.", completion = "You are carrying something of great power on you. I could feel it as you approached." }
WordHunterWoW_QuestEN[35210] = { title = "A Great Escape", description = "A goren tunnel!\n\nOnce the cap is cleared, it's certain to lead outside of this Light-forsaken pit.", objectives = "Clear the goren tunnel and use it to meet with Rexxar outside the Fissure of Fury.", completion = "Those goren tunnels have proven useful." }
WordHunterWoW_QuestEN[35211] = { title = "Preventing the Worst", description = "Have you seen all the fungus on the buildings in Pinchwhistle Point? It's only a matter of time 'til it releases enough spores to infest the whole coastline!\n\nThe remaining infected that are in Pinchwhistle Point will be too far gone for us to save later on, so let's do the right thing and put them out of their misery and prevent an even worse outbreak.\n\nI made some firebombs that will burn the fungus down, but I'll need you to place them while I set up the detonator.\n\nAre you up for it?", objectives = "Place 5 Firebombs within Pinchwhistle Point.", progress = "I'm almost done here. Have you placed all those firebombs yet?", completion = "Good work!\n\nOk I need to just finish setting up the ignition mechanism and we'll be all set." }
WordHunterWoW_QuestEN[35212] = { title = "Deeproot", description = "Since yer all set up to take on trees and bushes now, I need ta ask for a favor.\n\nI came to Gorgrond in search of an expedition of me fellow Dark Irons that were headed this way. Sadly I lost 'em.\n\nI am goin' south to look for them. Thing is, south is nothing but botani, podlings, giant trees, and other mean, angry plants.\n\nYer lumber camp resources would be mighty appreciated. If ya help me look for me friends I swear we'll help ya in any way we can.", objectives = "Meet Thaelin Darkanvil at Deeproot.", completion = "Ah good! Ya made it.\n\nThe lasses here insisted on comin' with, though they don't seem to like each other much." }
WordHunterWoW_QuestEN[35213] = { title = "The Razorbloom", description = "Kaalya thinks she picked up a trail. Seems a bunch of dwarves went north to Razorbloom by the signs.\n\nProblem is that place is filled with plant people. I ain't much use against plant people.\n\nAre you willing to investigate?", objectives = "Find clues to the whereabouts of Lera Ashtoes, Nori Sootstache, and Razzlebeard.", completion = "The plant people fattened up my friends with fruit an' honey an' mead. Seems they were fattenin' them up for sure." }
WordHunterWoW_QuestEN[35214] = { title = "The Infested", description = "D'kaan did not say it, but there were more rangari taken by the botani than the ones you found.\n\nHe believes they were slain. I fear worse.\n\nYou might dare to venture into the Razorbloom. If you do, you may discover what the botani do to their... \"prisoners.\"\n\nGive these poor souls a proper release.", objectives = "Slay 6 Infested.", progress = "One truth of Gorgrond: death is not the worst thing that can happen to you.", completion = "I thank you for doing what I could not.\n\nWhile it is the right thing to do, it is hard to loose the arrow when your target was once a friend." }
WordHunterWoW_QuestEN[35215] = { title = "The Voice of Iyu", description = "Journal Entry 25 -\n\nThe botani got themselves a leader who calls himself... er... herself... er... itself the Voice of Iyu.\n\nSeems the botani see the genesaur as gods and only the most bossy of the botani get to speak on behalf of the genesaur.\n\nWhen we tried askin' it about the artifact we found back at the base it got all angry and sent off Lera and Nori and I ain't seen either of them since.\n\nI got a bad feelin' about this thing.", objectives = "Slay the Voice of Iyu.", completion = "They mulched my friends? Those pointy branch wavers with their wee beady eyes! Thank ya for avenging ma friends.\n\nWe best be findin' the others before they get turned into plant food." }
WordHunterWoW_QuestEN[35216] = { title = "Super Seeds", description = "These seeds have been shielded with care by the botani.\n\nGreat power can be felt surging out of these tiny vessels of life.\n\nThese may prove useful.", objectives = "Collect Enriched Seeds.", progress = "What have ya found?", completion = "I may not know much about farmin' but I do know a power source when I see it. These seeds are packin' quite a punch.\n\nWay to think on yer feet and grab 'em, Commander." }
WordHunterWoW_QuestEN[35217] = { title = "Pearing It Up", description = "While you do Zamaya's work to earn her favor, we will secretly be sabotaging the Sargerei operation.\n\nIn the forests to the northwest, the podlings have gathered stolen pears from the farms. The little pests go crazy for the stuff.\n\nThe pears also happen to be a main food source for the Sargerei, so naturally, we're going to destroy the harvest.\n\nThat should take care of the podlings AND the draenei at the same time.", objectives = "Destroy 10 Sugar Pears.\n\nIf you lose your disguise, kill Sargerei enemies to collect a Sargerei Cowl, Sargerei Robe, and Sargerei Slippers to create a Sargerei Disguise.", completion = "Excellent! I admit I love the taste of those pears as well, but it is a small price to pay to destroy our enemy." }
WordHunterWoW_QuestEN[35218] = { title = "Iron Horde Orders", description = "Spirit spotted some orders at the Iron Horde camp on the nearby bluff. You must have missed them when you were there. Could you look into it?", objectives = "Look for weaponization orders at the Iron Horde camp in Crushfang's End.", completion = "These orders are written with terrible handwriting." }
WordHunterWoW_QuestEN[35219] = { title = "Vignette: Burning Front", description = "", objectives = "" }
WordHunterWoW_QuestEN[35220] = { title = "Vignette: Kharazos the Triumphant", description = "", objectives = "" }
WordHunterWoW_QuestEN[35221] = { title = "Da Keeper", description = "", objectives = "" }
WordHunterWoW_QuestEN[35222] = { title = "Firing the Mayor", description = "The bottle has a large stopper in it with the label \"Property of Mayor Nurg Boltsnap.\"\n\nAs you gaze at the bottle you hear the sound of heavy machinery coming from the nearby marshland. \n\nAn investigation would be prudent. If the mayor has turned he will also need to be put down.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill Mayor Nurg Boltsnap." }
WordHunterWoW_QuestEN[35225] = { title = "A Heavy Helping Hand", description = "Burrian gave us the coordinates of the Dark Iron base. They named it Moira's Reach.\n\nBut half way through buildin' it the base got infested with goren.\n\nIf you head south you should come to the structure. Just look for a big ol' cannon.\n\nWe will follow as soon as we get this bloody tank untangled.", objectives = "Find Dark Iron Dwarf survivors.", completion = "Co... Commander? Well ain't you a sight for sore eyes?\n\nI didn't think anyone friendly was comin' for me.\n\nWe found an artifact that seemed pretty handy against the locals in the area but then those acid-mouthed roly polies showed up and started eatin' everything.\n\nHelp me up an' we can git to it." }
WordHunterWoW_QuestEN[35226] = { title = "Old Friends, New Enemies", description = "I cannot believe Orgrim would continue to do Blackhand's bidding after all the destruction he has wrought.\n\nWe must confront him. Join me at the village along Orunai Coast and we will confront my oldest friend.", objectives = "Confront Orgrim Doomhammer at the village along Orunai Coast.", completion = "Orgrim will not stop this foolishness, so we must stop him." }
WordHunterWoW_QuestEN[35227] = { title = "Ogre Diplomacy", description = "Ogres are ogres. Spirits or not, the Ango'rosh are not different.\n\nEven with their ritual books, they won't relinquish their power to you until you prove yourself.\n\nI've fought ogres my entire life, and there's only one way to earn that.\n\nKilling them outright.\n\nThe more Ango'rosh spirits and their pets as you take out while you're there, the more respect you'll command among them.", objectives = "Kill 10 Ango'rosh in the Ango'rosh Ruins.", progress = "I hope you've extended our diplomatic hand to our ogre friends.", completion = "Another successful negotiation." }
WordHunterWoW_QuestEN[35228] = { title = "Firing the Mayor", description = "Ever since this zombie outbreak began I haven't seen the mayor at all. If he is infected then we could be in for a huge problem if he can escape out of town. Damn, we could be in for another zombie outbreak even!\n\nWe got to find him and make sure he doesn't escape! He used to ride in his custom shredder down on the shore line before the fungus started covering up everything. You might find him down there.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill Mayor Nurg Boltsnap." }
WordHunterWoW_QuestEN[35229] = { title = "Down the Goren Hole", description = "These beasts came at us so fast we didn't have time to mount a proper defense. They went right for the metal and chewed through any wall we had.\n\nIf we don't kill some of them soon they'll bring the whole fortress down on us.", objectives = "Slay 5 goren in Moira's Reach.", progress = "All in a day's work, eh Commander?", completion = "You give me blackrock orcs, troggs, er evil leper gnomes an' we'd be fine. But these acid munchin' beasts are the end of us." }
WordHunterWoW_QuestEN[35231] = { title = "Spiritual Matters", description = "The spirits of the dead have long been drawn to Oshu'gun.\n\nAs long as I can remember, the woods have been filled with ancestral spirits making a ghostly pilgrimage to the heart of the mountain.\n\nHowever, I fear that what is transpiring here is not the normal spirit walk I have seen before.\n\nMake your way to the Ancestral Grounds and commune with the spirits there for guidance on this matter.", objectives = "Speak with the spirits at the Ancestral Grounds.", completion = "The situation here is dire, <name>, but I sensed that we would meet again.\n\nI do not hear the call of the void as loudly as the others, for I am not long dead and my body rests far from this place.\n\nWith time though, that will change.\n\nIf you are here to help, listen closely for time is short." }
WordHunterWoW_QuestEN[35232] = { title = "The Call of Oshu'gun", description = "The elements have spoken and a vision has been revealed, {name}.\n\nTogether we shall travel to the great mountain Oshu'gun and put an end to the dark disturbance there.\n\nIf what you saw in the vision is to be believed, then great danger awaits us.\n\nI will meet you in the Spirit Woods at the foot of Oshu'gun. When you are ready to depart, speak with Gixmo Moneycash and he will fly you there.", objectives = "Fly to the Spirit Woods.", completion = "It has been many years since I have set foot within these woods.\n\nI was last here for the Kosh'harg many years ago when this place was shared amongst all clans. Those days have past and now only the Warsong banner flies here." }
WordHunterWoW_QuestEN[35233] = { title = "Just In Case", description = "When we set up shop the first thing we built was the cannon. Seemed like a good place fer it.\n\nWe started buildin' the base up around it when them chompin' acid spittin' varmints came crawlin' out of the ground.\n\nThe upside though is the cannon is built, just not loaded.\n\nWe have to go down to the bottom floor of this thing anyway so may as well grab some Doomshot if you see any on your way down.\n\nBetter to load the cannon and not need it than to need it and not have it loaded.", objectives = "Collect Doomshot.", progress = "Ya got that ammo?", completion = "While I hope we don' need to fire the big gun, I kinda hope we can fire the big gun." }
WordHunterWoW_QuestEN[35234] = { title = "Will of the Genesaur", description = "When the goren attacked we threw everything we had at them but they just kept comin'.\n\nSo some of the lads went and stole a fancy artifact from the botani.\n\nProblem was we couldn't get it to work. Now the artifact is sitting at the bottom of the bastion. To get to it you got to go all the way to the back of the tunnels past all them goren and find the wee tunnel that takes you farther underground.\n\nIf you retrieve it, it is yours.", objectives = "Recover the Will of the Genesaur.", progress = "Not fond of this place. If the plants ain't tryin' to kill you then the ground is tryin' to swallow ya up.", completion = "That artifact was useful until it ran out of juice. Hopefully you got some seeds and water for it." }
WordHunterWoW_QuestEN[35235] = { title = "Iyu", description = "Did ya hear that?\n\nSounds like that genesaur wants its 'will' back. I told ya this place is nuthin' but bad luck.\n\nI'll git that shot ya gave me loaded properly and see if I can't weaken that thing up. You better get up there and deal with it though...", objectives = "Defeat Iyu.", progress = "How goes your search?", completion = "That was a challenge." }
WordHunterWoW_QuestEN[35236] = { title = "Orunai Coast", description = "", objectives = "" }
WordHunterWoW_QuestEN[35237] = { title = "Mor'gran Logworks", description = "", objectives = "" }
WordHunterWoW_QuestEN[35238] = { title = "New Owner", description = "", objectives = "Battle-Bot 8000 owner acquired: <name>.\n\nCurrent desire: Massage <name>'s enemies... to death." }
WordHunterWoW_QuestEN[35239] = { title = "New Owner", description = "", objectives = "Battle-Bot 8000 owner acquired: <name>.\n\nCurrent directive: Massage <name>'s enemies... to death." }
WordHunterWoW_QuestEN[35240] = { title = "Bled Dry", description = "<The draenei spits out his last words.>\n\nThey kept us in cages. They... drain our blood, for... rituals...\n\n<He coughs violently.>\n\n...many left --\n\n    -- my... people...\n\n<The draenei dies.>", objectives = "Free the slaves from the 2 Bleeding Hollow Cages in Heartblood.", progress = "You should save those draenei, <name>. It is the right thing to do.", completion = "Well done, <name>.\n\nGiven, they are injured, half-starved, and poorly-equipped... but there is no blade so sharp as a vengeful spirit, no armor so thick as a righteous cause." }
WordHunterWoW_QuestEN[35241] = { title = "Vengeance for the Fallen", description = "Too many of my people have fallen at the hands of the Bleeding Hollow. Their cruelty cannot be forgiven.\n\n<The grieving orc looks up at you.>\n\nMake them pay.", objectives = "Slay 6 Bleeding Hollow orcs.", completion = "I admire your sense of duty, <name>. Even when your own survival hangs in the balance, you still find time to bring closure to a grieving widow. Well done." }
WordHunterWoW_QuestEN[35242] = { title = "Vengeance for the Fallen", description = "Too many of my people have fallen at the hands of the Bleeding Hollow. Their cruelty cannot be forgiven.\n\n<The grieving draenei looks up at you.>\n\nMake them pay.", objectives = "Slay 6 Bleeding Hollow orcs.", completion = "I admire your sense of righteousness, <name>. Even when your own survival hangs in the balance, you still find time to avenge a grieving widow. Well done." }
WordHunterWoW_QuestEN[35243] = { title = "The Dark Lady's Gift", description = "", objectives = "I was bidden to find my way to you, and to swear my service. Whatever you need of me, I will offer. I take a particular pleasure in turning things to ashes.\n\nThe dark lady sends her regards." }
WordHunterWoW_QuestEN[35244] = { title = "Vignette: Skagg", description = "", objectives = "" }
WordHunterWoW_QuestEN[35245] = { title = "A Sentimental Relic", description = "My father's bangle sat here for ages before that imposter Ikiss stole it away.\n\nI thank you for returning it, but I have no need for keepsakes. Take it, with my blessing.\n\nIf there are still Talonpriests loyal to the true Talon King, please bring it to them.", objectives = "Bring Lithic's Gift to Reshad in Veil Terokk.", progress = "Hm? What's that you have there?", completion = "Lithic actually spoke to you? Or, some shade of her at least... \n\nFascinating!" }
WordHunterWoW_QuestEN[35247] = { title = "Zero Xuks Given", description = "The spirits have spoken to me. They believe the magnaron, Gro the Uncreator, will join our fight and lead his underlings against the Iron Horde.\n\nThis is an honor beyond any bestowed upon a Laughing Skull, at least in my time.\n\nI will commune with the magnaron, and together we shall destroy the Iron Horde.", objectives = "Speak with Bony Xuk to observe him communing with Gro the Uncreator.", completion = "The spirits of my ancestors have betrayed me! Their skulls are surely laughing." }
WordHunterWoW_QuestEN[35248] = { title = "A Harsh Reminder", description = "Welcome to the front lines, outsider, where the wastelands and the jungle collide.\n\nWhen their forces forget about the ferocity of the Laughing Skull, this is where we come to make them remember.\n\nBy fierce and merciless destruction we survive. This is the way of Gorgrond.\n\nJoin in! Let us see if you can withstand the brutality of our land.", objectives = "Kill 8 denizens of the wasteland in Affliction Ridge.", completion = "I like killing things. And bones." }
WordHunterWoW_QuestEN[35249] = { title = "Powering the Defenses", description = "It's good to see a Horde champion joining the fight.\n\nAuchindoun's defenses are faltering quickly. The few Auchenai soulpriests not on the front are working fervently to maintain them.\n\nSoulbinder Tuulani went inside the nearby Tomb of Lights to retrieve a backup power pylon and hasn't returned. If you can find her and get her and the pylon back here safely it would help greatly.", objectives = "Find Soulbinder Tuulani in the Tomb of Lights.", completion = "You look like you can fight. We need to get out of here!" }
WordHunterWoW_QuestEN[35250] = { title = "Test Quest", description = "[PH]", objectives = "" }
WordHunterWoW_QuestEN[35251] = { title = "The Bounty of Bladespire", description = "The sacking of this fortress is as much your victory as ours. It is only fair you should share in the bounty.\n\nI had the men prepare a chest for you. Take what you will.", objectives = "Take your share of the plunder from Durotan's chest.", completion = "This camp of yours could be fruitful, but it rests upon the footstep of Grom'gar. The Thunderlords are not likely to be welcome neighbors." }
WordHunterWoW_QuestEN[35252] = { title = "Chest Reward Tracking Quest", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[35253] = { title = "FLAG: Thaelin Event Complete", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[35254] = { title = "Retribution for the Light", description = "There are agents of darkness everywhere, fighting tooth and nail to envelop the world. The Light relies on us to balance the scale.\n\nYou have the power needed to destroy Teron'gor's demonic minions once and for all. Send them to the Twisting Nether in pieces!", objectives = "Kill 15 demons in Gul'rok.", completion = "Already I can feel the Light triumphing over darkness. We've done it!" }
WordHunterWoW_QuestEN[35255] = { title = "Power of the Genesaur", description = "Commander, you now have the Will of the Genesaur along with the genesis water and enough seeds to grow an army. Not to mention the lives of the dwarves you saved.\n\nI would call this mission a success.\n\nI can help the dwarves mop up their operation here and see what we can salvage. In the meantime, you may want to bring the artifact to Maraad back at the outpost.", objectives = "Speak with Vindicator Maraad at Highpass in Gorgrond.", completion = "Well done, Commander. Many of the orcs have tried to master the power of the genesaur but I have never heard of any of them reaching this level of success.\n\nThis should provide us a substantial advantage in the days ahead." }
WordHunterWoW_QuestEN[35256] = { title = "A Heart Unbroken", description = "Though Gordawg's body lays shattered and lifeless upon the ground, a crystal heart glows brightly. The large crystal appears to be fully intact and all that remains of the mighty earthen fury.\n\nPerhaps Kalandrios will know what to make of the crystal.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Deliver the Heart of the Fury to Kalandrios.Though Gordawg's body lays shattered and lifeless upon the ground, a crystal heart glows brightly. The large crystal appears to be fully intact and all that remains of the mighty earthen fury.\n\nPerhaps Kalandrios will know what to make of the crystal.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[35257] = { title = "Power Unearthed", description = "What power could reduce a village to ashes in the blink of an eye? The Adherents claim it is the will of Rukhmar.\n\nA lie, obviously.\n\nThey did nothing to earn such power - in truth, they stumbled upon it rather unwittingly, in a hole in the ground.\n\nCome and visit me near the excavation site just west of here. We must understand their technology if we are to defeat it.", objectives = "Speak with Darkscryer Raastok near the Apexis Excavation.", completion = "Ah yes, you've arrived just in time." }
WordHunterWoW_QuestEN[35258] = { title = "Legacy of the Apexis", description = "The Apexis are long gone, but their legacy lies preserved in ancient chambers beneath Arak.\n\nLegions of dormant constructs; crystals flush with solar energy; magical techniques lost to the ages - the Apexis left behind caches of immense power, which the Adherents of Rukhmar have begun to unearth.\n\nBring me the cores of the re-activated constructs patrolling the excavation site. Those crystals are the basis of Apexis technology, and the key to our enemy's devastating power.", objectives = "Gather 5 Solar Cores from Apexis Guardians.", progress = "The Apexis had every advantage, and yet they vanished. What could have happened?", completion = "Excellent. With these we can begin to understand." }
WordHunterWoW_QuestEN[35259] = { title = "Sol Sisters", description = "When I was still a guard in Skyreach, I was tasked with protecting the sisters Veoryx and Krashyx.\n\nThey were prodigies. At an age when most sun acolytes could barely read, the sisters conjured familiars of pure sunlight to illuminate their textbooks in the small hours.\n\nNow they unravel the secrets of Apexis technology, and their excavation has just breached two ancient chambers.\n\nEnter those chambers and cut down the sisters before they reap the terrible rewards of their discovery.", objectives = "Slay Sol-Shaper Veoryx and Sol-Shaper Krashyx.", progress = "<The Sol-Shapers are using their power to awaken these ancient Apexis constructs.>", completion = "<The core of this slumbering construct begins to hum softly.>" }
WordHunterWoW_QuestEN[35260] = { title = "Hardly Working", description = "Those who were not incinerated at Veil Akraz are forced to help the Adherents excavate the very weapons aimed at their heads.\n\nAnyone trying to escape is vaporized by the overseer's Apexis turret.\n\nWith these effigies, they won't know anyone has left! Place one near an enslaved worker and observe as it creates a perfect copy. It even cloaks the subject in shadow, so they can slip away safely!", objectives = "Use Illusion Effigies to create decoys for 10 Enslaved Outcasts.", completion = "Deception is the ultimate power. Remember this, <name>." }
WordHunterWoW_QuestEN[35261] = { title = "Shot-Caller", description = "<Solar energy courses through the slumbering constructs, their ancient servos whirring to life all around you. It is too late to shut them down now.\n\nOutside, an arakkoa overseer bellows commands, each answered by the buzz of an Apexis beam carving away at the mountain.\n\nThat turret would make short work of the constructs - if you can command it.>", objectives = "Retrieve the Apexis Interface from Overseer Akrath.", progress = "<A comfortable-looking chair with a socket in the arm rest.>", completion = "<The Apexis interface slides into place with a satisfying click. Seems this is the seat for taking full command of the turret.\n\nRifling through the cushions, you find a few spare coins, which you pocket.>" }
WordHunterWoW_QuestEN[35262] = { title = "Service of Rangari Kaalya", description = "", objectives = "Commander, your skills at survival are to be commended but they have many blind spots.\n\nYou need a rangari like myself to help your forces or Draenor is going to eat you up like a goren with a rock.\n\nWill you accept my offer?" }
WordHunterWoW_QuestEN[35264] = { title = "A Bunch of Artifact Fragments", description = "", objectives = "The more, the better!", progress = "The more, the better!", completion = "That must of taken great effort to get back to us. You deserve this reward, friend." }
WordHunterWoW_QuestEN[35265] = { title = "The Ritual of Binding", description = "The time has come for you to undertake the Ritual of Binding, {name}.\n\nThis ancient, shamanic rite has been practiced since long before I was born. To be chosen is a great honor.\n\nMany shaman see vivid elemental visions during the rite; experiencing this world through the very elemental bonds that hold it together.\n\nWhen you are ready, speak with Kalandrios to begin the rite.", objectives = "Speak with Kalandrios to begin the Ritual of Binding.", progress = "Tell me of your vision, <name>. What did the elements reveal?", completion = "<Farseer Drek'Thar listens closely as you speak of your vision.>\n\nI see... these are truly dark days. Cho'gall has invaded the heart of Oshu'gun, draining the naaru of its life. He seeks to destroy the naaru, birthing a dark, void god in its place.\n\nCho'gall must be stopped. Come, we must travel to the sacred mountain before it is too late." }
WordHunterWoW_QuestEN[35266] = { title = "Boosted Character", description = "", objectives = "" }
WordHunterWoW_QuestEN[35267] = { title = "Ashran Test", description = "", objectives = "" }
WordHunterWoW_QuestEN[35271] = { title = "The Warsong Threat", description = "<The attack plans are scrawled onto the parchment in thick, black ink and bound in rough leather.>\n\nTo all outrider stations:\n\nThe warlord has commanded that all outriders prepare for a full assault upon the Horde invaders in our land. Plans for the attack have been delivered to several of the remote outrider posts.\n\nBlood and glory shall be ours as we trample the Horde invaders beneath our feet!\n\nThe warlord commands and the Warsong obey! Lok'tar ogar!", objectives = "Steal the Warsong Attack Plans.", progress = "What do you have for me?", completion = "<Blood Guard Ehanes looks over the attack plans.>\n\nHmm... I see. You have done well to retrieve these attack plans. With the plans in our hands, we will be more than prepared to counter the assault when it comes." }
WordHunterWoW_QuestEN[35272] = { title = "One of Our Own", description = "Da bird-men captured me while I was gettin' da lay a da land.\n\nWe been workin' on an outpost for you just round dis mountain so your will be spreadin' all over da continent.\n\nThings not be goin' well.\n\nI be needin' your assistance, commander. Can you tell dem that I mean no harm so I can be showin' you da outpost?", objectives = "Speak to Shadow-Sage Iskar and convince him to let Shadow Hunter Ukambe free.", progress = "You be savin' my hide, commander.", completion = "Thank da spirits you showed up. Dey hear my prayers." }
WordHunterWoW_QuestEN[35273] = { title = "Hot Seat", description = "<Apexis constructs are about to emerge from their ancient chambers on a warpath. The arakkoa are sure to send more sol-shapers to support them.\n\nThe interface and the turret hum in soft resonance.>", objectives = "Use the Overseer's Chair to take control of the Apexis Turret and slay 20 Apexis Destroyers and 30 Adherent Sol-Shapers.", completion = "Ahh, well done. Even with my condition, I could sense the carnage from here.\n\nIt must have been quite a show, kah-hah-haww." }
WordHunterWoW_QuestEN[35274] = { title = "One of Our Own", description = "These wretched creatures captured me while I was scouting the area. Now that you're here, commander, we could really use your help back at base.\n\nOh, and any way you could convince your... friends... to let me go?\n\nThey, uh... won't let me leave.", objectives = "Speak to Shadow-Sage Iskar and convince him to let Jasper Fel free.", progress = "I had really hoped to have given you a better impression when you came out here.", completion = "Now, uh... could we maybe forget this little incident happened, commander?\n\nBodrick and the other agents would never let me live this down." }
WordHunterWoW_QuestEN[35275] = { title = "Inspecting the Troops", description = "Axefall be just a moment's ride from here.\n\nI be markin' da location on your map and meet you dere.", objectives = "Speak to Shadow Hunter Ukambe at Axefall.", completion = "Our lives for your will, commander." }
WordHunterWoW_QuestEN[35276] = { title = "Inspecting the Troops", description = "Southport lies not far from here to the southwest.\n\nNo time for chit-chat. I will meet you there, commander.", objectives = "Speak to Jasper Fel at Southport.", completion = "I hope everything is to your liking. It's been one hell of a job." }
WordHunterWoW_QuestEN[35277] = { title = "Orders, Commander?", description = "Commander, our status report is... regrettable.\n\nWe'll be out of supplies in a few days' time, and that's assuming we have any troops left by then. \n\nThere's just enough material left to put up an inn or a trading post.\n\nThe inn would allow us to station fresh troops here, but the trading post would open up potential supply routes with the outcasts nearby.\n\nI've left out Gazlowe's blueprints on the drafting table. We await your will.", objectives = "Inspect the Drafting Table and choose which outpost structure to construct.", progress = "Have you made a choice, commander?\n\nGive the word and it will be done.", completion = "Your will be done.\n\nFor the Horde!" }
WordHunterWoW_QuestEN[35279] = { title = "Treasure: Shadowmoon Treasure 01", description = "", objectives = "" }
WordHunterWoW_QuestEN[35280] = { title = "Treasure: Shadowmoon Treasure 02", description = "", objectives = "" }
