WordHunterWoW_QuestEN[35293] = { title = "Old Friends", description = "Admiral Taylor was ordered to establish a garrison inland while we erected yours in Shadowmoon Valley. He settled just a short ways north of here.\n\nThe two of us could go there and borrow some supplies to tide us over before our next shipment.\n\nWhat do you say, commander? I'm sure the admiral will be thrilled to see you again.", objectives = "Speak to Jasper Fel at Admiral Taylor's Garrison.", completion = "What in the king's name happened here?" }
WordHunterWoW_QuestEN[35294] = { title = "Jasper Moves", description = "", objectives = "" }
WordHunterWoW_QuestEN[35295] = { title = "What's Theirs is Ours", description = "I found somethin' else while I was scoutin', boss.\n\nDa Alliance have a garrison just across da way, and der been no movement in or out of da place in a good while.\n\nDis be a golden opportunity to sack da place and bolster your coffers, commander.\n\nWhat do ya say? We do it together.", objectives = "Speak to Shadow Hunter Ukambe at Admiral Taylor's Garrison.", completion = "Everyone be dead, mon. What did dis?" }
WordHunterWoW_QuestEN[35296] = { title = "Tainted Garden", description = "The abandonded mine shaft has been overrun with Goren!  They seem to be responding to commands from a big one further down in the mine.  If you can take him out, the rest will probably retreat.\n\nOnce you have those Goren cleared out, we can get that mine up and working!You will learn:", objectives = "Kill Stonetooth in the Garrison Mine." }
WordHunterWoW_QuestEN[35297] = { title = "FLAG: Army Pushed", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[35298] = { title = "Flame On", description = "Alright {name}, we've saved as many as we could but now we need to make sure this disaster doesn't spread any further.\n\nThe firebombs are wired up and ready to go.\n\nKimzee just finished work on the flying machine so we're ready to ride back to the Gearworks as soon as we're finished.\n\nYou've done all the hard work so I think you should get the honors of triggering it.", objectives = "Use the Firebomb Plunger then ride on Kimzee's Flying Machine.", completion = "<name>, you did fantastic work.\n\nEveryone here at the Gearworks owes you big time for what you've done for us.\n\nHere, I want to give you little something. Think of it as a personal token of my gratitude." }
