WordHunterWoW_QuestEN[35317] = { title = "The Dark Heart of Oshu'gun", description = "We are not far from the inner chamber, {name}. The truth behind the evil here awaits us.\n\nI can project my spirit into the chamber to guide you, but it will be up to you to defeat the evil that lays within.\n\nMay the wind of Kalandrios guide your arm, the wisdom of Aborius enlighten your faculties, and the flame of Incineratus burn your enemies.\n\nMay the memory of Gordawg be your shield.", objectives = "Enter the Sanctum of the Naaru.", completion = "You have done well, <name>.\n\nBy defeating the void god Decimatus, the destruction of this great valley has been avoided. The threat of the pale has subsided for now as well.\n\nThe loss of Gordawg will be felt throughout Nagrand, but someday a new earthen fury will take seat upon the Throne of Elements and balance will be restored." }
WordHunterWoW_QuestEN[35318] = { title = "Mogu'shan Palace Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35319] = { title = "Shado-Pan Monastery Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35320] = { title = "Shado-Pan Monastery Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35321] = { title = "Mogu'shan Palace Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35322] = { title = "I See Dead People", description = "Everybody here be... dead.\n\nDis architect's spirit not be wantin' to fight us. Even in death he only be wantin' to work. Maybe we can break da haze over him and get to da bottom of dis.\n\nI bet one of da spectral laborers be havin' one of his schematics we can show to him to clear his mind.", objectives = "Retrieve Bryan Finn's Schematic from Spectral Laborers.", progress = "I'd recognize one of my schematics anywhere.", completion = "Thank you, friend." }
WordHunterWoW_QuestEN[35323] = { title = "Stormstout Brewery Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35324] = { title = "Stormstout Brewery Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35325] = { title = "Temple of the Jade Serpent Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35326] = { title = "Unused", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[35327] = { title = "Temple of the Jade Serpent Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35329] = { title = "I See Dead People", description = "Th... they're ghosts! All of them!\n\nBryan was one of my best friends. Something is clouding his mind; we need to snap him out of it and get to the bottom of this!\n\nHe was always obsessed with his work. Maybe showing him one of his schematics would help. One of the spectral laborers might have one.", objectives = "Retrieve Bryan Finn's Schematic from Spectral Laborers.", progress = "I'd recognize one of my schematics anywhere.", completion = "Thank you, friend." }
WordHunterWoW_QuestEN[35330] = { title = "The Ritual of Binding", description = "It is time for you to undergo the Ritual of Binding, {name}. I will wait here as you speak with Kalandrios to begin the rite.\n\nDuring the ritual, you will experience the vision of the elements. Return to me when the ritual is complete, and we will speak more.", objectives = "Speak with Kalandrios to begin the Ritual of Binding.", progress = "Speak to me of your vision, <name>. What mysteries did you behold?", completion = "<Vindicator Nobundo listens closely as you speak of your vision.>\n\nThese are grave images of which you speak, <name>! If Cho'gall continues bleeding the naaru of its Light, K'ure will die and in the naaru's place a void god will emerge. Void gods are terrible creatures that live only to destroy!\n\nWe must travel to Oshu'gun immediately and put a stop to the threat of Cho'gall!" }
WordHunterWoW_QuestEN[35331] = { title = "Called to the Throne", description = "I was far from here in Talador when the voice called out to me.\n\nI looked around but found myself alone. Again, I heard the voice as if it were a breeze in my mind.\n\n\"You are needed at the throne,\" it whispered.\n\nThe voice called itself Kalandrios, and it guided me to this place.\n\nI had never been here before, nor had I yet beheld these furies with my eyes; yet this feels strangely familiar to me as if it happened long ago in a forgotten dream.\n\nWe should greet the furies and hear them out.", objectives = "Commune with the furies at the Throne of Elements.", progress = "Are you ready to commune with the elemental spirits of the throne?", completion = "I am not sure what to make of this.\n\nThe elements are no longer in balance? The great fury Gordawg is missing and must be found?\n\nThe furies appear noble, and deep within my soul their words ring true.\n\nI believe we aid should them in their cause." }
WordHunterWoW_QuestEN[35332] = { title = "Nobundo Sends Word", description = "Your presence has been requested at the Throne of Elements, {name}.\n\nVindicator Nobundo has heard the call of the furies upon the wind and made the journey to commune with the elements.\n\nI know not what the intentions of the furies are, but they are revered as noble and powerful spirits by the orcs.", objectives = "Find Vindicator Nobundo at the Throne of Elements.", completion = "I am glad to see that you have arrived safely.\n\nCome, there is much work to be done here." }
WordHunterWoW_QuestEN[35333] = { title = "Elemental Attunement", description = "Even now, as we speak, the voice of Kalandrios continues to whisper to my mind.\n\n\"The Hero of Azeroth must attune to the elements of the plateau.\"\n\nUpon the Elemental Plateau are four great pillars carved of living rock. Lay your hands upon the stone pillars and your soul will be attuned with the elements.\n\nI will continue to commune with the great furies and attempt to further understand their will while you journey to the plateau.", objectives = "Attune to the four elemental pillars.", completion = "I see a fire within your eyes and a wind upon your step, <name>.\n\nIf what Kalandrios speaks is true, you have attuned your life energy with each of the elemental forces on Draenor.\n\nThe voice says that you are now ready to undertake the Ritual of Binding.\n\nReturn to me when your work upon the plateau is finished and we will speak further." }
WordHunterWoW_QuestEN[35334] = { title = "Vignette: The Egg of Varasha", description = "", objectives = "" }
WordHunterWoW_QuestEN[35335] = { title = "Vignette: Bashiok", description = "", objectives = "" }
WordHunterWoW_QuestEN[35337] = { title = "That Pounding Sound", description = "Commander. The rangari and I were just discussing the merits of various 'hunting' approaches.\n\nI assured her that the SI:7 are well-equipped to deal with any situation, even ones out in the wild.\n\nShe seems to think that we don't know what we're doing when it comes to bringing down game in 'her land.'\n\nWe're not going to let her get away with saying that, right? Let's take down some clefthoof.", objectives = "Collect 12 Pairs of Leatherhide Ears from Leatherhide clefthoof.", progress = "It's unbelievable how arrogant these rangari can be.", completion = "Twelve pairs, huh? That's pretty good, commander.\n\nUm, no, I think that's about how many I managed to bag. Yeah... about a dozen pairs of ears. Yep...." }
WordHunterWoW_QuestEN[35338] = { title = "Shooting the Breeze", description = "Kia and I are having a spirited debate over who kills more efficiently: SI:7 or rangari.\n\nCare to get in on the wager, commander?\n\nI've been focusing on talbuk because of their fierce majesty. They truly encapsulate the grandeur of Nagrand as any native of Draenor knows.", objectives = "Collect 24 Breezestrider Horns from Breezestrider talbuk.", progress = "This outsider really thinks she can come here and best me in my own land?\n\nOh... sorry, commander. Present company excluded, of course.", completion = "Twenty-four, huh? That's fine work.\n\nI brought back fifty.\n\nI'll send someone out for the meat. Waste not, want not." }
WordHunterWoW_QuestEN[35339] = { title = "A Parting Favor", description = "I don't know what happened. My crew and I must have been the first to fall.\n\nMy wife, the innkeeper, is in the same stupor you found me in. I can feel it... and there are others with her.\n\nPlease, give the townsfolk peace and show their essences to my wife. That should bring her back from that cold abyss.", objectives = "Gather 6 Spectral Essences from restless spirits inside the garrison and use them to convince Alice Finn of her fate.", progress = "Everything is so hazy... what happened? Who are you?", completion = "We're... dead?" }
WordHunterWoW_QuestEN[35340] = { title = "What Happened Here?", description = "Dis architect's spirit not be wantin' to fight us. Maybe we can break da haze over his mind and find out what happened.\n\nI bet one of da undead peasants has one of his schematics or somethin' we can show to him to clear his mind.\n\nIt be worth a shot.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Search for one of Bryan Finn's Schematics." }
WordHunterWoW_QuestEN[35341] = { title = "Defection of Gronnstalker Rokash", description = "You have done me a great service. This blade is as much yours as it is mine.\n\nI offer you this blood oath: I shall serve your cause and lend my knowledge of blades and mining to your forces.\n\nWill you accept it?", objectives = "Accept the Blood Oath of Blademaster Na'Shra.", completion = "You have proven yourself more powerful than my previous leaders. My service is yours." }
WordHunterWoW_QuestEN[35342] = { title = "The Mysterious Flask", description = "The liquid swirling around inside the flask clearly has strong alchemical properties, but its nature is beyond your training.\n\nYou have heard that one of the Eventide villagers at your garrison has some knowledge of the alchemy of Draenor. Perhaps he could tell you more?", objectives = "Speak to Aenir at your garrison.\n\nProvided item:", completion = "Ah. I see you have found a creation of Draenor alchemy." }
WordHunterWoW_QuestEN[35343] = { title = "The Young Alchemist", description = "I learned a little about alchemy from my aunt. If you want to know more, though, you should speak with my cousin Abatha. She was apprenticing under my aunt before she passed away.\n\nAbatha lives near the Verdant Mire with her father and sister.", objectives = "Find Abatha at the Verdant Mire.", completion = "Please. Help me. I need to find my father." }
WordHunterWoW_QuestEN[35344] = { title = "The Missing Father", description = "I would be happy to help with your alchemical inquiries, but right now I am worried about my father.\n\nIt's been quite some time since he went hunting down by the river, but he still hasn't returned home. I need to watch Lumiel. Will you please find him?", objectives = "Find Telos in the Verdant Mire.", completion = "Thank you, stranger. I don't think the razorfangs were happy that I was hunting the same prey." }
WordHunterWoW_QuestEN[35345] = { title = "Shocking Assistance", description = "It's been a struggle to support the family since my wife died, and I got too ambitious when I got a contract for shockscales.\n\nAlas, there is no way I will hunt enough eels to fulfill it in time now.", objectives = "Collect 100 Shockscales from Shockscale eels.", progress = "Thank you so much for finding my father.", completion = "You did this for my family? After you saved our father? Thank you, <name>.\n\nYou wished to know about Draenor alchemy? I will do my best to share my knowledge with you." }
WordHunterWoW_QuestEN[35346] = { title = "Abatha, the Alchemist", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[35347] = { title = "Treasure: Ogre Booty 000", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
