WordHunterWoW_QuestEN[35349] = { title = "Blackrock Caverns Bonus Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[35350] = { title = "Queen of the Clefthoof", description = "Laara told me that they have Banthar here! Or rather, that she's still alive back now. Did what I just said make any sense?\n\nThis is our chance, commander. We can defeat a younger, more powerful version of Banthar and really stick it to these rangari.\n\nWe'll show Laara how a true professional works.", objectives = "Collect the Horn of Banthar from Banthar.", progress = "Banthar's horn. Hemet would be green with envy to have another shot at such a powerful beast.", completion = "Magnificent kill, commander. You've done us all proud." }
WordHunterWoW_QuestEN[35351] = { title = "Blackrock Caverns Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35352] = { title = "Blackrock Caverns Bonus Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[35353] = { title = "A Piece of the Puzzle", description = "I... I remember now. Watch Commander Branson told us to stay in the inn... he said we would be safe here.\n\nThen...\n\nThen that THING broke through and slaughtered everyone!\n\nThe last thing I remember seeing was it descending into the larder.", objectives = "Kill the Horrific Aberration in the basement of the inn.", progress = "Is the creature dead?", completion = "I will convince the others of our fate. There's no denying it anymore." }
WordHunterWoW_QuestEN[35356] = { title = "Someone's Missing Arrow", description = "<An arrow of rangari make is sticking out of the side of this talbuk. Perhaps Rangari Laara will be interested in your find.>", objectives = "Take the Rangari Arrow to Rangari Laara at Telaari Station.\n\nProvided item:", completion = "That's MY arrow! Where'd you get it?" }
WordHunterWoW_QuestEN[35357] = { title = "King of the Breezestriders", description = "Let me guess, you found it in a talbuk's flank?\n\n<Laara seems lost in thought for a moment.>\n\nThat arrow was intended for Tall Buck, king of the Breezestriders. Another talbuk - the one you killed - jumped in the way as I was taking my shot.\n\nI suggest you go after the king. When I was hunting him, he seemed fond of the pond at Lonely Falls to the south.", objectives = "Collect Tall Buck's Tail from Tall Buck.", progress = "How goes the hunt for Tall Buck?", completion = "Well done, <name>. You succeeded where I did not.\n\nPerhaps you outsiders aren't such bad hunters after all." }
