WordHunterWoW_QuestEN[35372] = { title = "The Call of Oshu'gun", description = "The elements have spoken and a vision has been revealed, {name}.\n\nTogether we shall travel to the great mountain Oshu'gun and put an end to the dark disturbance there.\n\nIf what you saw in the vision is to be believed, then great danger awaits us.\n\nI will meet you in the Spirit Woods at the foot of Oshu'gun. When you are ready to depart, speak with Gixmo Moneycash and he will fly you to there.", objectives = "Fly to the Spirit Woods.", completion = "These woods are sacred to the orcs and to my people as well.\n\nBeneath the great mountain of Oshu'gun lies the heart of Nagrand, the Genedar. This great dimensional vessel rescued my people from annihilation and brought us to this world." }
WordHunterWoW_QuestEN[35373] = { title = "Treasure: Ogre Booty 006", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[35374] = { title = "That Pounding Sound", description = "Commander. The frostwolf and I were just discussing the merits of various 'hunting' approaches.\n\nI assured her that the shadow hunters are well-equipped to deal with any situation, even ones out in the wild.\n\nShe seems to think that we don't know what we're doing when it comes to bringing down game in 'her land.'\n\nWe're not going to let her get away with saying that, right? Let's take down some clefthoof.", objectives = "Collect 12 Pairs of Leatherhide Ears from Leatherhide clefthoof.", progress = "It's unbelievable how arrogant these frostwolves can be.", completion = "Twelve pairs, huh? That's pretty good, commander.\n\nUm, no, I think that's about how many I managed to bag. Yeah... about a dozen pairs of ears. Yep...." }
WordHunterWoW_QuestEN[35375] = { title = "Queen of the Clefthoof", description = "Ogka told me that they have Banthar here! Or rather, that she's still alive back now. Did what I just said make any sense?\n\nThis is our chance, commander. We can defeat a younger, more powerful version of Banthar and really stick it to these frostwolves.\n\nWe'll show Ogka how a true professional works.", objectives = "Collect the Horn of Banthar from Banthar.", progress = "Banthar's horn. Hemet would be green with envy to have another shot at such a powerful beast.", completion = "Magnificent kill, commander. You've done us all proud." }
WordHunterWoW_QuestEN[35376] = { title = "Shooting the Breeze", description = "Taz and I are having a spirited debate over who kills more efficiently: shadow hunters or frostwolves.\n\nCare to get in on the wager, commander?\n\nI've been focusing on talbuk because of their fierce majesty. They truly encapsulate the grandeur of Nagrand as any native of Draenor knows.", objectives = "Collect 24 Breezestrider Horns from Breezestrider talbuk.", progress = "This outsider really thinks he can come here and best me in my own land?\n\nOh... sorry, commander. Present company excluded, of course.", completion = "Twenty-four, huh? That's fine work.\n\nI brought back fifty.\n\nI'll send someone out for the meat. Waste not, want not." }
WordHunterWoW_QuestEN[35377] = { title = "Someone's Missing Axe", description = "<A throwing axe of frostwolf make is sticking out of the side of this talbuk. Perhaps Stalker Ogka will be interested in your find.>", objectives = "Take the Frostwolf Axe to Stalker Ogka at Wor'var.\n\nProvided item:", completion = "That's MY axe! Where'd you get it?" }
WordHunterWoW_QuestEN[35378] = { title = "King of the Breezestriders", description = "Let me guess, you found it in a talbuk's flank?\n\n<Ogka seems lost in thought for a moment.>\n\nThat axe was intended for Tall Buck, king of the Breezestriders. Another talbuk - the one you killed - jumped in the way as I was taking my shot.\n\nI suggest you go after the king. When I was hunting him, he seemed fond of the pond at Lonely Falls to the south.", objectives = "Collect Tall Buck's Tail from Tall Buck.", progress = "How goes the hunt for Tall Buck?", completion = "Well done, <name>. You succeeded where I did not.\n\nPerhaps you outsiders aren't such bad hunters after all." }
WordHunterWoW_QuestEN[35379] = { title = "Hemet's Happy Hunting Grounds", description = "", objectives = "" }
WordHunterWoW_QuestEN[35380] = { title = "Second in Command", description = "Wait... I remember something else.\n\nSir Edward... he was shouting... looking for someone.\n\nI... I can't remember who. There were so many screams...", objectives = "Speak to Sir Edward at Admiral Taylor's Garrison.", completion = "If today was any other day I'd have you court-martialed for being out of uniform." }
WordHunterWoW_QuestEN[35381] = { title = "Treasure: Shadowmoon Treasure 05", description = "", objectives = "" }
WordHunterWoW_QuestEN[35382] = { title = "Treasure: Shadowmoon Treasure 06", description = "", objectives = "" }
