WordHunterWoW_QuestEN[35384] = { title = "Treasure: Shadowmoon Treasure 08", description = "", objectives = "" }
WordHunterWoW_QuestEN[35386] = { title = "The Warsong Threat", description = "<The attack plans are scrawled onto the parchment in thick, black ink and bound in rough leather.>\n\nTo all outrider stations:\n\nThe warlord has commanded that all outriders prepare for a full assault upon the Alliance invaders in our land. Plans for the attack have been delivered to several of the remote outrider posts.\n\nBlood and glory shall be ours as we trample the Alliance invaders beneath our feet!\n\nThe warlord commands and the Warsong obey! Lok'tar ogar!", objectives = "Steal the Warsong Attack Plans.", progress = "What do you have for me?", completion = "<Captain Washburn examines the attack plans, squinting at the lettering and holding the pages upside down.>\n\nHmm... I see... yes... indeed!\n\nThese are obviously attack plans, as you yourself have stated, but they are most likely written by kobold pyromancers.\n\nStrange though, I haven't seen any kobold pyromancers since my days in Azeroth. No matter! I assure you that the outpost is well armed and mostly fireproof!\n\nIf we are attacked, the outpost shan't fall. You have my word, commander!" }
WordHunterWoW_QuestEN[35387] = { title = "Through The Nether", description = "The void rituals have been disrupted, but dark energy still flows into the nether beacons at the ritual sites. This can only mean that the beacons are being powered from within the Twisting Nether itself.\n\nThe only way to sever the flow of void energy to the beacons is to travel into the Twisting Nether and stop whatever power lurks there!\n\nUse a beacon to travel to the Twisting Nether. Once there, us the shaman stone given to us by the furies to contact me.\n\nLight be with you.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Travel to the Twisting Nether." }
WordHunterWoW_QuestEN[35388] = { title = "The Void March", description = "Legions of void terrors are marching upon Oshu'gun and sacrificing themselves to the void lord Invalidus.\n\nAs they die Invalidus grows stronger. It is as if the lesser creatures only serve to feed the void lord.\n\nWe must stop Invalidus from becoming so powerful that it cannot be stopped.\n\nSlay as many void monsters as you can, to slow the growth of Invalidus. In the meantime, I will search for a way to encounter Invalidus before it is too late to stop it.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Destroy 12 Void Creatures." }
WordHunterWoW_QuestEN[35389] = { title = "Silence The Call", description = "The Warsong shaman are using the elements to channel dark energy from the void.\n\nI am no shaman, but even I know that such practices are abhored by most orc clans. The power of the void is opposite to the Light, and a source of entropy and destruction.\n\nThese rituals thin the veil between our world and the Twisting Nether. Should the rituals continue, this land will soon be overrun by the denizens of the Twisting Nether.\n\nSlay the shaman leading these dark rituals before destruction falls upon us!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Slay the Warsong ritual leaders." }
WordHunterWoW_QuestEN[35390] = { title = "The Shadow Over Oshu'gun", description = "The void lord Invalidus stands atop the peak of Oshu'gun gorging itself upon the souls of the dead.\n\nEven the fallen void terrors that you slew only served to feed the monster.\n\nIf we do not act now, Invalidus will grow too powerful to encounter alone.\n\nAt each of the ritual sites in the Twisting Nether, there is a crystal filled with the powers of the void. Disturb the void crystal and Invalidus will sense your presence.\n\nBe ready, Invalidus will waste no time in attempting to feed on your soul.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Summon and defeat Invalidus." }
WordHunterWoW_QuestEN[35391] = { title = "Disrupt The Rituals", description = "Beneath the mountain of Oshu'gun the Warsong perform dark rituals.\n\nThe Warsong shaman seek to empower their clan by drawing upon a great source of void energy within the heart of Oshu'gun.\n\nThough I do not know for certain the source of this power...I fear that the dying naaru K'ure may be involved.\n\nThe Warsong rituals must be stopped or the veil that separates this world from the Twisting Nether will be ripped apart.\n\nLocate the ritual totems used to channel these rituals and destroy them.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Destroy the Ritual Totems." }
WordHunterWoW_QuestEN[35392] = { title = "The Nether Approaches", description = "By drawing upon the power of the void, the Warsong have thinned the veil that shields our world from the Twisting Nether.\n\nPortals are opening within the nether that threaten to connect the terrors of the void to Draenor.\n\nShould these portals fully open, the path will be clear for all manner of demons and void creatures to rampage across Nagrand.\n\nGo and collapse the portals before they become functional!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collapse 10 Void Portals." }
WordHunterWoW_QuestEN[35393] = { title = "Spiritual Matters", description = "The spirits of the dead have long been drawn to the mountain of Oshu'gun.\n\nAs long as I can remember, the woods have been filled with ancestral spirits making a ghostly pilgrimage to the heart of the mountain. I fear that the souls drawn to Oshu'gun are being consumed by the growing void within the mountain.\n\nMake your way to the Ancestral Grounds and commune with the spirits there for guidance.", objectives = "Speak with the spirits at the Ancestral Grounds.", completion = "The situation here is dire, <name>, but I sensed that we would meet again.\n\nI do not hear the call of the void as loudly as the others, for I am not long dead and my body rests far from this place.\n\nWith time though, that will change.\n\nIf you are here to help, listen closely for time is short." }
WordHunterWoW_QuestEN[35394] = { title = "The Pale Threat", description = "In the time that you have been fighting against the void, I have been exploring the disturbance within Shadowfall Canyon.\n\nA dark mist has settled in the canyon, <name>; and I found twisted, pale creatures lurking there.\n\nWe have much to discuss. Return to me from the Twisting Nether and we will speak more.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Return to Vindicator Nobundo.In the time that you have been fighting against the void, I have been exploring the disturbance within Shadowfall Canyon.\n\nA dark mist has settled in the canyon, <name>; and I found twisted, pale creatures lurking there.\n\nWe have much to discuss. Return to me from the Twisting Nether and we will speak more.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[35395] = { title = "The Fate of Gordawg", description = "Looming monstrously between us and the inner chamber is the great fury we have sought to return to the Throne of Elements.\n\nGordawg stands before us enthralled; a slave to Cho'gall. My heart is heavy with grief to see such a great creature mindless and enslaved by evil.\n\nThere is no going back, in order to push forward you must go through Gordawg.\n\nIt pains me, but Gordawg must be slain.\n\nSlay Gordawg and return the fury's heart to the Throne of Elements where it belongs.", objectives = "Retrieve the Heart of the Fury.", progress = "What of Gordawg? Has the great fury been brought to rest?", completion = "Gordawg was a mighty ally. The elements will mourn the loss of the fury, but death was the only answer. Gordawg would not have wished to stay a slave to evil.\n\nThough Gordawg is no more, the heart of a fury is eternal and unbreakable. In time, this brightly glowing heart will take shape into a new earthen fury.\n\nSuch is the cycle of life upon the Elemental Plateau." }
WordHunterWoW_QuestEN[35396] = { title = "The Dark Heart of Oshu'gun", description = "Amongst the timeworn wreckage of the Genedar is the entrance to the vessel's inner chamber. The void energy appears to be most concentrated in that place.\n\nYou must enter the inner chamber and face whatever evil lurks within. I fear whatever fate may have befallen the great naaru K'ure in that place, but regardless the evil there must be purged.\n\nMay the Light be with you, {name}.", objectives = "Enter the Sanctum of the Naaru.", completion = "The fate of K'ure could not have been prevented.\n\nCho'gall accelerated the naaru's transition into a void god in hopes of bringing destruction upon Draenor. Cho'gall must be dealt with, but for now let us honor the memory of the great naaru K'ure.\n\nK'ure was truly the savior of my people, a friend to the virtuous, and a teacher of prophets.\n\nMay the great naaru ever live within our hearts." }
WordHunterWoW_QuestEN[35397] = { title = "The Pale Threat", description = "If we are to succeed in stopping Cho'gall from destroying the naaru, we will need to fight our way through the Underpale; a dark, winding cavern infested with the Pale.\n\nThe Pale are fallen orcs that despise all that is good and holy. The longer they are left to their devices beneath the ground, the further their dark plots progress.\n\nMake your way into the Underpale, slay the vile creatures within and take out their leader, Greyseer.", objectives = "Kill Greyseer and 6 Pale orcs.", completion = "The Pale are wretched creatures that hate the Light and plot against the innocent. Without Greyseer to lead them, they will be disorganized and in chaos for a time.\n\nShould a new leader arise from within their ranks, we shall smite them down once more." }
WordHunterWoW_QuestEN[35398] = { title = "Dark Binding", description = "Even as we speak, the pale are enslaving an army of elementals in Shadowfall Canyon. Many have already been enslaved and if we do not lend our aid, more will follow.\n\nGo to Shadowfall Canyon and set free the elemental spirits which are not yet fully enthralled by the pale. As for those already enslaved, the only mercy we can give them now is a swift death.", objectives = "Free 8 elemental spirits.", completion = "You have done well to free the elemental spirits from their bonds. If Cho'gall and the pale seek an army of elemental slaves, they must not be allowed to succeed." }
WordHunterWoW_QuestEN[35399] = { title = "Mossy Fate", description = "Your wolf queen will not let me out of her sight.\n\nThe children of the magnaron may have destroyed my village but it was the children of the genesaur who took my people.\n\nThe botani and their minions drag our people to the Razorbloom, and if we see them again, it is not as they were in life.\n\nYou have already helped the Skulls, so I ask your help again.\n\nEnter the Razorbloom and search for my people that were recently taken.\n\nPerhaps they may even be alive.", objectives = "Search for Torg Earkeeper, Meka the Face Chewer, and Chag the Noseless in Razorbloom.", completion = "Dead? All dead? Dead and mulched and forgotten. No Chag with his missing nose or Meka with her love for chewing faces.\n\nAnd Torg, my beloved Torg. A son we had together. A son that is still missing.\n\nThe botani will pay for this. They will burn for this." }
WordHunterWoW_QuestEN[35400] = { title = "The Infested", description = "I understand Kaz's desire to rescue her people, but her plan is reckless and she is not telling us everything.\n\nI came along to make sure she wasn't devising a plan against us and now I see this... this... horror.\n\nWhat did the botani do to these orcs?\n\nThese infested souls need to be put to rest. Give them peace.", objectives = "Slay 6 Infested Orcs.", completion = "These creatures... were not what I expected to see. I always knew Gorgrond to be a dangerous place, but I never could have guessed at how vile.\n\nThank you, commander, for your compassion in this." }
WordHunterWoW_QuestEN[35401] = { title = "The Vortex Pinnacle Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35402] = { title = "The Voice of Iyu", description = "The botani and their wretched minions take and take and take.\n\nThey want food, they take our land. They want an army, they take our people.\n\nIt is important to strike fear into the shrubby hearts of these plant people.\n\nLook for their leader, the Voice of Iyu. It is a botani who speaks on behalf of their genesaur master.\n\nKill their precious leader in the safety of his precious bloom.", objectives = "Slay the Voice of Iyu.", completion = "It isn't enough to kill the botani. They will always have greater numbers.\n\nYou must cut them deep and hard, where it hurts them the most.\n\nLike slaying their most sacred leader." }
WordHunterWoW_QuestEN[35403] = { title = "The Vortex Pinnacle Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35404] = { title = "Grim Batol Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35405] = { title = "Grim Batol Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35406] = { title = "Super Seeds", description = "These seeds have been shielded with care by the botani.\n\nGreat power can be felt surging out of these tiny vessels of life.\n\nThese may prove useful.", objectives = "Collect Enriched Seeds.", progress = "What have you found?", completion = "Seeds. So simple to look at but in each the potential for untold amounts of destruction. Much like my son.\n\nYou were wise to take these." }
WordHunterWoW_QuestEN[35407] = { title = "Punishable by Death", description = "Traitors, the lot!\n\nYou're looking at the last bastion of forces still loyal to Admiral Taylor and the Alliance.\n\nI'll be damned if the defectors get away clean.\n\nYou look like you're ready. Show them how we deal with their kind during times of war.", objectives = "Kill 8 garrison traitors.", completion = "Well fought. For the Alliance!" }
WordHunterWoW_QuestEN[35408] = { title = "Prime the Cannons", description = "The armory is lost to the traitors. All we have left are these few cannons with no ammunition.\n\nSoldier, I need you to recover cannonballs so we can get these things running.\n\nActually, one more cannon wouldn't hurt, either.", objectives = "Recover 10 Ironcoat Cannonballs and 1 Armory Cannon.", progress = "I hope you're toting a cannon and some balls, soldier.", completion = "Good job, soldier." }
WordHunterWoW_QuestEN[35411] = { title = "Zul'Gurub Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35412] = { title = "Zul'Gurub Bonus Objective Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35413] = { title = "Lost City of the Tol'vir Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35414] = { title = "Lost City of the Tol'vir Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35415] = { title = "Halls of Origination Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35416] = { title = "Power of the Genesaur", description = "Commander, you now have the Will of the Genesaur along with the genesis water and enough seeds to grow an army. Not to mention the Laughing Skulls you helped save.\n\nI would call this mission a success.\n\nI will investigate this fortress further and see if there are more materials we might glean from it.\n\nIn the meantime, you may want to bring these artifacts you have obtained to Durotan back at the outpost. I will catch up once we have finished here.", objectives = "Speak with Durotan at Beastwatch in Gorgrond.", completion = "Well done, Commander. Many of the orcs have tried to master the power of the genesaur but I have never heard of any succeeding.\n\nYou have won us a powerful weapon for the next time we face the Iron Horde." }
