WordHunterWoW_QuestEN[35429] = { title = "Pollen Power", description = "Those of us who grew up in Gorgrond have long learned a few secrets of the botani that can be used to grow our own plants.\n\nThere is no such thing as a hungry Laughing Skull for this reason.\n\nThe ravagers are the key.\n\nOutside of Evermorn Springs you will find ravagers of every type. Slay them and bring me the pollen they carry, and I can cultivate it to be of use to your garrison.", objectives = "Collect 20 Potent Pollen.", progress = "Few dare challenge the botani in the field of growing plants.", completion = "Ah... yes, yes, yes. Fresh pollen. With a dash of a few secret ingredients you can feed an army with the food you could grow from this, if you know the secret ways." }
WordHunterWoW_QuestEN[35430] = { title = "Cutter", description = "You found many Laughing Skulls. All friends, all loved, all dead. But you did not find my precious Cutter.\n\nThey must have taken him to Evermorn Springs.\n\nFind him, and rescue him.\n\nHe is a good boy, and deserves a better death than infesting.\n\nI am going to round up some ravagers and take the place by air. Look for me in Evermorn if you find Cutter before I do.", objectives = "Find Cutter.", completion = "The botani took my dad. They took my friends. And now they are making me eat fruit!\n\nWhy are they so mean?!\n\nDid you kill them all?\n\nI think you should kill them." }
WordHunterWoW_QuestEN[35431] = { title = "The Best Poison", description = "Do you like poisons? I am more of a \"set everything on fire and loot what doesn't burn\" kind of orc myself.\n\nBut I do know a thing or two about poisons.\n\nWhen you venture into the Razor Bloom, look for a pungent, violent plant that we call Reaver Vine. Under just the right circumstances, and FIRE, the vine will make a lovely poison. Bring me some and I shall concoct a lovely poison for you.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 8 Reaver Vines." }
WordHunterWoW_QuestEN[35432] = { title = "Bushwhacker", description = "Kaz is using us, I am sure of it. She is a Laughing Skull and must NOT be trusted.\n\nFor now, I am willing to play along until we can learn more. \n\nKaz is going to ask for you to travel to Evermorn Springs. When there, I recommend you slay any botani you encounter.\n\nCulling the numbers of these horrific casters will hopefully save future orcs from such a infested fate.\n\nI will stay with Kaz and keep a close eye on her.", objectives = "Slay 7 Bloom Weavers.", completion = "I had thought the Laughing Skull were planning something. Now I think I am beginning to understand.\n\nThey match savagery with savagery." }
WordHunterWoW_QuestEN[35433] = { title = "Cut Them Down", description = "They steal children? Children?!\n\nHad you not rescued Kaz's child, he would be reduced to mulch just like the others.\n\nYou should send them a message they will understand. Cut down their great dew casters. Rip them apart.\n\nLet them know that it is not okay to take our children.", objectives = "Slay 3 Dew Masters.", completion = "They are lucky you are the one that killed them. I would have tried to carve pictures in their dead wood bodies." }
WordHunterWoW_QuestEN[35434] = { title = "The Life Spring", description = "It sounds like these... \"dwarves\"... you found managed to steal a powerful botani artifact.\n\nBut the fools didn't know they need a special water to power it.\n\nTo the north is a well along the Evermorn Rise.\n\nThere you will find a guardian, a creature of water we have named Utrophis.\n\nSlay it and take its essence and you will be one step closer to claiming the power of the botani and their genesaur.", objectives = "Collect the Waters of Utrophis.", progress = "For years the Laughing Skull would not touch the sacred waters. We feared the wrath of the botani. We should have set them to burn long ago.", completion = "The Waters of Utrophis. I have never held or smelled or tasted it before. But I have heard many stories, many legends.\n\nI was expecting something more grand." }
