WordHunterWoW_QuestEN[35444] = { title = "The Southern Wilds", description = "First the Iron Horde, then the Shadowmoon orcs, and now there's trouble brewing to the south!\n\nMy brother is a feyrider to the south, at the Draakorium.\n\nHe says that creatures from the swamp are venturing onto our lands. What is this world coming to?\n\nAnyway, you look like a seasoned adventurer. If you are heading that way, would you mind checking in over there?", objectives = "Speak to Prelate Reenu at The Draakorium.", completion = "Thank you for coming to our aid." }
WordHunterWoW_QuestEN[35446] = { title = "The Oculus Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35447] = { title = "The Oculus Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35448] = { title = "Vignette: Darkmaster Go'vid", description = "", objectives = "" }
WordHunterWoW_QuestEN[35449] = { title = "Utgarde Pinnacle Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35450] = { title = "The Southern Wilds", description = "I've heard disturbing news from our friends at The Draakorium, to the south.\n\nThe town lies near a swamp, and recently, dangerous creatures have been venturing near its borders.\n\nYou seem like a seasoned adventurer. If you are heading that way, would you mind checking in with our people there?\n\nI would feel much better if I knew they were safe.", objectives = "Speak to Prelate Reenu at The Draakorium.", completion = "Ah, Prelate Luari sent you, did she? Such a sweet woman, always looking out for others." }
WordHunterWoW_QuestEN[35452] = { title = "Utgarde Pinnacle - Bonus Objective Reward", description = "", objectives = "" }
