WordHunterWoW_QuestEN[35611] = { title = "Return to Veil Terokk", description = "<A small note is tied to the kaliri's foot.>\n\n\"Percy should have brought with him a basket of goods, assuming he didn't dump it off somewhere along the way. The contents are a token of my gratitude and an apology for the altercation with your scout.\n\nI must urge you to return to Veil Terokk so we may press forward with our plans.\n\n- Reshad \"", objectives = "Speak with Reshad in Veil Terokk.", completion = "Thank you for returning to us, <name>. I must admit we are sorely in need of your help." }
WordHunterWoW_QuestEN[35612] = { title = "Scarlet Monastery Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35613] = { title = "Scarlet Monastery Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35614] = { title = "Artificer Romuul", description = "", objectives = "I have heard of you, traveler. Your people have come to defeat the Iron Horde.\n\nFrom what I have just seen, your combat skills are as impressive as they say.\n\nI, too, wish to see the Iron Horde gone from this land. I will lend you the strength of my hammer, and you may also find my knowledge of crystalworking to be useful.\n\nWhat do you say?" }
WordHunterWoW_QuestEN[35615] = { title = "Razorfen Kraul Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35616] = { title = "Nagrand - Treasure 029 - Steamwheedle Supplies", description = "", objectives = "" }
WordHunterWoW_QuestEN[35617] = { title = "Fiona", description = "", objectives = "I have spoken with the rest of my caravan, and we've agreed to rest our wagon for a while while I pledge my service to your garrison.\n\nI think I could be of great use to you. What do you say?" }
WordHunterWoW_QuestEN[35618] = { title = "Gidwin Goldbraids", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[35619] = { title = "Pinchwhistle Gearworks", description = "Commander, a goblin courier arrived this morning.\n\nHe mentioned that he is from a settlement to the southeast called the Pinchwhistle Gearworks. They have requested our assistance with some sort of ecological disaster.\n\nIf we can earn their trust it'll be worth the effort. Head down there and see what sort of assistance we can provide.\n\nI've already spoken to the flight master and he's set up a special flight to get you out there.", objectives = "Speak to Firn Swiftbreeze to secure a flight to the Pinchwhistle Gearworks.", completion = "Hey, you're from that Alliance base right?\n\nGlad you made the trip because we really could use your help!" }
WordHunterWoW_QuestEN[35620] = { title = "Pinchwhistle Gearworks", description = "Commander, a courier arrived this morning.\n\nHe said he's from a goblin settlement to the southeast called the Pinchwhistle Gearworks. They've asked for our assistance with some sort of ecological disaster.\n\nWe're spread thin but if we can earn their trust then we might be able to gain a valuable ally.\n\nHead down there and see what sort of assistance we can provide. I've already spoken to the flight master and he's set up a special flight to get you out there.", objectives = "Speak to Hutou Featherwind to secure a flight to the Pinchwhistle Gearworks.", completion = "Hey, you're from that Horde base right?\n\nGlad you made the trip because we really could use your help!" }
WordHunterWoW_QuestEN[35621] = { title = "Tarenar Sunstrike", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[35622] = { title = "Nagrand - Treasure 030 - Hidden Stash", description = "", objectives = "" }
WordHunterWoW_QuestEN[35623] = { title = "Nagrand - Vignette Boss - Explorer Rixak", description = "", objectives = "" }
WordHunterWoW_QuestEN[35624] = { title = "Roona", description = "", objectives = "I have never seen anyone fight like you, <name>. I am curious about your people and your mission here in this place.\n\nIf I can be of assistance, I would like to join your cause." }
WordHunterWoW_QuestEN[35625] = { title = "Shelly Hamby", description = "", objectives = "Draenor... even the sound of this place makes me sick.\n\nMy husband is gone. I cannot go home while his memory lingers.\n\nPlease, let me join you and fight for you. Send me to the frontlines, wherever killing is needed.\n\nWith every enemy that I face, perhaps the pain will lessen." }
WordHunterWoW_QuestEN[35626] = { title = "Apprentice Artificer Andren", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[35627] = { title = "Treasure: Basket of Arakkoa Goods", description = "", objectives = "" }
WordHunterWoW_QuestEN[35628] = { title = "Rangari Chel", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[35629] = { title = "Vindicator Onaala", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[35630] = { title = "Garrison Visitor: Sappy", description = "", objectives = "" }
WordHunterWoW_QuestEN[35631] = { title = "Rulkan", description = "", objectives = "Prophet Velen spoke highly of you, and I can see that your weapons are keen and your intent is just.\n\nI sense great potential within you. If you will allow it, I would warm my hands by your fire for a while.\n\nI would like to follow you and learn from your people. In return, I shall fight for you.\n\nWhat do you say, traveler?" }
WordHunterWoW_QuestEN[35632] = { title = "A Lesson in Archaeology", description = "As an archaeologist, it's important to make great discoveries and contributions to the field. Why? Because that's how you make a name for yourself!\n\nEven that hack Harrison Jones has a somewhat reputable name. If he can do it, then you can too!\n\nThe Highmaul are hiding something big in that cave of theirs and we need to get in there and take it!\n\nTake this teleportation beacon and make your way to the back of the cave. Once you find the relic, place the beacon and my team will take care of the rest!", objectives = "Recover the Mysterious Artifact.", completion = "Great work back there! That's how real archaeology is done!\n\nIt's a good thing you came to me to learn the trade, kid. You've got talent and I'd hate to see it wasted on a putz like Harrison Jones!" }
WordHunterWoW_QuestEN[35633] = { title = "Scout Forensics", description = "My entire squad is gone. Some are dead; that much is obvious. The others though... they must be further in.\n\nGo and search the bodies of my squad that you find, each will carry a small pouch of personal items. I would like to return these to their families.\n\nI will go ahead and meet you inside the marsh.", objectives = "Collect 5 Rangari Pouches from dead Rangari.", progress = "The families of my squad need closure and we need more information on their deaths.", completion = "Thank you for doing this <name>.  Hopefully they can be cleaned of these foul spores that coat everything here." }
WordHunterWoW_QuestEN[35634] = { title = "Control is King", description = "Apexis technology is fascinating, isn't it? Machines powered by solar energy. Energy which itself has been imbued with magic!\n\nSimply brilliant!\n\nAh, but there's always a catch. And I think you may have found it.\n\nBring the interface device back to Veil Terokk, will you? I'll be along shortly with the Apexis cores.\n\nIf my theory is right, we may be able to turn the Adherents' own weapon against them!", objectives = "Bring the Apexis Interface to Darkscryer Raastok in Veil Terokk.", progress = "Did you bring the device?", completion = "It will take some time, but this may be the key to our victory." }
WordHunterWoW_QuestEN[35636] = { title = "All Due Respect", description = "A group of Adherents came 'round just before the attack on Skettis. Disguised myself as a mushroom, I did. The fools walked right past me.\n\nMy neighbor up the road was not so lucky.\n\nHe had a fondness for texts, if I recall. Might be valuable information in his hut, if you give Reshad a moment to rummage around.\n\nOh, and bring one of his feathers to the shrine near Veil Terokk, would you? He was such a dear, and I know it's what he'd want.", objectives = "Retrieve the Feather of Syth and the Saga of Terokk.", progress = "Here, I'll take them both for safekeeping.", completion = "<Reshad presses the feather into the tome before sliding it into his robes.>\n\nWe have one more stop before the wayshrine..." }
WordHunterWoW_QuestEN[35637] = { title = "Assault on Stonefury Cliffs", description = "", objectives = "" }
WordHunterWoW_QuestEN[35638] = { title = "A Few Artifact Fragments", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Every little bit helps." }
WordHunterWoW_QuestEN[35639] = { title = "A TON of Artifact Fragments", description = "", objectives = "As much as you can carry.", progress = "As much as you can carry.", completion = "Great work, <class>! I will let Vindicator Maraad know of your bravery." }
WordHunterWoW_QuestEN[35640] = { title = "Vengeance for the Fallen", description = "I... almost made it out.  Most of us... dead. The others... they are no longer themselves.\n\nThese lurching spore beasts are the cause, dragging us further into the marsh... stop them.", objectives = "Kill 7 Fungal Lurchers.", completion = "Thank you for avenging my fallen friends. We will get to the bottom of this I swear!" }
WordHunterWoW_QuestEN[35641] = { title = "Assault on Stonefury Cliffs", description = "", objectives = "" }
WordHunterWoW_QuestEN[35642] = { title = "Mysterious Pod", description = "This pod is similar to the ones growing on or near the bodies around here, except this one is pulsating weirdly.\n\nThis is something Khaano would be interested in.", objectives = "Bring the Glowing Red Pod to Khaano at Crimson Fen in Gorgrond.\n\nProvided item:", completion = "I've seen these around on corpses and the beasts, but not as big.  Let me see it..." }
WordHunterWoW_QuestEN[35643] = { title = "Nagrand - Treasure 062 - Mountain Climber's Pack", description = "", objectives = "" }
WordHunterWoW_QuestEN[35644] = { title = "Mercy for the Living", description = "You can see that the dead were the lucky ones. Those that live wander about attacking anything not infected with these vile spores.\n\nI cannot bring myself to slay them, but if you could bring mercy to those poor people I would be very grateful.", objectives = "Kill 6 Fungus Covered Shamblers.", completion = "Perhaps we shouldn't have wasted time on them, this place... drains me. Still it was a good deed you have done." }
WordHunterWoW_QuestEN[35645] = { title = "The Secret of the Fungus", description = "I'm beginning to sense a strong... connection... between the fungus and the creatures that inhabit it. There are certain mushrooms that are stronger than others.\n\nI believe if I had some samples of these I could use them, track the source of this foul fungus and... deal with it.", objectives = "Collect 5 Glowing Mushrooms.", progress = "Where are my mushrooms?!", completion = "Sadly, I'm growing used to the smell of these spores. In fact, they smell quite pleasant now. Perhaps if I eat these it will speed up our work here..." }
WordHunterWoW_QuestEN[35646] = { title = "Nagrand - Treasure 006 - Steamwheedle Supplies", description = "", objectives = "" }
WordHunterWoW_QuestEN[35647] = { title = "A Grim Harvest", description = "The spores grow thick further into the marsh, but those larger fungus beasts are the key.\n\nYes, kill them and take their spore sacs. I will need them to refine my... search.", objectives = "Bring Khaano 3 Spore Pods from the Fungal Stompers.", progress = "Those pods are critical <name>, I need them!", completion = "I... I must consume these like the mushrooms. It will help me locate the source, I swear!" }
WordHunterWoW_QuestEN[35648] = { title = "Nagrand - Treasure 005 - Steamwheedle Supplies", description = "", objectives = "" }
WordHunterWoW_QuestEN[35649] = { title = "The Writhing Mire", description = "", objectives = "" }
WordHunterWoW_QuestEN[35650] = { title = "Chapter III: Ritual of the Charred", description = "I have seen a strange ritual performed by ancients. They step into fire, burning the leaves from their branches and charring their bark.\n\nI call it the Ritual of the Charred. If we want to weaken the ancients, we can get rid of them before they become even stronger.\n\n- Frenna", objectives = "Kill 4 Ancients.", completion = "Those ancients are crazy! Hard to believe they'd burn off their own leaves." }
WordHunterWoW_QuestEN[35651] = { title = "Chapter II: The Harvest", description = "I have seen a creature working with the ancient saplings, imbuing them with anger and hatred toward creatures unlike them.\n\nPerhaps it is this botani who is responsible for the unusually aggressive nature of ancients here in Tangleheart.\n\nWould killing this botani do us good? I fear I would be no match for it alone.\n\n- Frenna", objectives = "Kill Ontogen the Harvester.", completion = "Ya took out the big nasty did ya? Yer sure to be causin' some real trouble out there!" }
WordHunterWoW_QuestEN[35652] = { title = "Growing Wood", description = "We got the lumber mill good an' built, but we be needin' more wood!\n\nThe Rangari tol' me there's botani usin' some kinda sap to grow ancients fast as you like.\n\nGet yer hands on some o' that sap and I betcha I can put it work.\n\nWhat? Oh, Glyza here? Found 'er crashed here and she knows a thing or two about lumberjackin'. I'll take her back to the outpost later.\n\nI'll meet ya inside Tangleheart if I can find it.", objectives = "Collect 100 Ancient Growth Sap from botani or ancients.", progress = "Glyza is good with tools.", completion = "Sap? Who called me a sap?! Oh..." }
WordHunterWoW_QuestEN[35653] = { title = "Wood is Wood", description = "Them ancients in Bracken Tangle be crazier than a dwarf who don't like gold.\n\nThe burn their leaves right off their 'eads and make their bark hard to fire.\n\nYa know, that bark might come in 'andy 'round here.\n\nChop down a few ancients and I'll send a lackey to gather their wood.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill 6 Emberbark Ancients." }
WordHunterWoW_QuestEN[35654] = { title = "Chapter I: Plant Food", description = "There are strange, glowing objects within Tangleheart, seemingly pollinated by a variety of stinging creature.\n\nThe botani sometimes collect whatever the pods produce. I can't be sure what it is, but it might be dangerous to us.\n\n- Frenna", objectives = "Destroy 8 Pollen Pods.", completion = "Couldn't say what those spores were for, but I feel better knowin' they're gone." }
WordHunterWoW_QuestEN[35656] = { title = "A Heartfelt Search", description = "I can feel a powerful presence in the marsh {name}, it is not far from here.\n\nGo see what is there while I finish my grim feast.  I will catch up...", objectives = "Investigate the strange presence in the Crimson Fen.", completion = "This is unfortunate... I had hoped... Still we are closer now, we are on the right track to finishing this.\n\nNone too soon either, the screaming beasts are really getting to me..." }
WordHunterWoW_QuestEN[35659] = { title = "Heart of the Fen", description = "The pounding in my head is almost unbearable but I must see this through. With all the spore samples I've taken I know where to go and what to do.\n\nI will find the source and spread... no! Destroy it! I will do what needs to be done!", objectives = "Follow Khaano deeper into the Crimson Fen and deal with what comes.", completion = "That is terrible news. I will warn off all scouts from venturing to the Crimson Fen from now on.  Thank you and I am glad you were not affected by the spores..." }
WordHunterWoW_QuestEN[35660] = { title = "Nagrand - Treasure 052 - Fungus-Covered Chest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35661] = { title = "Nagrand - Treasure 054 - Dreamflower", description = "", objectives = "" }
WordHunterWoW_QuestEN[35662] = { title = "Nagrand - Treasure 053 - Steamwheedle Supplies", description = "", objectives = "" }
WordHunterWoW_QuestEN[35663] = { title = "A Lesson in Teamwork", description = "One of the most important skills an archaeology team needs is good teamwork. The key to teamwork is knowing when to give and when to take.\n\nThe Highmaul ogres have been excavating mysterious artifacts from the gorge. I want you to team up with the Highmaul ogres in the name of good archaeology!\n\nRemember what I said about giving and taking? The ogres have given us their hard work to excavate the artifacts. Now I want you to take those artifacts from them and bring them here!\n\nIt's teamwork!", objectives = "Retrieve 10 Mysterious Artifacts.", progress = "Have you retrieved the mysterious artifacts? It's all about teamwork!", completion = "You did a great job, kid!\n\nI hope you learned something about teamwork today. Here's your cut, minus my teaching fee... the Steamwheedle Preservation Society service charge... and gratuity of course!" }
WordHunterWoW_QuestEN[35664] = { title = "Seedbearers of Bad News", description = "When these seedbearers are slain their seeds survive. From them spring new seedbearers, not over years, but hours.\n\nLeaving their remains here would soon cause the outpost to be overrun.\n\nWe have learned that burning their remains prevents this from happening.", objectives = "Burn 5 Ancient Seedbearer corpses.", progress = "These creatures employ unusual tactics.", completion = "The ancients should not be a problem for your outpost for some time." }
WordHunterWoW_QuestEN[35665] = { title = "We Have Company", description = "Commander, I've spotted Iron Horde soldiers nearby.\n\nIt is bold, even for them, to venture into such deadly territory.\n\nIf we do not deal with their presence, they will surely be a threat to your camp.\n\nWhile I scout deeper into the canyons, may I request your help in investigating the camp?", objectives = "Investigate the Iron Horde camp in Sulfur Basin.", completion = "Thank you, friend. I am in your debt.\n\nThis arrogant Iron Horde has made a dangerous enemy today." }
WordHunterWoW_QuestEN[35666] = { title = "Rangari in the Red", description = "Gorgrond is a very dangerous place and I've sent scouting squads out to investigate various regions.\n\nI've sent one squad to the marsh called the Crimson Fen and they've not come back yet.  I'd like you to find the missing squad and get a report if possible.", objectives = "Find Khaano near the Crimson Fen in Gorgrond.", completion = "D'kaan sent you? He's not likely to enjoy the report I have to give him." }
WordHunterWoW_QuestEN[35667] = { title = "Skulltakers in Crimson Fen", description = "Grulkor and his group are often not seen for weeks, returning only when they can carry no more trophies and supplies. He has been gone too long this time.\n\nHe mentioned hunting in the Crimson Fen for the first time, see if he still lives.", objectives = "Find Grulkor near the Crimson Fen in Gorgrond.", completion = "Marrow sent you, eh? Well we leave when I'm done here." }
WordHunterWoW_QuestEN[35668] = { title = "Syth's Secret", description = "Our deceased friend here was hiding more than a love of old scrolls and erotic sorcery-fiction. He had something truly valuable.\n\nIf I'm reading his notes correctly, he claims to have found the Eye of Anzu - Terokk's scrying orb from the days after his fall.\n\nWe need that orb! The notes say he stashed it in a ravager den just up the road.", objectives = "Retrieve the Eye of Anzu.", progress = "To hold such a treasure. I wonder if that Sun-Talon had any idea of the significance?", completion = "<Reshad gazes into the inky orb.>\n\nAmazing. To think Terokk used this very orb to commune with Anzu. One could become quite the darkweaver with an implement such as this.\n\nCome, let's get it safely to the Veil." }
WordHunterWoW_QuestEN[35669] = { title = "WANTED: Keeho's Severed Paw", description = "Posted by: Taskmaster Gornek\n\nThe saberon known as Keeho poses a serious threat to Axefall.\n\nHe has taken to slaughtering peons on the night shift and dragging their corpses to his den in the pridelands.\n\nAnyone who can bring me his severed paw as proof of his demise will be rewarded greatly.", objectives = "Retrieve Keeho's Severed Paw from Keeho the Savage.", progress = "Lok'tar, commander.", completion = "The peons will sing songs of your glory, commander. Lok'tar ogar!" }
WordHunterWoW_QuestEN[35670] = { title = "WANTED: Spineslicer's Husk", description = "Posted by: Killga\n\nI will greatly reward anyone who brings me Spineslicer's husk.\n\nI wish to fashion fine ravager armor, but do not have the skills to take down such a beast.\n\nDon't tear too many holes in it.", objectives = "Retrieve Spineslicer's Husk from Spineslicer.", progress = "It is an honor to have you in my shop, commander.", completion = "I am glad we can count on you, commander." }
WordHunterWoW_QuestEN[35671] = { title = "A Gathering of Shadows", description = "Veil Terokk is just ahead.\n\nLet us hope the others have made the journey safely.", objectives = "Enter Veil Terokk with Reshad.", completion = "We owe you a great debt for delivering Reshad safely to us, <name>.\n\nHowever, our struggle has only just begun." }
WordHunterWoW_QuestEN[35672] = { title = "WANTED: Venombarb", description = "Posted by: Hutou Featherwind\n\nVenombarb is feared in the skies above Arak, even by the high arakkoa.\n\nShe has made air travel difficult for our riders, preventing vital supplies from reaching Axefall.\n\nI require no proof of her demise, simply ensure her screech never again echoes among the spires.\n\nShe nests above the howling crag to the northeast.", objectives = "Kill Venombarb.", completion = "A thousand thanks to you, commander. I will call for more supply runs immediately." }
WordHunterWoW_QuestEN[35673] = { title = "Nagrand - Treasure 014 - Appropriated Warsong Supplies", description = "", objectives = "" }
WordHunterWoW_QuestEN[35674] = { title = "WANTED: Keeho's Severed Paw", description = "Posted by: Lieutenant Willem\n\nKeeho, a monstrous saberon, has taken to raiding Southport at night. We're losing men left and right.\n\nI offer a hefty bounty to anyone able to track down Kreeho and bring his severed paw to me.", objectives = "Retrieve Keeho's Severed Paw from Keeho the Savage.", progress = "Pleasure to see you, sir.", completion = "Well done, commander. For the Alliance!" }
WordHunterWoW_QuestEN[35675] = { title = "WANTED: Spineslicer's Husk", description = "Posted by: Quartermaster Jolie\n\nWe're running out of supplies to repair our troops' armor.\n\nI'll pay handsomely for the husk of the mighty ravager Spineslicer. It would provide us with repair materials for weeks.", objectives = "Retrieve Spineslicer's Husk from Spineslicer.", progress = "Oh, commander! What an honor!\n\nHow can I help you?", completion = "I didn't think anyone could actually kill the beast. Thank you, commander!" }
WordHunterWoW_QuestEN[35676] = { title = "WANTED: Venombarb", description = "Posted by: Falrogh\n\nVenombarb taunts me every day. Screeching and killing me buzz.\n\nSomebody, anybody, kill the beast. I don't want proof, I want peace and quiet.", objectives = "Kill Venombarb.", completion = "By Muradin'sh beard... you actually killed the beasht. Praishe be to ye, commander ...hic!" }
WordHunterWoW_QuestEN[35677] = { title = "Treasure: Sunken Fishing Boat", description = "", objectives = "" }
WordHunterWoW_QuestEN[35678] = { title = "Nagrand - Treasure 015 - Warsong Lockbox", description = "", objectives = "" }
WordHunterWoW_QuestEN[35679] = { title = "Garrison Campaign: The Fall of Shattrath", description = "Greetings, {name}. I bring another message from Archmage Khadgar.\n\nWe can no longer ignore Socrethar's presence at Shattrath. He spreads dangerous beliefs, converting more draenei to his \"new order\" with each passing day.\n\nThe time has come for us to confront him.\n\nExarch Maladaar should be expecting you at the Spire of Light in Talador. Good luck, {name}.", objectives = "Speak to Exarch Maladaar at the Spire of Light in Talador.", completion = "I am glad to see you, <name>. Your aid will be invaluable in this critical hour." }
WordHunterWoW_QuestEN[35680] = { title = "Garrison Campaign: The Fall of Shattrath", description = "Greetings, {name}. I bring another message from Archmage Khadgar.\n\nWe can no longer ignore Socrethar's presence at Shattrath. He spreads dangerous beliefs, converting more draenei to his \"new order\" with each passing day.\n\nThe time has come for us to confront him.\n\nLady Liadrin should be expecting you at the Spire of Light in Talador. Good luck, {name}.", objectives = "Speak to Lady Liadrin at the Spire of Light in Talador.", completion = "I am glad to see you, <name>. Your aid will be invaluable in this critical hour." }
WordHunterWoW_QuestEN[35681] = { title = "Garrison Supplies", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "A new breastplate, well, a new enough breastplate. I will make sure this is put to good use." }
WordHunterWoW_QuestEN[35682] = { title = "Nagrand - Treasure 016 - Warsong Spear", description = "", objectives = "" }
WordHunterWoW_QuestEN[35683] = { title = "Reclaiming the City", description = "The Shattrath offensive is going well, but Socrethar refuses to show himself.\n\nDespite our best efforts, we are unable to break into the inner city of Shattrath. The dome's defenses are simply too strong.\n\nHowever, we think we can lure Socrethar out of hiding. Defeat his lieutenants and warriors, and gather their medallions of service.\n\nWhen we show him proof of their demise, his pride will surely force him to face us.", objectives = "Collect 100 Sargerei Insignias.", progress = "What I ask is no easy task, for his scions are formidable. How goes the offensive?", completion = "Excellent. These insignias will surely bring Socrethar out of hiding." }
WordHunterWoW_QuestEN[35684] = { title = "Reclaiming the City", description = "The Shattrath offensive is going well, but Socrethar refuses to show himself.\n\nAnd despite our best efforts, we are unable to break into the inner city, where he resides.\n\nHowever, we think we can lure Socrethar out of hiding. Defeat his lieutenants and warriors, then gather their medallions of service.\n\nWhen we show him proof of their demise, his pride will surely force him to face us.", objectives = "Collect 100 Sargerei Insignias.", progress = "What I ask is no easy task, for his followers are formidable. How goes the offensive?", completion = "Excellent. These insignias will surely bring Socrethar out of hiding." }
WordHunterWoW_QuestEN[35685] = { title = "Socrethar's Demise", description = "Meet me down by the entrance to the Shattrath dome.\n\nThere, we will issue our challenge to the Sargerei leader. If he accepts our challenge, it is there that he shall meet his end.\n\nThe creature that calls himself Socrethar was once my brethren. I can only hope that there is still some Light left within him.", objectives = "Kill Socrethar.", completion = "Finally, it is done. Othaar... my old friend... be at peace now." }
WordHunterWoW_QuestEN[35686] = { title = "Rage and Wisdom", description = "An endless war wages between the creatures of the eastern wilds and the beasts of the western wasteland.\n\nShould one side overwhelm the other, all of Draenor would fall at the hand of the victor.\n\nI sent Rangari Erdanii to the heart of the battle between these two forces. It is likely that she will need your help, commander.", objectives = "Speak to Rangari Erdanii at Affliction Ridge.", completion = "These creatures are relentless in their assault against one another." }
WordHunterWoW_QuestEN[35687] = { title = "Socrethar's Demise", description = "Meet me down by the entrance to the Shattrath dome.\n\nThere, we shall issue our challenge to the Sargerei leader. If he accepts, it is there that he shall meet his end.\n\nI must admit, {name}, I am looking forward to this.", objectives = "Kill Socrethar.", progress = "What is it?", completion = "Finally, it is done. This creature of darkness shall torment us no longer. Shattrath is free of his taint." }
WordHunterWoW_QuestEN[35688] = { title = "Vignette: Enavra Varandi", description = "", objectives = "" }
WordHunterWoW_QuestEN[35689] = { title = "A Few Artifact Fragments", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Every little bit helps." }
WordHunterWoW_QuestEN[35690] = { title = "A Bunch of Artifact Fragments", description = "", objectives = "The more, the better!", progress = "The more, the better!", completion = "That must of taken great effort to get back to us. You deserve this reward, friend." }
WordHunterWoW_QuestEN[35691] = { title = "A TON of Artifact Fragments", description = "", objectives = "As much as you can carry.", progress = "As much as you can carry.", completion = "Great work, <class>! I will let Vindicator Maraad know of your bravery." }
WordHunterWoW_QuestEN[35692] = { title = "Nagrand - Treasure 010 - Freshwater Clam", description = "", objectives = "" }
WordHunterWoW_QuestEN[35693] = { title = "A Harsh Reminder", description = "Welcome to the front lines, commander, where the wastelands and the jungle collide.\n\nThe battle below rages on, but I believe one side is beginning to overwhelm the other. This cannot be allowed to happen.\n\nThe gronnlings are gaining an upper hand and must be stopped before they pose a threat to Highpass.\n\nI will get closer to the battle while you thin their ranks. Meet me within Affliction Ridge when you are done.", objectives = "Kill 8 denizens of the wasteland in Affliction Ridge.", completion = "You have a true talent for combat." }
WordHunterWoW_QuestEN[35694] = { title = "Nagrand - Treasure 011 - Golden Kaliri Egg - TSH", description = "", objectives = "" }
WordHunterWoW_QuestEN[35695] = { title = "Nagrand - Treasure 022 - Warsong Cache", description = "", objectives = "" }
WordHunterWoW_QuestEN[35696] = { title = "Nagrand - Treasure 048 - Burning Blade Cache", description = "", objectives = "" }
WordHunterWoW_QuestEN[35697] = { title = "Peace Offering", description = "We need allies amongst these spires, and quickly. Commander, I believe it would be wise if you sought out aid.\n\nThere is a lone arakkoa outcast southeast of here living near a ravager nest. The ravagers do not attack him - I suspect he has information on the beasts we may be able to use.\n\nI have our last crate of cactus apple surprise ready for you. It is our best shot, sir.", objectives = "Deliver the Crate of Cactus Apple Surprise to Dusk-Seer Irizzar in the Spires of Arak.", progress = "Any luck, commander?", completion = "I believe we can come to an arrangement, savior of Skettis. But first..." }
WordHunterWoW_QuestEN[35699] = { title = "Peace Offering", description = "We could really use an ally to trade with, commander.\n\nThere's an arakkoa outcast living in the middle of a ravager nest northeast of here... do you think he might ally with us? He must have some sort of secret to keeping those ravagers at bay.\n\nI have one last crate of my Northshire Port. Maybe that will help convince him that we're friendly.", objectives = "Deliver the Crate of Northshire Port to Dusk-Seer Irizzar.", progress = "Welcome back! How did things go with the arakkoa?", completion = "I believe we can come to an arrangement, savior of Skettis. But first..." }
WordHunterWoW_QuestEN[35701] = { title = "Tracking: Mill Treasure 1", description = "", objectives = "" }
WordHunterWoW_QuestEN[35702] = { title = "Chains of Iron", description = "The artifact we seek is within our grasp.\n\nBe prepared for a fight. If they truly have learned how to control gronn, this may be more difficult than I anticipated.\n\nI will join you in this battle as soon as you arrive.", objectives = "Defeat Captain Brak and find the Heart of the Magnaron.", progress = "We have the artifact, and with it we will make the Iron Horde pay.", completion = "Yes... Think of the orcs that will fall before us with this power..." }
WordHunterWoW_QuestEN[35703] = { title = "Tracking: Mill Treasure Barrier 1", description = "", objectives = "" }
WordHunterWoW_QuestEN[35704] = { title = "When All Is Aligned", description = "The ravenspeaker acolytes have been equipped with Apexis interfaces, they just need to get close enough.\n\nCome, let us take to the skies and secure the Terrace of Dawn.\n\nWhen all is aligned, we shall turn the false suns against one another and the spires shall burn like torches!\n\nI look forward to penning your actions into history.", objectives = "Fly upon Ka'alu and kill 80 Adherents.", completion = "Percy and I want to give you something as a token of our thanks. It's not much but please, take your reward." }
WordHunterWoW_QuestEN[35705] = { title = "Best Deals Anywhere", description = "Commander, two goblin smugglers - Mixxy and Trixxy Weldblast - came through here recently and went off towards the bog to the east.\n\nThey had drilling equipment but weren't carrying any weapons, sir.\n\nI'd bet anything that they'll have materials we'd want, and that they could use some protection in return.\n\nCommander, I think seeking them out would be a good idea.", objectives = "Speak to Mixxy Weldblast in Murkbog.", completion = "I don't know what you're doin' all the way out here, but mind helpin' a gal out since you're stopping by?" }
WordHunterWoW_QuestEN[35706] = { title = "Sticky Situation", description = "We were hauling batteries to the excavation site and I crashed my freakin' car!\n\nMy sister didn't even look back. I took the turn a little fast, so what? It happens!\n\nPoint is, the batteries went flying everywhere and I'm in no condition to lift them out.\n\nSo what do you say? Wanna help me out?", objectives = "Retrieve 5 Submerged Batteries.", progress = "Do you have the batteries?", completion = "You're a real doll. Let's get out of here." }
WordHunterWoW_QuestEN[35707] = { title = "Tangleheart", description = "Hey there, peach. We've got the lumber mill good and ready, but we gotta find a way of choppin' wood fast out here.\n\nThe Laughing Skull talked about Tangleheart, where the botani grow things quick as a quark.\n\nI'm headin' there now.", objectives = "Speak to Penny Clobberbottom outside Tangleheart.", completion = "Hey! Looky what I found here." }
WordHunterWoW_QuestEN[35708] = { title = "Tangleheart", description = "The Rangari have been here for a tick, and they hear tell from the Laughing Skull o' a place called Tangleheart.\n\nSeems some really bad ancients come from there, and botani use a kind o' sap to grow them quickly.\n\nI think we could use that for yer outpost. Hey, wood is wood, right?\n\nI'll meet ya there.", objectives = "Speak to Glirin outside Tangleheart.", completion = "Cheers! I found a goblin skulkin' about here. Think I'll keep 'er around. Says she knows things about lumberjackin'." }
WordHunterWoW_QuestEN[35709] = { title = "Treasure: Laughing Skull Cache I", description = "", objectives = "" }
WordHunterWoW_QuestEN[35711] = { title = "Nagrand - Treasure 059 - Abu'gar's Tenacity", description = "", objectives = "" }
WordHunterWoW_QuestEN[35712] = { title = "Nagrand - Vignette Boss 012 - Redclaw the Feral", description = "", objectives = "" }
WordHunterWoW_QuestEN[35713] = { title = "The Tinkertoss Twins", description = "Commander, two gnomish smugglers passed by while you were out - Filbert and Dilbert Tinkertoss. They were headed towards the bog to the east.\n\nThey had all sorts of drilling equipment but didn't seem to have any weapons.\n\nWhat do you think of offering them protection in exchange for some of their materials?\n\nI'll jot down where they were headed in case you decide to go.", objectives = "Speak to Filbert Tinkertoss in Murkbog.", completion = "You're armed to the teeth! Say, would you be interested in helping a weary gnome out?" }
WordHunterWoW_QuestEN[35714] = { title = "Nagrand - Vignette Boss 001 - Greatfeather", description = "", objectives = "" }
WordHunterWoW_QuestEN[35715] = { title = "Nagrand - Vignette Boss 002 - Gar'lua the Wolfmother", description = "", objectives = "" }
WordHunterWoW_QuestEN[35716] = { title = "Sticky Situation", description = "A squadron of arakkoa spotted us while we were en route to the excavation site and took out our caravan. My brother made it to safety in the chaos.\n\nLucky son of a tinker.\n\nI can't leave without the batteries for our drill, but they all fell into the bog and I can't even get them to budge.\n\nAny chance you could retrieve them for me?", objectives = "Retrieve 5 Submerged Batteries.", progress = "Any luck?", completion = "You're a lifesaver! Let's get these to the excavation site." }
WordHunterWoW_QuestEN[35717] = { title = "Nagrand - Vignette Boss 015 - Gnarlhoof the Rabid", description = "", objectives = "" }
WordHunterWoW_QuestEN[35718] = { title = "Back on Track", description = "You're a lifesaver, I'll tell you what.\n\nSay, how about you go on ahead to the excavation site and let my sister know I'm on my way. I'll get everything neat and tidy and go get a new cart to lug these over.", objectives = "Speak to Trixxy Weldblast in Veil Zekk.", completion = "Oh, Mixxy sent you? What a relief. I'm not even armed!" }
WordHunterWoW_QuestEN[35719] = { title = "Back on Track", description = "Now that the batteries are out of the bog I can radio in some more copters to take them to camp.\n\nI'll stay here until they arrive, but you should go ahead to my brother Dilbert and let him know what happened. He must be worried sick!", objectives = "Speak to Dilbert Tinkertoss in Veil Zekk.", completion = "Oh, thank goodness. I don't even have any weapons!" }
WordHunterWoW_QuestEN[35720] = { title = "Seamless Breastplate", description = "", objectives = "" }
WordHunterWoW_QuestEN[35721] = { title = "Old Balance Treads", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "A new set of footwear is always welcome. You ever march across Azeroth? No? Well, if you do, take multiple pairs of shoes, unless you're a troll I guess. I will make sure these are put to good use." }
WordHunterWoW_QuestEN[35722] = { title = "Re-Soled Treads", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "A new set of footwear is always welcome. You ever march across Azeroth? No? Well, if you do, take multiple pairs of shoes, unless you're a troll I guess. I will make sure these are put to good use." }
WordHunterWoW_QuestEN[35723] = { title = "Two-Toned Greaves", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Many neglect protecting their lower legs. Just ask One-Legged Tom. I will make sure these are put to good use." }
WordHunterWoW_QuestEN[35724] = { title = "Blood-Washed Greaves", description = "", objectives = "" }
WordHunterWoW_QuestEN[35725] = { title = "Vignette: Faebright", description = "", objectives = "" }
WordHunterWoW_QuestEN[35726] = { title = "Balanced Short Sword", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "A short sword, we can always use new blades. It's too bad it isn't longer, but they can't all be long swords.  I will make sure it's put to good use." }
WordHunterWoW_QuestEN[35727] = { title = "Slightly-Bent Short Sword", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "A short sword, we can always use new blades. I will make sure it's put to good use." }
WordHunterWoW_QuestEN[35728] = { title = "Decent Barrier Shield", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Many around here could use a good shield. It's never good to get too close with the enemy.  I will make sure this is put to good use." }
WordHunterWoW_QuestEN[35729] = { title = "Frosty Bulwark", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Many around here could use a good shield. It's never good to get too close with the enemy.  I will make sure this is put to good use." }
WordHunterWoW_QuestEN[35730] = { title = "Cauterizing Wounds", description = "You have saved my most precious companion, Nisha. I owe you a great debt.\n\nThe Iron Horde lured me away to separate us. I shall not make the same mistake again.\n\nThey have inflicted grievous wounds, and I fear we must cause her even more pain before the healing process can begin.\n\nPlease use a burning log from the nearby fire to cauterize her wounds.\n\nI will hold her down.", objectives = "Use a Burning Log to cauterize Nisha's wounds.", progress = "Nisha must make it through this.", completion = "Thank you. Her wounds have closed." }
WordHunterWoW_QuestEN[35731] = { title = "Vignette: Ba'ruun", description = "", objectives = "" }
WordHunterWoW_QuestEN[35732] = { title = "Vignette: Shinri", description = "", objectives = "" }
WordHunterWoW_QuestEN[35733] = { title = "Rites of the Talonpriests", description = "That gavel was once known as Beakbreaker. In his final, darkest days, Terokk used it to perform grim, damnable acts of sacrifice. \n\nIt is best not to dwell on those days.\n\nTerokk was sealed away deep within the shadows to rest, and perhaps to heal.\n\nMaking contact with him will take a great deal of effort, so in the meantime, allow me to tell you of his more glorious exploits. Before this wretched curse took hold.\n\nPlease, place the gavel upon the effigy.", objectives = "Place Terokk's Gavel on the Effigy of Terokk.", completion = "<As you place the gavel at the base of the effigy, Reshad speaks over your shoulder.>" }
WordHunterWoW_QuestEN[35734] = { title = "The Talon King", description = "<As Reshad begins reciting a tale of Terokk's glory days, your eyes fall to the twin swords at the effigy's belt.\n\nThey had seemed so plain in Skettis, but now they thrum with power, as if reacting to the scrollkeeper's words.>", objectives = "Use the Effigy of Terokk to re-live Terokk's battle with the Bloodmane. Slay 30 Bloodmane Shortfangs, 20 Mature Bloodmane saberon, and Pridelord Karash.", completion = "That was but one of many such tales.\n\nNo arakkoa living or dead has ever compared to the Talon King." }
WordHunterWoW_QuestEN[35735] = { title = "Nagrand - Vignette Boss 021 - Berserk Shredder", description = "", objectives = "" }
WordHunterWoW_QuestEN[35736] = { title = "Writing in the Snow", description = "This is a worn page from Shadow Hunter Bwu'ja's journal. It appears to be a sketch of the entrance of the Bloodmaul Slave Mines. Rokhan, in your garrison, would be very interested in this.", objectives = "Deliver the tattered journal page to Rokhan in your garrison.", completion = "Excellent work. Your service is always appreciated, <name>." }
WordHunterWoW_QuestEN[35737] = { title = "Writing in the Snow", description = "This is a worn page from Owynn Graddock's journal. It appears to be a sketch of the entrance of the Bloodmaul Slave Mines. Bodrick Grey, in your garrison, would be very interested in this.", objectives = "Deliver the tattered journal page to Bodrick Grey in your garrison.", completion = "Excellent work. Your service is always appreciated, <name>." }
WordHunterWoW_QuestEN[35738] = { title = "All Natural", description = "So you have a smuggler's den, huh?\n\nI'd love to trade with ya, toots, I really would, but my laser cannon isn't even functional right now.\n\nI'll tell you what. See all the ancients around here? They got toasted good by the arakkoa's weapon, and they're practically walking piles of charcoal.\n\nBring me some charcoal to power this thing and you've got a deal.", objectives = "Collect 30 Fresh Charcoal from ancients.", progress = "If you've got the stuff, let's talk.", completion = "That ought to do it! Nice work." }
WordHunterWoW_QuestEN[35739] = { title = "All Natural", description = "Oh, you have a trading post?\n\nFantastic!\n\nLet's make a deal. You help me power up my laser cannon, and I'll trade some of this... thermo... ultra... obsidiglass with you for some weapons.\n\nThe ancients all around here are practically made of charcoal after the arakkoa weapon hit, you should go get some of that!", objectives = "Collect 30 Fresh Charcoal from ancients.", progress = "Blasted refurbished goblin tech is always malfunctioning.", completion = "That's... quite a bit of charcoal. Nicely done!" }
WordHunterWoW_QuestEN[35740] = { title = "Frightening Voodoo Doll", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Voodoo dolls are highly prized by many soldiers. I will see that this one makes it into their hands." }
WordHunterWoW_QuestEN[35741] = { title = "Sad Voodoo Doll", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Voodoo dolls are highly prized by many soldiers. I will see that this one makes it into their hands." }
WordHunterWoW_QuestEN[35742] = { title = "Attuned Alchemist Stone", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "It's good to see that the alchemist stone has been restored. I will make sure that it is delivered to your master alchemist. He was looking for a new stone for his apprentice." }
WordHunterWoW_QuestEN[35743] = { title = "Lesser Alchemist Stone", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "It's good to see that the alchemist stone has been restored. I will make sure that it is delivered to your master alchemist. He was looking for a new stone for his apprentice." }
WordHunterWoW_QuestEN[35744] = { title = "Ending Executions", description = "We arrived as soon as we could... but we be too late. Da Iron Horde has taken our warriors prisoner.\n\nNo doubt they be trying ta squeeze info out of da troops.\n\nI fear once they are done with da interrogation they gonna execute their prisoners. Time be running out.", objectives = "Kill 3 Ironmarch Executioners", completion = "Da prisoners be shaken up, but they are free. We be in your debt, <name>." }
WordHunterWoW_QuestEN[35745] = { title = "Attack of the Iron Horde", description = "We received reports of the Dark Portal turning red right before the attack. They call themselves the Iron Horde.\n\nTheir army is extremely well equipped, and their numbers appear to be unending.\n\nThey have already taken Okril'lon Hold and Nethergarde Keep. Our troops on the frontlines could use your help, {class}.", objectives = "Kill 8 Ironmarch Grunts.", completion = "Aka'Magosh, champion. I'm sure your presence on the field was inspiring for the troops." }
WordHunterWoW_QuestEN[35746] = { title = "Under Siege", description = "Those Iron Horde cannons are laying waste to our troops. I'm not sure how much more of this we can handle. Our forces are already spread too thin.\n\nThere has to be a way to stop those war machines.", objectives = "Sabotage 3 Iron Demolishers.", completion = "It will take the Iron Horde quite a while to get those demolishers operational again. Throm-Ka, <name>." }
WordHunterWoW_QuestEN[35747] = { title = "Taking a Trip to the Top of the Tank", description = "We cannot risk the reactivation of the Dark Portal. Now is the time for the deathblow.\n\nThaelin should have figured out how to get that tank working by now. Take him with you, and turn that tank against the Dark Portal itself. We will follow behind you.", objectives = "Speak with Thaelin Darkanvil, then escort him to the top of the Iron Worldbreaker.", completion = "This... I can work with this." }
WordHunterWoW_QuestEN[35748] = { title = "Subversive Scouts", description = "We have been unable to execute a vast majority of our battleplans. We are definitely being watched.\n\nThe Iron Horde must have scouts planted throughout the Blasted Lands. Victory is slipping away from us.", objectives = "Kill 5 Iron Horde scouts.", completion = "You killed how many scouts? No wonder we have been unable to execute our plans..." }
WordHunterWoW_QuestEN[35749] = { title = "Passable Old Staff", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Ah a staff, the staple mage weapon. If only more would use them, they provide such better protection than carrying around a book, or lamp. I will see if I can make sure a few more staves are handed out first." }
WordHunterWoW_QuestEN[35750] = { title = "Lunatic Lieutenants", description = "It is time we learned more about our new enemy.\n\nOur scouts have identified a number of the Iron Horde's lieutenants. Their attack is too organized to be run by tribal knowledge alone. Surely their lieutenants have access to secret battleplans. \n\nYou are the only soldier I can trust with this mission, {name}.", objectives = "Collect Iron Horde battleplans.", progress = "Were you able to gain access to any battleplans?", completion = "Let's take a look at these battleplans." }
WordHunterWoW_QuestEN[35751] = { title = "Attack on Nethergarde", description = "The Iron Horde controls Nethergarde Keep, but they are fools if they think we will let them retain such a strategic position.\n\nMy best troops are more than eager to spill the blood of those savages, but we need a champion like yourself to lead the charge.", objectives = "Plant the Horde flags inside Nethergarde Keep.", completion = "The Iron Horde will learn to fear us, as they should." }
WordHunterWoW_QuestEN[35752] = { title = "Magically Banded Totem", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Totems are fierce weapons. At times I wish they could be wielded by all, but in the hands of our larger soldiers they are devastating." }
WordHunterWoW_QuestEN[35753] = { title = "Sanded Totem", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Totems are fierce weapons. At times I wish they could be wielded by all, but in the hands of our larger soldiers they are devastating." }
WordHunterWoW_QuestEN[35754] = { title = "Leering Ritual Mask", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Ooh a ritual mask. Many of our warriors are used to wearing masks into battle, I am sure one would find this beneficial." }
WordHunterWoW_QuestEN[35755] = { title = "Intricately Carved Battle Staff", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Ah a staff, the staple mage weapon. If only more would use them, they provide such better protection than carrying around a book, or lamp. I will see if I can make sure a few more staves are handed out first." }
WordHunterWoW_QuestEN[35756] = { title = "Disturbing Ritual Mask", description = "", objectives = "" }
WordHunterWoW_QuestEN[35757] = { title = "Extendable Wand", description = "", objectives = "" }
WordHunterWoW_QuestEN[35758] = { title = "Patched Wand", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Perfect, we needed more wands. You would be surprised how rare wands are these days, one would think they have gone out of style." }
WordHunterWoW_QuestEN[35759] = { title = "Nagrand - Treasure 065 - Abandoned Cargo", description = "", objectives = "" }
WordHunterWoW_QuestEN[35760] = { title = "Toothsmash the Annihilator", description = "If the battleplans you brought back are true, the Dreadmaul ogres are as much to blame for this devastation as the Iron Horde. It's time we send those ogres a message.\n\nIt looks like the Iron Horde's main contact is a large ogre in Dreadmaul named Toothsmash. Killing him will put a dent in their battleplans.", objectives = "Kill Toothsmash the Annihilator", completion = "Toothsmash is dead? Good, I'm sure it will take the Iron Horde a while to find another ogre smart enough to help them with their efforts." }
WordHunterWoW_QuestEN[35761] = { title = "Ransacking Nethergarde", description = "After the Iron Horde took Nethergarde we attacked. While we killed the Iron Horde at Nethergarde they brought more forces through the portal and took Okril'lon Hold. So many souls stripped of their bodies by those savages.\n\nWe must not forget those that gave their lives at Nethergarde. If you find any mementos of the fallen, bring them back to me.", objectives = "Collect Master Aitokk's Axe, Neka's Poison Flask, and Overseer Struk's Shield.", progress = "Did you find anything?", completion = "Throm-Ka, <name>. These mementos will forever remind us of our champions." }
WordHunterWoW_QuestEN[35762] = { title = "Death to the Dreadmaul", description = "The stupidity of the Dreadmaul ogres never ceases to amaze me. The Iron Horde is clearly using them to further their own nefarious agenda.\n\nRegardless, we must show the ogres what happens when you confront the true Horde. I think it's time we send the Dreadmaul ogres a message.", objectives = "Kill 8 Dreadmaul Ogres.", completion = "It's important that our enemies understand what happens when you attack the true Horde. I'm glad you could be there to show them." }
WordHunterWoW_QuestEN[35763] = { title = "Gar'mak Bladetwist", description = "With the intelligence you have gathered we have learned this assault is being led by a powerful Iron Horde orc named Gar'mak Bladetwist. He is hunkered down inside Okril'lon Hold.\n\nKilling him will not win this war, but it will surely break down the Iron Horde's communication. This will buy us valuable time while we gather more forces and outline a battleplan to deal with this new threat.", objectives = "Kill Gar'mak Bladetwist.", completion = "It was an honor fighting alongside of you, <name>." }
WordHunterWoW_QuestEN[35764] = { title = "Okrilla's Revenge", description = "The Dreadmaul ogres think they have bested us? They will all suffer. Here take this poison, place a couple drops in their rat stew.\n\nThe poison will slowly eat away at their insides. Causing a prolonged and painful death, just like they deserve.", objectives = "Poison the Dreadmaul ogre food supply.", completion = "I wish I could be there to watch their faces as they suffer. I hope they all die a slow horrible death." }
WordHunterWoW_QuestEN[35765] = { title = "Nagrand - Treasure 049 - Adventurer's Pack", description = "", objectives = "" }
WordHunterWoW_QuestEN[35766] = { title = "I See Dead Arakkoa", description = "I've got a strange problem and I'm hoping you might be able to help. I don't know who else could help, to be honest.\n\nMy workers keep saying they're seeing the ghost of the arakkoa that used to head up this place.\n\nI know, I know, it's crazy but could you take my Ghostogrifier 12000 to her body and check?\n\nIf there's a ghost around here, it'll find it. If there's not, then my workers are trying to slack off on the clock.", objectives = "Use the Ghostogrifier 12000 and kill the spirit of Talonpriest Zekk.", completion = "Well, I'll be. Ghosts. Who knew?" }
WordHunterWoW_QuestEN[35767] = { title = "Experimental Healing Potion", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "The troops can always use the extra healing potions in the field. I'll distribute them out immediately!" }
WordHunterWoW_QuestEN[35768] = { title = "Ultra Healing Potion", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "The troops can always use the extra healing potions in the field. I'll distribute them out immediately!" }
WordHunterWoW_QuestEN[35769] = { title = "Empowered Scroll", description = "", objectives = "" }
WordHunterWoW_QuestEN[35770] = { title = "Alchemist Notebook", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "I see you found the missing alchemy apprentice's field guide. I'm sure they will be happy to see that all of the sections were restored. I will return it to their master for safe keeping." }
WordHunterWoW_QuestEN[35771] = { title = "Legible Scroll", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "A good buff scroll can mean everything in the thick of battle. I will make sure that this is available to our troops." }
WordHunterWoW_QuestEN[35772] = { title = "Alchemist Field Guide", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "I see you found the missing alchemy apprentice's field guide. I'm sure they will be happy to see that all of the sections were restored. I will return this to their master for safe keeping." }
WordHunterWoW_QuestEN[35773] = { title = "Strangely Pleasant Painting", description = "", objectives = "" }
WordHunterWoW_QuestEN[35774] = { title = "\"Mostly Stable\" Elixir", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "I'm glad you were able to stabilize this dangerous elixir. We weren't sure what else we would have done with it if it was still as volatile as before. We'll keep this on hand if our troops need an extra boost in strength." }
WordHunterWoW_QuestEN[35775] = { title = "Moldy Book", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Ooh, a mysterious tome. These contain valuable secrets that could aid a soldier in battle." }
WordHunterWoW_QuestEN[35776] = { title = "Overly Clear Book", description = "", objectives = "" }
WordHunterWoW_QuestEN[35777] = { title = "Unbendable Card", description = "", objectives = "" }
WordHunterWoW_QuestEN[35778] = { title = "Nagrand - Vignette Boss 020 - Ancient Blademaster - TSH", description = "", objectives = "" }
WordHunterWoW_QuestEN[35779] = { title = "Bent Card", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Most would scoff at a card, but they underestimate the risk of idle soldiers. Some cards are so beloved and tended by soldiers that their decks are imbued with special powers and handed down." }
WordHunterWoW_QuestEN[35780] = { title = "\"Stable\" Elixir", description = "", objectives = "" }
WordHunterWoW_QuestEN[35781] = { title = "Restored Infantry Cloak", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "We can always use extra cloaks. Who knows how cold the nights can be in this land." }
WordHunterWoW_QuestEN[35782] = { title = "I See Dead Arakkoa", description = "Say, while you're here would you mind helping me out with a major problem?\n\nThe workers keep saying that they're seeing the ghost of the head arakkoa that used to be here.\n\nI don't believe it for a second but could you take my Ghostogrifier 12000 to her body and check?\n\nIf they're not crazy, it'll prove it.", objectives = "Use the Ghostogrifier 12000 and kill the spirit of Talonpriest Zekk.", completion = "You're kidding! What a world." }
WordHunterWoW_QuestEN[35783] = { title = "Draenic Survivalist Cloak", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "We can always use extra cloaks. Who knows how cold the nights can be in this land." }
WordHunterWoW_QuestEN[35784] = { title = "Vignette Boss", description = "", objectives = "" }
WordHunterWoW_QuestEN[35785] = { title = "Abstract Painting", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "A painting? We don't get many of these, but I think this could be just the thing to distract or cheer up the garrison soldier. I know just the place to put it." }
WordHunterWoW_QuestEN[35786] = { title = "Bronze Victory", description = "We're deep in enemy territory, staking our claim. Eventually, the locals will come sniffing around.\n\nWe can't show them weakness. Any attack on us must be met fast and furious.", objectives = "We're deep in enemy territory, staking our claim. Eventually, the locals will come sniffing around.\n\nWe can't show them weakness. Any attack on us must be met fast and furious.", progress = "We're deep in enemy territory, staking our claim. Eventually, the locals will come sniffing around.\n\nWe can't show them weakness. Any attack on us must be met fast and furious.", completion = "With every victory, or claim here grows more strong." }
WordHunterWoW_QuestEN[35787] = { title = "Silver Victory", description = "A victory is a twin-edged axe. It stakes a claim, but it also foments rebellion and revenge. We must be complete and decisive.", objectives = "A victory is a twin-edged axe. It stakes a claim, but it also foments rebellion and revenge. We must be complete and decisive.", progress = "A victory is a twin-edged axe. It stakes a claim, but it also foments rebellion and revenge. We must be complete and decisive.", completion = "Without each battle, or sovereignty here grows, Commander." }
WordHunterWoW_QuestEN[35788] = { title = "Gold Victory", description = "The stronger our enemies, the more soundly we must beat them. With so much at stake, we must strive for total victory.", objectives = "The stronger our enemies, the more soundly we must beat them. With so much at stake, we must strive for total victory.", progress = "The stronger our enemies, the more soundly we must beat them. With so much at stake, we must strive for total victory.", completion = "Our foes cringe, Commander. Hah! They'll lick their wounds for days before even dreaming of another fight." }
WordHunterWoW_QuestEN[35789] = { title = "Infantry Leather Cap", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "The recruits always leave their helms behind and we have a tough time keeping up with the replacement requests. We will return the cap to the stockpile." }
WordHunterWoW_QuestEN[35790] = { title = "Heavy Duty Utilicap", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "The recruits always leave their caps and helmets behind and we have a tough time keeping up with the replacement requests. We will return the cap to the stockpile." }
WordHunterWoW_QuestEN[35791] = { title = "Absorbable Vellum", description = "", objectives = "" }
WordHunterWoW_QuestEN[35792] = { title = "Stitched Saddle Bag", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "You can never have too many saddle bags. With exploration parties going further into the wilderness, they will need to take more supplies. I will deliver this to the next exploration unit." }
WordHunterWoW_QuestEN[35793] = { title = "Transferable Vellum", description = "", objectives = "" }
WordHunterWoW_QuestEN[35794] = { title = "Huntsman's Saddlebag", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "You can never have too many saddle bags. With exploration parties going further into the wilderness, they will need to take more supplies. I will deliver this to the next exploration unit." }
WordHunterWoW_QuestEN[35795] = { title = "Marching Drum", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "The officers have been asking for more equipment to help inspire their men to follow commands. Now we can deliver on their request." }
WordHunterWoW_QuestEN[35796] = { title = "Frenzy War Drum", description = "", objectives = "" }
WordHunterWoW_QuestEN[35797] = { title = "The Ebon Hunter", description = "The laser should be good to go once we get it set up, there's just one more thing I need.\n\nThere's a spore walker that hunts on the delta just southeast from here. It has an apparatus on its face that can fire a powerful laser - way more powerful than what we have hooked up.\n\nI want it.\n\nWe'll be mining faster than you can imagine once we get that bad boy hooked up!", objectives = "Collect an Organic Laser Apparatus from the Ebon Hunter.", progress = "I should probably have mentioned that the laser is pretty... potent.", completion = "Perfection. Let's get it hooked up!" }
WordHunterWoW_QuestEN[35798] = { title = "Treasure: Glowing Cave Blossom", description = "", objectives = "" }
WordHunterWoW_QuestEN[35799] = { title = "Wooly Bedroll", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "With our limited supplies, repairing and repurposing everything is a must. Now we have some extra necessities for our field kits." }
WordHunterWoW_QuestEN[35800] = { title = "Luxurious Bedroll", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "With our limited supplies, repairing and repurposing everything is a must. Now we have some extra necessities for our field kits." }
WordHunterWoW_QuestEN[35801] = { title = "Restored Lace Kerchief", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "I recognize this kerchief, but it appears that you have repaired it. I know someone will be very happy to see this again." }
WordHunterWoW_QuestEN[35802] = { title = "Immaculate Lace Kerchief", description = "", objectives = "" }
WordHunterWoW_QuestEN[35803] = { title = "Lesser Mage Robe", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "This robe will be perfect for one of the apprentice mages. Thank you for keeping our armaments well supplied." }
WordHunterWoW_QuestEN[35804] = { title = "Primal Mage Robe", description = "", objectives = "" }
WordHunterWoW_QuestEN[35805] = { title = "Heavy Duty Knapsack", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Adventurers and scouts go through knapsacks and other bags quickly. Having a few extra on hand will help us keep up with the demand." }
WordHunterWoW_QuestEN[35806] = { title = "Rugged Knapsack", description = "", objectives = "" }
WordHunterWoW_QuestEN[35807] = { title = "Trophy of Glory: Erosian", description = "Defeating Erosian has yielded you a trophy worthy of acclaim.\n\nTake this to Durotan at Beastwatch.", objectives = "Take the trophy to Durotan at Beastwatch in Gorgrond.\n\nProvided item:", completion = "One minute you are skirting the cauldrons avoiding the Gronn, the next a blast a steam followed by burning hot claws.  Erosian's death should make our scouts lives a lot easier!" }
WordHunterWoW_QuestEN[35808] = { title = "Trophy of Glory: Erosian", description = "Defeating Erosian has yielded you a trophy worthy of acclaim.\n\nTake this to Maraad at Highpass.", objectives = "Take the trophy to Maraad at Highpass in Gorgrond.\n\nProvided item:", completion = "One minute you are skirting the cauldrons avoiding the Gronn, the next a blast a steam followed by burning hot claws.  Erosian's death should make our scouts lives a lot easier!" }
WordHunterWoW_QuestEN[35809] = { title = "Trophy of Glory: Dessicus", description = "Defeating Dessicus has yielded you a trophy worthy of acclaim.\n\nTake this to Maraad at Highpass.", objectives = "Take the trophy to Maraad at Highpass in Gorgrond.\n\nProvided item:", completion = "You have defeated yet another deadly beast in Gorgrond.\n\nDessicus cared little on who he preyed upon, they all went into his salt pools forever. You have saved many lives <name>!" }
WordHunterWoW_QuestEN[35810] = { title = "Trophy of Glory: Dessicus", description = "Defeating Dessicus has yielded you a trophy worthy of acclaim.\n\nTake this to Durotan at Beastwatch.", objectives = "Take the trophy to Durotan at Beastwatch in Gorgrond.\n\nProvided item:", completion = "You have defeated yet another deadly beast in Gorgrond.\n\nDessicus cared little on who he preyed upon, they all went into his salt pools forever. You have saved many lives <name>!" }
WordHunterWoW_QuestEN[35811] = { title = "Trophy of Glory: Crater Lord Igneous", description = "Defeating Crater Lord Igneous has yielded you a trophy worthy of acclaim.\n\nTake this to Durotan at Beastwatch.", objectives = "Take the trophy to Durotan at Beastwatch in Gorgrond.\n\nProvided item:", completion = "I thought I felt less quakes in the earth. His fury caused untold damage to this world, it is good that he has fallen to you." }
WordHunterWoW_QuestEN[35812] = { title = "Trophy of Glory: Crater Lord Igneous", description = "Defeating Crater Lord Igneous has yielded you a trophy worthy of acclaim.\n\nTake this to Maraad at Highpass.", objectives = "Take the trophy to Maraad at Highpass in Gorgrond.\n\nProvided item:", completion = "I thought I felt less quakes in the earth. His fury caused untold damage to this world, it is good that he has fallen to you." }
WordHunterWoW_QuestEN[35813] = { title = "Trophy of Glory: Fungal Praetorian", description = "Defeating the Fungal Praetorian has yielded you a trophy worthy of acclaim.\n\nTake this to Maraad at Highpass.", objectives = "Take the trophy to Maraad at Highpass in Gorgrond.\n\nProvided item:", completion = "I've heard tales of the Crimson Fen from the rangari; no one has yet returned from there. If this was the reason then we can all breathe safer now." }
WordHunterWoW_QuestEN[35814] = { title = "Trophy of Glory: Fungal Praetorian", description = "Defeating the Fungal Praetorian has yielded you a trophy worthy of acclaim.\n\nTake this to Durotan at Beastwatch.", objectives = "Take the trophy to Durotan at Beastwatch in Gorgrond.\n\nProvided item:", completion = "I've heard tales of the Crimson Fen from the Laughing Skull and how no one ever returns from there. If this is part of the reason, then we can all breathe safer now." }
WordHunterWoW_QuestEN[35815] = { title = "Trophy of Glory: Charl Doomwing", description = "Defeating Charl has yielded you a trophy worthy of acclaim.\n\nTake this to Durotan at Beastwatch.", objectives = "Take the trophy to Durotan at Beastwatch in Gorgrond.\n\nProvided item:", completion = "Our purpose here was hard enough without a giant beast like Charl harassing our scouts and aggravating the Gronn.\n\nGlory to you <name>!" }
WordHunterWoW_QuestEN[35816] = { title = "Trophy of Glory: Charl Doomwing", description = "Defeating Charl has yielded you a trophy worthy of acclaim.\n\nTake this to Maraad at Highpass.", objectives = "Take the trophy to Maraad at Highpass in Gorgrond.\n\nProvided item:", completion = "Our purpose here was hard enough without a giant beast like Charl harassing our scouts and aggravating the Gronn.\n\nYou have saved the rangari a great deal of punishment with this kill, <name>!" }
WordHunterWoW_QuestEN[35817] = { title = "Trophy of Glory: Roardan the Sky Terror", description = "Defeating Roardan has yielded you a trophy worthy of acclaim.\n\nTake this to Maraad at Highpass.", objectives = "Take the trophy to Maraad at Highpass in Gorgrond.\n\nProvided item:", completion = "The screams of that giant rylak could never be ignored.\n\nYou could never be sure if it was far away or if there would be a sudden shadow followed by your immediate death.  Well done!" }
WordHunterWoW_QuestEN[35818] = { title = "Trophy of Glory: Roardan the Sky Terror", description = "Defeating Roardan has yielded you a trophy worthy of acclaim.\n\nTake this to Durotan at Beastwatch.", objectives = "Take the trophy to Durotan at Beastwatch in Gorgrond.\n\nProvided item:", completion = "The screams of that giant rylak could never be ignored.\n\nYou could never be sure if it was far away or if there would be a sudden shadow followed by your immediate death.  Well done!" }
WordHunterWoW_QuestEN[35819] = { title = "Trophy of Glory: Khargax the Devourer", description = "Defeating Khargax has yielded you a trophy worthy of acclaim.\n\nTake this to Durotan at Beastwatch.", objectives = "Take the trophy to Durotan at Beastwatch in Gorgrond.\n\nProvided item:", completion = "The Laughing Skull have always steered clear of that area because Khargax was very quick for such a huge beast. They will be pleased to know their eaten dead have been avenged." }
WordHunterWoW_QuestEN[35820] = { title = "Trophy of Glory: Khargax the Devourer", description = "Defeating Khargax has yielded you a trophy worthy of showing off at your outpost. \n\nReturn this to Maraad to increase your glory!", objectives = "Take the trophy to Maraad at Highpass in Gorgrond.\n\nProvided item:", completion = "You have done us all a great favor <name>.\n\nThe existence of that slippery hydra wasn't even truly known despite our losses in the area." }
WordHunterWoW_QuestEN[35821] = { title = "Trophy of Glory: Sodius", description = "Defeating Erosian has yielded you a trophy worthy of showing off at your gladiatorial arena. \n\nReturn this to <ARENA NPC NAME> to increase your glory!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Take the trophy to <ARENA NPC NAME> at <HORDE OUTPOST> in Gorgrond.Defeating Erosian has yielded you a trophy worthy of showing off at your gladiatorial arena. \n\nReturn this to <ARENA NPC NAME> to increase your glory!You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[35822] = { title = "Trophy of Glory: Sodius", description = "Defeating Sodius has yielded you a trophy worthy of acclaim.\n\nTake this to Durotan at <HORDE OUTPOST>.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Take the trophy to Durotan at <HORDE OUTPOST> in Gorgrond.Defeating Sodius has yielded you a trophy worthy of acclaim.\n\nTake this to Durotan at <HORDE OUTPOST>.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[35823] = { title = "Sparkling Band", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Often forgotten as armor, rings can often make all the difference in a battle. Their magic is subtle but significant. I will be sure to make sure these make it to the battlefront." }
WordHunterWoW_QuestEN[35824] = { title = "Renewed Band", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Often forgotten as armor, rings can often make all the difference in a battle. Their magic is subtle but significant. I will be sure to make sure these make it to the battlefront." }
WordHunterWoW_QuestEN[35825] = { title = "Imbued Locket", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "This locket still has some magic left in it, I am sure we could out fit a few of our soldiers, even those that think jewelry doesn't suit them." }
WordHunterWoW_QuestEN[35826] = { title = "Used Locket", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "This locket still has some magic left in it, I am sure we could out fit a few of our soldiers, even those that think jewelry doesn't suit them." }
WordHunterWoW_QuestEN[35827] = { title = "Focused Crystal", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Ooh, shiny. I think I can put this crystal to good use in a couple of projects I am working on." }
WordHunterWoW_QuestEN[35828] = { title = "I Drew Aggro...culture", description = "{name}? Boy am I glad to see ya.\n\nI was tryin' ta ditch that genesaur when I stumbled across this rangari camp.\n\nNext thing I know, the ground is creepin' up and spittin' out all sorts of angry plants.\n\nI barely made it out of me tank before that genesaur threw it like it was an empty beer mug.\n\nI'm gonna make my way back to the road an' look fer me tank.\n\nI'll see ya there when yer done.", objectives = "Meet Thaelin Darkanvil at the Wildwood Wash.", completion = "Ah perfect. I'll get this up an' runnin' in no time." }
WordHunterWoW_QuestEN[35829] = { title = "Buffed Crystal", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Ooh, shiny. I think I can put this crystal to good use in a couple of projects I am working on." }
WordHunterWoW_QuestEN[35830] = { title = "Immaculate Statue", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Statues were once a staple of combat on Azeroth, this statue will definitely be put to good use." }
WordHunterWoW_QuestEN[35831] = { title = "Restored Statue", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Statues were once a staple of combat on Azeroth, this statue will definitely be put to good use." }
WordHunterWoW_QuestEN[35832] = { title = "Priceless Gryphon Figurine", description = "", objectives = "" }
WordHunterWoW_QuestEN[35833] = { title = "Crude Gryphon Figurine", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Some claim figurines bring luck on a battlefield. In truth most figurines are imbued with magical properties by craftsman with the gift. It looks like you have a touch of the gift, the soldiers here will prize this." }
WordHunterWoW_QuestEN[35834] = { title = "Wake of the Genesaur", description = "One moment we see a great metal beast rolling into our camp, the next a genesaur follows it and sends a wave of pure chaotic life at us.\n\nThe manifestations left behind by the genesaur must be culled so we have time to salvage what we can before leaving.\n\nIf you are here to help, then start killing as many of the violent plants that are assailing us as possible.", objectives = "Slay 9 Wild Overgrowth.", completion = "A good start. The growth from a genesaur is pure chaos and must be culled whenever possible." }
WordHunterWoW_QuestEN[35835] = { title = "The Ebon Hunter", description = "We're ready to set up the laser, but we're going to need more firepower to cut through this stuff.\n\nThe Ebon Hunter stalks the delta just southeast from here. It has an apparatus on its face that can fire a laser way stronger than what we have hooked up.\n\nWe need that.\n\nYou should go get it while we set up the laser.", objectives = "Collect an Organic Laser Apparatus from the Ebon Hunter.", progress = "By the way, that laser is very dangerous. Be careful!", completion = "Alright, let's put this thing to use!" }
WordHunterWoW_QuestEN[35836] = { title = "Nagrand - Vignette Boss 008 - The Lunker", description = "", objectives = "" }
WordHunterWoW_QuestEN[35837] = { title = "Garrison Campaign: Deep Recon", description = "One of my top field operatives, Jeanine Amrell, is stationed deep in Iron Horde territory in northern Nagrand.\n\nShe reports that the warlords of the orcish clans are planning to convene in secret at Mok'gol Watchpost.\n\nThis may be a critical opportunity for us to gain intel on their future plans.\n\nI need you to meet up with agent Amrell immediately. This may be our chance, {name}!", objectives = "Find Jeanine Amrell at the Hidden Camp in Nagrand.", completion = "<Judging by the marks on her body, the agent put up an impressive fight.>" }
WordHunterWoW_QuestEN[35838] = { title = "The Warlord's Council", description = "Upon closer inspection, you notice a piece of leather parchment looped around her neck.\n\nScrawled upon it angrily are the words:\n\n\"WITNESS THE FATE OF THOSE WHO DEFY THE IRON HORDE!\"", objectives = "Find out who is behind the written note.", completion = "I'm glad I found you, <name>. I've been hiding out since the Warsong orcs ambushed our camp at the Hidden Camp.\n\nYou should have seen the fight that Jeanine put up. Even after they began torturing her, she never gave up that there were two of us.\n\nShe had a will of steel, that one." }
WordHunterWoW_QuestEN[35839] = { title = "Plans of War", description = "I managed to get my hands on Jeanine's notebook. She identified several key items in the nearby buildings to investigate, but couldn't follow up before her demise.\n\nThe least we can do is follow the lead that she left us.\n\nSearch the camp for the intelligence. I'll keep the orcs distracted.", objectives = "Find the Scale Model of Gorgorek, Miniature War Machine, and Map of Tanaan Jungle.", completion = "This is remarkable, <name>. We now have direct proof of Grommash's intentions.\n\nPerhaps now, we can stay a step ahead of the Iron Horde. Great work!" }
WordHunterWoW_QuestEN[35840] = { title = "Intercepting the Orders", description = "Intelligence is the name of the game, friend. The more we know about Hellscream's plans, the easier it will be to thwart them.\n\nThe Mok'gol orcs often act as Hellscream's couriers, carrying mission orders from this place to his outposts all over Draenor.\n\nKill these riders, and recover any orders that you can find.", objectives = "Collect the Frostfire Mission Orders, Shadowmoon Mission Orders, and Spires of Arak Mission Orders.", progress = "Do you have something for me?", completion = "Excellent work, <name>." }
WordHunterWoW_QuestEN[35841] = { title = "Putting Down the Packleader", description = "Operations at Mok'gol Watchpost are entrusted to a mighty warrior named Packleader Vor'gash.\n\nIf we can take out this fierce leader, we can shut down their communications temporarily.\n\nYou can find Vor'gash patrolling the compound to the northeast.\n\nSlay him.", objectives = "Slay Packleader Vor'gash.", completion = "I have heard many reports about Vor'gash. It is a relief to know he will trouble us no more." }
WordHunterWoW_QuestEN[35842] = { title = "Putting Down the Packleader", description = "Da one in charge a Mok'gol Watchpost be Packleader Vor'gash.\n\nWe take him out, we shut dem down.\n\nYa ken find 'im patrolling da compound ta da nor'east.\n\nKill 'im.", objectives = "Slay Packleader Vor'gash.", completion = "I know about dis Vor'gash. It be a relief ta know he won't trouble us no more." }
WordHunterWoW_QuestEN[35843] = { title = "Garrison Campaign: Deep Recon", description = "Ya timin' be good, commanda.\n\nI sent one a ma shadow huntas deep inta da land 'a da enemy.\n\nHe reports dat da warlords be plannin' ta meet in secret at Mok'gol Watchpost.\n\nDis be our chance ta learn what Hellscream be up to.\n\nGo now, and meet wit Zasta. He will tell ya what to do next.", objectives = "Find Shadow Hunter Zasta at the Hidden Camp in Nagrand.", completion = "<Judging by the marks on his body, the shadow hunter put up an impressive fight.>" }
WordHunterWoW_QuestEN[35844] = { title = "The Warlord's Council", description = "Upon closer inspection, you notice a piece of leather parchment looped around his neck.\n\nScrawled upon it angrily are the words:\n\n\"WITNESS THE FATE OF THOSE WHO DEFY THE IRON HORDE!\"", objectives = "Find out who is behind the written note.", completion = "I ben lookin' for ya, commanda. I knew you was comin', but dat nasty orc lady got ta ya afore I could give warnin'.\n\nAt least I could save ya. Poor Zasta. He never saw it comin'." }
WordHunterWoW_QuestEN[35845] = { title = "Plans of War", description = "I managed ta recover Zasta's notes. He saw dey Warsong leaders meetin' often in dey nearby buildings. Zasta tinks dere be clues about dey Iron Horde's plans nearby.\n\nDey least we can do is follow dey lead he left us.\n\nSearch dey camp for dey intelligence. I'll keep dey orcs distracted.", objectives = "Find the Scale Model of Gorgorek, Miniature War Machine, and Map of Tanaan Jungle.", completion = "Now we have proof a Hellscream's intentions.\n\nMebbe now, we ken stay a step ahead a da Iron Horde. Gud work." }
WordHunterWoW_QuestEN[35846] = { title = "Intercepting the Orders", description = "Intelligence be da name a da game, commanda. Da more we know about Hellscream's plans, da easier it be ta mess dem.\n\nDa Mok'gol orcs be Hellscream's couriers, carrying mission orders from dis place ta his outposts all over Draenor.\n\nKill dese riders, an' recover any orders dat you ken find.", objectives = "Collect the Frostfire Mission Orders, Shadowmoon Mission Orders, and Spires of Arak Mission Orders.", progress = "Ya have something for me?", completion = "Dis is gud, <name>. Dis be real gud." }
