WordHunterWoW_QuestEN[35853] = { title = "Super Immunoglobulin Kit", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "With all of the strange diseases in Draenor, we need to boost our immune systems as much as we can. I'll make sure to distribute this out right away!" }
