WordHunterWoW_QuestEN[35861] = { title = "Garrison Campaign: Darktide Roost", description = "We are getting reports that Iron Horde warships are docking on a small island just south of Shadowmoon Valley.\n\nWe sent in some scouts, but we haven't heard back from them yet. It might be worth investigating.\n\nDungar Longdrink has a gryphon waiting for you when you are ready, commander.", objectives = "Travel to Darktide Roost.", completion = "These savages have no honor, it is time we deal with the Iron Horde presence on this island." }
WordHunterWoW_QuestEN[35862] = { title = "Blackrock Cluster Bomb", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "This seems like a great explosive to deter any large enemy from attacking us. I'm sure the engineers will be thrilled to see this in our stockpile." }
