WordHunterWoW_QuestEN[35870] = { title = "Basilisk Butcher", description = "Basilisk is one of Nisha's favorite meals. This is where she hunts, and that's likely how those Iron Horde bastards were able to capture her.\n\nWhy would they go to the trouble to subdue her this way? Perhaps together, you and I might learn the answer as we punish them for their transgressions.\n\nFor now, Nisha's going to need some food. While I tend to her, will you do her hunting for her?", objectives = "Collect 9 Basilisk Meat from Stoneshamble Basilisks or Decaying Basilisks.", progress = "<Nisha sniffs deeply.>", completion = "<Nisha downs the meat in one gulp.>" }
WordHunterWoW_QuestEN[35871] = { title = "A Few Artifact Fragments", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Every little bit helps." }
WordHunterWoW_QuestEN[35872] = { title = "A Bunch of Artifact Fragments", description = "", objectives = "The more, the better!", progress = "The more, the better!", completion = "That must of taken great effort to get back to us. You deserve this reward, friend." }
