WordHunterWoW_QuestEN[35895] = { title = "Terokk's Fall", description = "<Once again, Reshad's voice envelops you.>\n\nTerokk was a powerful and respected king, beloved by his people.\n\nHis sages, however, were not so loyal. Hungry for control of Skyreach, they conspired against him.", objectives = "Use the Effigy of Terokk to re-live Terokk's fall. Find Lithic, rally 5 Outcast Talon Guards, slay 20 Crazed Outcasts, and use the Eye of Anzu.", completion = "Since that day, the sages have remained in power in Skyreach, now calling themselves the Adherents of Rukhmar and claiming to be the heralds of Her will." }
WordHunterWoW_QuestEN[35896] = { title = "The Avatar of Terokk", description = "My long sleep was disturbed by dreams of the past. I cut down my old enemies again. I watched my daughter die again.\n\nYou were there. I felt your presence in these dreams. And your past was revealed to me as well.\n\nSomeone has woven our fates together. My people are yours to protect, and your enemies are mine to destroy.\n\nThe Shattered Hand are rallied in Bladefist Hold. Left to their own, they would claim this land for the Iron Horde.\n\nTake my power, and together we shall break them.", objectives = "Speak with Shade of Terokk to accept his power. Slay 25 Shattered Hand combatants, 4 Shattered Pit-Masters, and confront Kargath Bladefist.", progress = "Take what you have earned, <name>.", completion = "The Shattered Hand is in shambles and the Avatar of Terokk now walks among us.\n\nWhen I promised you power back in Skettis, did you expect that it would come without any strings attached? Ha!" }
WordHunterWoW_QuestEN[35897] = { title = "The Missing Piece", description = "Terokk's daughter Lithic was a skilled huntress, but found her true passion in goldsmithing.\n\nShe forged this bangle as a gift for her father, and he wore it for many years. Only after Lithic passed away did he remove the bangle, for her memory was too much for the old king to bear.\n\nPlace the bangle upon the effigy, and I shall tell you of Terokk's fall.", objectives = "Place Lithic's Gift on the Effigy of Terokk.", completion = "<You carefully hang the bangle upon the effigy's arm.>" }
