WordHunterWoW_QuestEN[35905] = { title = "Supply Drop", description = "Your laborers below have finished with the harvest and are ready to cart supplies back to your garrison. Don't worry about the safety of your caravan this time; I will dispatch a rangari detail to shadow them from the woods and protect them.\n\nThe Exarchs will always watch over you.\n\nYour supplies should be waiting for you when you return to your garrison. Good luck with your campaign, {name}!", objectives = "Speak with Baros Alexston at your garrison in Shadowmoon Valley.", completion = "Commander! Zipfizzle arrived with your laborers in tow just moments ago. We've got a huge surplus of food, now, and promises of more where that came from.\n\nApparently the draenei threw in some other resources as well. Very good work, sir. What should we build next?" }
WordHunterWoW_QuestEN[35906] = { title = "Vignette: Mad \"King\" Sporeon", description = "", objectives = "" }
WordHunterWoW_QuestEN[35907] = { title = "Attempted Murder", description = "Your bartender Lunzul is dying, commander. She's been poisoned and needs an antidote immediately.\n\nOne of your scouts reported seeing a Shattered Hand orc nearby recently - that's our best bet.\n\nThere is a small arakkoa camp to the east that sits near a known Shattered Hand encampment. I suggest we start our search there.\n\nI've already spoken to your flight master about securing us a flight; every second counts.", objectives = "Speak to Hutou Featherwind to secure a flight to Shadow's Vigil.", completion = "These corpses are fresh. Their killers must still be nearby." }
WordHunterWoW_QuestEN[35908] = { title = "Vignette: Stoneshard Broodmother", description = "", objectives = "" }
