WordHunterWoW_QuestEN[35914] = { title = "Internal: Default Invasion Reward", description = "Quakes have been shaking the garrison for the last hour, and a few of our scouts aren't reporting in.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Repel the Breaker invasion of your garrison.\n\n(Speak with Sergeant Grimjaw again to begin)" }
WordHunterWoW_QuestEN[35915] = { title = "Attempted Murder", description = "Kolrigg is dyin', commander. He's been poisoned and needs an antidote before it's too late.\n\nOne o' yer scouts reported seein' a Shattered Hand orc nearby not long ago - I wager that's our best shot.\n\nThere's a small arakkoa camp tae the east that sits near a known Shattered Hand encampment. We should start our search there, sir.\n\nI've already spoken to yer flight master about flyin' us out; every second counts.", objectives = "Speak to Firn Swiftbreeze to secure a flight to Shadow's Vigil.", completion = "Aye, these corpses are definitely fresh. They can't have gone far." }
WordHunterWoW_QuestEN[35919] = { title = "Treasure: Sacrifice", description = "", objectives = "" }
WordHunterWoW_QuestEN[35920] = { title = "Nagrand - Vignette Boss 019 - Tura'aka", description = "", objectives = "" }
WordHunterWoW_QuestEN[35921] = { title = "Bread and Circuses", description = "Hey, mister, this crumb-bum won't let me in. Interested in some cold, hard cash?\n\nMy boss is promoting fights at the Ring of Trials. You look like you could hold your own.\n\nYou should go fight.", objectives = "Speak with Dexyl Deadblade at the Ring of Trials.", completion = "Hey there, bub. Lucy sent you? Good kid.\n\nYeah... you look like you'll do nicely." }
WordHunterWoW_QuestEN[35922] = { title = "Bread and Circuses", description = "Hey, mister, this crumb-bum won't let me in. Interested in some cold, hard cash?\n\nMy boss is promoting fights at the Ring of Trials. You look like you could hold your own.\n\nYou should go fight.", objectives = "Speak with Dexyl Deadblade at the Ring of Trials.", completion = "Hey there, bub. Lucy sent you? Good kid.\n\nYeah... you look like you'll do nicely." }
WordHunterWoW_QuestEN[35923] = { title = "Nagrand - Vignette Boss 006 - Hunter Blacktooth", description = "", objectives = "" }
WordHunterWoW_QuestEN[35924] = { title = "Assassin's Mark", description = "Their poison is more powerful than I thought. We need to find the orc responsible for making it.\n\nMaster assassins always leave their mark somewhere on one of their kills. It's a calling card; a claim to fame in their circles.\n\nThis was definitely the work of such an assassin.\n\nWe should split up and see if we can find some sign on one of the outcast corpses that will lead us to their creator. Rendezvous at the bottom of the hill, commander.", objectives = "Search Vigilant Outcast corpses for a Craftsman's Mark.", progress = "Any luck? I couldn't find anything.", completion = "What is it you found? Let me see that." }
WordHunterWoW_QuestEN[35925] = { title = "The Gronn Strategy", description = "Raz,\n\nYour orders are to capture four additional gronn for weaponization.\n\nOf your first group, only one survived the entire process.\n\nOne attacked our soldiers relentlessly and had to be put down. Another fell victim to a misfire while being fitted. Yet another rolled onto its cannons in its sleep. We're still cleaning up that mess.\n\nRest assured, your efforts are not in vain.\n\n- Captain Brak", objectives = "Show the weaponization orders to Rexxar at Breaker's Crown.", progress = "Weaponizing gronn? If they succeed...", completion = "This is grim news, <name>." }
WordHunterWoW_QuestEN[35926] = { title = "Assassin's Mark", description = "We need tae find the orc responsible fer makin' the poison tae make an antidote.\n\nMaster assassins always leave their mark somewhere on one o' their kills. It's a claim tae fame o' sorts. An' trust me, this was the work of a master assassin.\n\nLet's split up and see if we can find some sign on one o' the outcast corpses that will lead us tae their killer. I'll meet ye at the bottom o' the hill, commander.", objectives = "Search Vigilant Outcast corpses for a Craftsman's Mark.", progress = "Did ye find anything?", completion = "What's that? Let me have a look." }
WordHunterWoW_QuestEN[35927] = { title = "Forsaken Brains", description = "", objectives = "A brain is a vital organ. But for those Undead? Debatable.", progress = "A brain is a vital organ. But for those Undead? Debatable.", completion = "Well done, <name>. Transporting a brain is no easy task. I mean, they're just so darn slippery." }
WordHunterWoW_QuestEN[35928] = { title = "Meatgut Needs Bones", description = "", objectives = "I have plenty of meat. You should buy some.\n\nWhat I really need are bones. Nagrand's animals are the heartiest on all of Draenor. They have the finest-quality bones.\n\nI'm making the tastiest soup you've ever tried. I'll show that Grogglefitz who the best cook truly is.", progress = "I have plenty of meat. You should buy some.\n\nWhat I really need are bones. Nagrand's animals are the heartiest on all of Draenor. They have the finest-quality bones.\n\nI'm making the tastiest soup you've ever tried. I'll show that Grogglefitz who the best cook truly is.", completion = "That's a good start. I'll throw these in the pot.\n\nBring me more." }
WordHunterWoW_QuestEN[35929] = { title = "Blackfathom Deeps Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35930] = { title = "Blackfathom Deeps (Bonus) Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35931] = { title = "Nagrand - Vignette Boss 016 - Warsong Scout", description = "", objectives = "" }
WordHunterWoW_QuestEN[35932] = { title = "Nagrand - Vignette Boss 026 - Warsong Tactician", description = "", objectives = "" }
WordHunterWoW_QuestEN[35933] = { title = "Azeroth's Last Stand", description = "Countless times you have battled against impossible odds and unspeakable evil - and returned the victor. Now, once more, you have answered the call of duty, prepared to risk your life to save the world that you love - our world.\n\nYou are Azeroth's last hope, {name}.\n\nWhile the challenges that stand before us are daunting, there is no other that I would trust to lead this mission.\n\nThe enemy at the front may have the information we need to win this war. Seek and destroy!\n\nGo now, {name}! For Azeroth!", objectives = "Collect the Iron Horde Missive from one of the Iron Horde at the base of the Dark Portal." }
WordHunterWoW_QuestEN[35934] = { title = "Nisha's Vengeance", description = "Since I left on my last hunt, the Iron Horde have drawn nearer and reinforced their positions.\n\n<A grin spreads across Rexxar's lips.>\n\nThey've created a target-rich environment.\n\nI must continue nursing Nisha to health for now. You go in my stead, friend. Fill them with the fear and pain that they inflicted on her.\n\nMake their screams fill the canyon!", objectives = "Kill 10 Grom'kar Grunts.", completion = "Thank you, <name>. Nisha is nearly returned to health." }
WordHunterWoW_QuestEN[35935] = { title = "Iron Horde Invasion!", description = "There's smoke on the horizon.... The Iron Horde is coming.", objectives = "Repel the Iron Horde invasion.", progress = "We must hold the line!", completion = "The Iron Horde is a menace. Let's stamp out the rest of them. For the Horde!" }
WordHunterWoW_QuestEN[35937] = { title = "Blood Elf Ear", description = "", objectives = "If you bring back one with some fancy jewelry still attached, I'll give you a bonus.", progress = "If you bring back one with some fancy jewelry still attached, I'll give you a bonus.", completion = "Bah, no ear rings or anything. Better luck next time, <class>." }
WordHunterWoW_QuestEN[35938] = { title = "Goblin Nose", description = "", objectives = "Did you know even fish can smell better than us?", progress = "Did you know even fish can smell better than us?", completion = "Ha, yea, just some nose trivia for you there. This pointy trophy proves you slayed a Goblin out there. Good job, here's a lil' something for your hard work." }
WordHunterWoW_QuestEN[35939] = { title = "Tauren Hoof", description = "", objectives = "Ever see a Tauren Rogue, <name>?", progress = "Ever see a Tauren Rogue, <name>?", completion = "Of course you haven't! I mean, look at these things...you can't sneak into anything with these things clacking around." }
WordHunterWoW_QuestEN[35940] = { title = "Orc Tooth", description = "", objectives = "It doesn't matter which tooth, an incisor... canine, premolar, whatever. I know an Orc tooth when I see one.", progress = "It doesn't matter which tooth, an incisor... canine, premolar, whatever. I know an Orc tooth when I see one.", completion = "Jeez... somebody didn't brush, eh? Hah, here take this reward <name>." }
WordHunterWoW_QuestEN[35941] = { title = "Troll Feet", description = "", objectives = "Believe me, I wouldn't of asked for their feet if I didn't have to.", progress = "Believe me, I wouldn't of asked for their feet if I didn't have to.", completion = "Oh man, <coughs> ... get that thing sealed into my bucket quick." }
WordHunterWoW_QuestEN[35942] = { title = "Pandaren Hide", description = "", objectives = "Wait a minute... how do I know you skinned these off a Horde and not one of your friends?", progress = "Wait a minute... how do I know you skinned these off a Horde and not one of your friends?", completion = "I'm kidding! I'm kidding! We all know you're a model <class> of Stormshield, <name>. Here, take this as a reward." }
WordHunterWoW_QuestEN[35943] = { title = "Nagrand - Vignette Boss 026 - Duretha", description = "", objectives = "" }
WordHunterWoW_QuestEN[35944] = { title = "Proof of Strength: Goren Tooth", description = "This tooth is proof of your strength at slaying goren and your gladiator friend has born witness!\n\nTake the tooth back to Jonaa and claim your accolades!", objectives = "Take the proof to Rangari Jonaa at Highpass in Gorgrond.\n\nProvided item:", completion = "We are impressed with your ability to slay the goren. They are relentless and voracious and can overwhelm those are not prepared." }
WordHunterWoW_QuestEN[35945] = { title = "Greblin Fastfizzle", description = "I've been hanging here forever!\n\nI was flying around, surveying the area for Nixxie when -- blamo! One of those stupid ogres throws a rock right at me!\n\nMy glider busted and here I am... and boy is this uncomfortable.\n\nHelp me down will ya? I'll make it worth your while.", objectives = "Help Greblin Fastfizzle down.", completion = "Ouch... my leg is still asleep, that smarts... Greblin Fastfizzle's my name, archeology's my game.\n\nHow can I help?" }
WordHunterWoW_QuestEN[35946] = { title = "Peckers the Majestic", description = "You have done me a great service. This blade is as much yours as it is mine.\n\nI offer you this blood oath: I shall serve your cause and lend my knowledge of blades and mining to your forces.\n\nWill you accept it?You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Accept the Blood Oath of Blademaster Na'Shra.You have done me a great service. This blade is as much yours as it is mine.\n\nI offer you this blood oath: I shall serve your cause and lend my knowledge of blades and mining to your forces.\n\nWill you accept it?You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[35947] = { title = "The Power of Poison", description = "G.V.? We need a name and a location. Not damned initials.\n\n<Velonara pulls out a small vial.>\n\nThis is my last vial of wracking poison. We use it to extract information from prisoners. It is... potent.\n\nCoat your weapon with it and head into the Shattered Hand camp just ahead. Engage them as normal and demand answers - the poison will take care of the rest. I've had enough of these orcs.", objectives = "Interrogate Shattered Hand orcs in the Harvesting Pits to find out the name and location of \"G.V.\".", completion = "This Gardul Venomshiv is as good as dead." }
WordHunterWoW_QuestEN[35948] = { title = "Proof of Strength: Goren Tooth", description = "This tooth is proof of your strength at slaying goren and your gladiator friend has born witness!\n\nTake the tooth back to Limbflayer and claim your accolades!", objectives = "Take the proof to Limbflayer at Beastwatch in Gorgrond.\n\nProvided item:", completion = "We are impressed with your ability to slay the goren. They are relentless and voracious and can overwhelm those are not prepared." }
