WordHunterWoW_QuestEN[35959] = { title = "The Power of Poison", description = "G.V.? We need a full name. A  location!\n\nI have an idea fer how we can find those out.\n\n<Hulda pulls out a small vial.>\n\nThis is my last vial o' wracking poison. We use it when we need tae extract information from prisoners.\n\nCoat yer weapon wi' it and head into the Shattered Hand camp just ahead. Engage them as normal and demand answers - the poison will take care o' the rest.", objectives = "Interrogate Shattered Hand orcs in the Harvesting Pits to find out the name and location of \"G.V.\".", completion = "Gardul Venomshiv, eh? He's good as dead." }
