WordHunterWoW_QuestEN[35970] = { title = "Preservation Capitalization", description = "I'm looking for precious artifacts. The kind of artifacts that can help solve some of the greatest mysteries of Draenor, and make the Steamwheedle Preservation Society a ton of moolah. And ladies love the moolah, know what I'm sayin?\n\nSo, get me the artifacts, I'll get the ladies, and you get... wait, what are you looking for again?", objectives = "Collect a Redtooth Necklace, Purpletooth Necklace, and an Ogre Bust.", progress = "What do you find? Anything worth selling? Err.. preserving.", completion = "Nice! What did you get?\n\nA necklace, not bad.. another necklace, good. A giant rock in the shape of an ogre head?\n\n<Greblin seems puzzled, he glances up at you.>\n\nSeriously? This is a rock in the shape of an idiot. Whatever, the necklaces look good.\n\nNot a bad find overall." }
WordHunterWoW_QuestEN[35971] = { title = "Tracking: Mill Treasure 7", description = "", objectives = "" }
WordHunterWoW_QuestEN[35972] = { title = "Ogre Onslaught", description = "Those ogres are standing in the way of a full Steamwheedle Preservation excavation.\n\nThey are brutal, violent, horrible smelling beasts. And if I'm being completely honest with myself, I'm pretty mad they broke my glider.\n\nDo me a favor will ya? Wipe 'em off the face of Draenor.\n\nIt will make everyone's life easier, or at the very least, it will make my life easier.", objectives = "Kill 3 Ogres and 3 Ogron.", completion = "Oh, that's way better.\n\nMaybe next time they'll think twice before they throw a rock at someone. Err... I mean if they weren't so dead and everything." }
WordHunterWoW_QuestEN[35973] = { title = "Brokyo Beatdown", description = "I'm almost done here, but I can't leave in good conscience.\n\nI spotted an ogron named Brokyo that is wearing a priceless ring. Priceless as in crazy expensive.\n\nI'm sure Nixxie will give me a promotion if I bring that ring back to her.", objectives = "Kill Brokyo.", progress = "Did you take care of Brokyo?", completion = "You got the ring? Nice! The Steamwheedle Preservation Society is going to make some serious moolah on this stuff.\n\nNixxie will be pleased." }
WordHunterWoW_QuestEN[35974] = { title = "Assault on Darktide Roost", description = "The Iron Horde has Goblins now? Take them out!", objectives = "Disrupt the Iron Horde and gather intelligence on them." }
