WordHunterWoW_QuestEN[35984] = { title = "Tracking: Mill Treasure 13", description = "", objectives = "" }
WordHunterWoW_QuestEN[35985] = { title = "Garrison Campaign: The Broken Precipice", description = "Hey there! You're the commander of this keep, right? I represent the Steamwheedle Preservation Society.\n\nWe've been trying to get a very important excavation up and running in Nagrand. Unfortunately, we've had trouble with ogres in the area.\n\nIn fact, one of our best preservationists recently went missing while surveying the area. He's the third society member we've lost up there this week!\n\nWe aren't really equipped for a rescue mission... so whad'ya say? We could really use the help.", objectives = "Find Greblin Fastfizzle.", completion = "You're looking for what now? I mean, yeah sure... whatever. Just get me down alright?" }
WordHunterWoW_QuestEN[35986] = { title = "Nagrand - Treasure 021 - Bone-Carved Dagger", description = "", objectives = "" }
WordHunterWoW_QuestEN[35987] = { title = "Nagrand - Treasure 025 - Genedar Debris", description = "", objectives = "" }
WordHunterWoW_QuestEN[35988] = { title = "Call of the Archmage", description = "<The amorphous blob of arcane energy appears to be giving people a tour of your garrison.>\n\nCommander <name>! I was sent here to summon you.\n\nArchmage Khadgar has a very urgent favor to ask. He is gravely concerned about additional threats this world may hold for Azeroth, and he will need your assistance pursuing them. Please see him at his tower, east of Talador, in the Zangarra swamp.\n\nThis will not take long.", objectives = "Speak with Archmage Khadgar at Khadgar's Tower in Zangarra.", completion = "<The Archmage looks damp and uncomfortable.>\n\nI apologize for the conditions here, <name>. I had no choice. I summoned this tower at the optimal confluence of arcane energies. My hope is to finish my work here before all my books get musty.\n\nSo then! Let's get to it." }
WordHunterWoW_QuestEN[35989] = { title = "Khadgar's Task", description = "This world poses many dangers to our own. Chief among them is the Iron Horde - your garrison and the full might of your army is directed at this foe. But for myself I have a different target in mind.\n\nGul'dan.\n\nHere, make yourself comfortable. Have some mana strudel. I will share my plan as I create your ring...", objectives = "Speak with Khadgar within his tower in Zangarra.", completion = "Your ring is finished. This is but the first step - with more time together we'll be able to create a ring of legendary power. But first things first!\n\nGul'dan could be hiding anywhere, but if we can locate any of his lieutenants I think I know a way to flush him out. Let's begin by gathering the magical reagents I'll need." }
WordHunterWoW_QuestEN[35990] = { title = "Core of Flame", description = "Compared to Azeroth, Draenor is a young world. The primal forces that shaped and bent the land are still accessible - if you know where to look.\n\nI need you to find for me a Core of Flame. The Bloodmaul Ogres have been known to use these to bend molten furies to their will, but you and I can find a much better use for one.\n\nEnter the Bloodmaul Slag Mines and acquire one from Gug'rokk. He won't need it anymore after you kill him.", objectives = "Acquire a Core of Flame from Gug'rokk in the Bloodmaul Slag Mines [Heroic only.]", progress = "Have you been to the Slag Mines yet?\n\nHonestly, who mines slag anyway? What do they do with it?", completion = "<Khadgar rolls the fiery orb back and forth between his hands.>\n\nDo you know how to use this, <name>?\n\nMe neither. Sometimes you just have to improvise as you go." }
WordHunterWoW_QuestEN[35991] = { title = "Core of Iron", description = "There's no point in getting a Core of Flame without any way to focus its power. Somehow, the goblins figured out how to do it - the technology is used in the \"Iron Star\" engines that the Iron Horde is using extensively throughout Draenor. We're gonna need the biggest engine core that we can find.\n\nOur best bet is to derail one of their trains and crack open the engine compartment. I suggest a raid on the Grimrail Depot...", objectives = "Collect a Core of Iron from the engine of the Grimrail Depot train [Heroic only.]", progress = "Did you get the engine core?\n\nOrdinarily I wouldn't ask you to assault a fortified moving train - ah, no, that's not true. This is exactly the sort of thing I'm going to need from you. All the time.", completion = "Oh very good. I've been waiting to get a close look at one of these - let's open it up here.\n\nHmmmmm...\n\nWell, those goblins aren't very creative but their methods have a certain brute-force charm to them. It's amazing this thing doesn't explode. Or maybe it does. At least I'm beginning to understand what they use a \"samophlange\" for.\n\nThis will work. Well done, <name>!" }
WordHunterWoW_QuestEN[35992] = { title = "Core of Life", description = "Scrying for a living being is a very specific kind of magic, and if we want to search the whole of Draenor for Gul'dan, we're going to need a very powerful living reagent.\n\nThe answer lies with the plant life of Draenor itself. There is a creature known as a \"genesaur\" who is the closest we can get to the primordial creatures who shaped all life on this world.\n\nOne of our Kirin-Tor outposts has been overrun in Gorgrond, and a genesaur named \"Yalnu\" was spotted. Kill it, and bring its heart to me!", objectives = "Collect a Core of Life by slaying Yalnu in the Everbloom [Heroic only].", progress = "How fares the outpost? More importantly... where's my core of life?", completion = "Oh - it's still alive! Can you feel that?\n\nI must return this to the soil of Draenor when we are done with it. Perhaps in the care of the Cenarion Circle, who can ensure that it doesn't grow into another corrupted threat.\n\nWell done, <name>. This was no easy feat." }
WordHunterWoW_QuestEN[35993] = { title = "Tackling Teron'gor", description = "I just received dark news from Exarch Maladaar that may be of use to us. Shadow Council agents have infiltrated Auchindoun! I guarantee Gul'dan's minions are behind this - likely Teron'gor, his right-hand orc.\n\nLet's pull him from the chessboard, <name>. Kill Teron'gor!\n\nBring me a vial of his corrupt blood, and I can use it to track down other Shadow Council troublemakers... Including Gul'dan. Our prey will not be able to hide.", objectives = "Obtain Corrupted Blood of Teron'gor from Teron'gor in Auchindoun [Heroic only].", progress = "What news of Auchindoun? Are the spirits of the draenei safe?\n\nWas I right about Teron'gor?", completion = "We've done a great thing today, <name>. We've deprived Gul'dan of one of his top lieutenants and we're one step closer to finding the fiend himself." }
WordHunterWoW_QuestEN[35994] = { title = "Eyes of the Archmage", description = "With the blood of Teron'gor and the crystals you collected for me, I should be able to zero in on our target. Step outside with me and I will begin my scrying spell. Speak with me to start - be ready for anything!", objectives = "Speak with Khadgar and guard him as he performs his scrying spell.", completion = "Gul'dan is countering my magic, <name>! He's hiding!\n\nHe's a crafty one, but we're craftier. I think I know a way to increase the power and range of my spell..." }
WordHunterWoW_QuestEN[35995] = { title = "Tarnished Bronze", description = "That dead dragon's essence has seeped into the very fabric of this light-forsaken world. His spirit is also restless. If you and I are to claim what remains of his power, we're going to need to finish the job that Garrosh started.\n\nI'm going to need to rely on your tactical combat expertise, commander. Would you prefer to go on the offensive, to fight defensively, or to heal us?\n\nThe decision is yours. Speak to me when you are ready, and the three of us will destroy Kairoz once and for all.", objectives = "Speak to Archmage Khadgar to choose your preferred role, and defeat the Spirit of Kairozdormu.", completion = "<The archmage is out of breath.>\n\nGive me - give me a moment. Pshew.\n\n<name>, that was incredible! You are possibly the greatest <class> I've ever had the honor to fight alongside." }
WordHunterWoW_QuestEN[35996] = { title = "Vignette: Depthroot", description = "", objectives = "" }
WordHunterWoW_QuestEN[35997] = { title = "Empire's Fall", description = "The Ogre Sorcerer King, Imperator Mar'gok, has mastered magical techniques we would consider on the fringe of arcane science. His felbreakers, among others, can actively dampen or nullify magic. Even fel magic!\n\nIf we're to locate Gul'dan, we need to figure out how it's done. Acquire a felbreaker's tome from his felbreaker captain and acquire the sigil of the sorcerer king himself - I must know what he knows.\n\nYes, {name}, this means I expect you to storm Highmaul and defeat everyone inside. Get to it!", objectives = "Collect a Felbreaker's Tome and the Sigil of the Sorcerer King from Highmaul.", progress = "What have you found in Highmaul?", completion = "The felbreaker's tome is blank? Let me see that. Did you get the Sorcerer King's sigil? Of course - see here, as you run the sigil over the page, runic lettering appears. Oh... this is really advanced.\n\nIt may take some time to fully comprehend what you've discovered, <name>, but these initial pages appear to be dedicated to the nature of fel. Exactly what I need! Great work!" }
WordHunterWoW_QuestEN[35998] = { title = "Legacy of the Sorcerer Kings", description = "For over a thousand years, the ogre sorcerer kings maintained an iron grip over their empire using a variety of artifacts. Trusted lieutenants were given magical gems that allowed them to enforce the emperor's will out in the field. These \"Abrogator Stones\" still maintain their power even today, and can be found scattered throughout the Highmaul complex. Sometimes in clusters.\n\nCollect oa of these Abrogator Stones for me!", objectives = "Collect 125 Abrogator Stones from creatures in Highmaul. Your garrison followers may also be able to locate stones in certain missions.", progress = "Do you have the stones? I never thought I'd turn to ogres for magical might, but those ancient Sorcerer Kings knew a thing or two about raw arcane energy that would keep Kirin-Tor scholars busy for ages.", completion = "<Khadgar holds some of the stones up to the light, allowing narrow filaments of arcane energy to spiral from stone to stone.>\n\nI don't think I'll ever underestimate ogres again, <name>. One or two intelligent ones can mold the others into a formidable army." }
WordHunterWoW_QuestEN[35999] = { title = "Nagrand - Treasure 071 - Genedar Debris", description = "", objectives = "" }
WordHunterWoW_QuestEN[36000] = { title = "Fugitive Dragon", description = "Ready to do some dragon hunting? A bronze dragon freed Garrosh Hellscream and took him to this world. His name is  Kairozdormu, and he's a fugitive from Azeroth. It's time to track him down.\n\nHis essence permeates this entire timeline. If I could just get a hold of him - dead or alive! - I could re-calibrate my magic to this era of Draenor.\n\nWe'll need the help of a fellow bronze dragon. I'll find her and meet you in Nagrand. Let's rendezvous at the crossroads north of the Ring of Trials.", objectives = "Meet with Khadgar north of the Ring of Trials in Nagrand.", completion = "<name>, Chromie here has offered to help track down our bronze fugitive.\n\nShe may look diminutive, but I assure you she is as old as a hundred of your lifetimes." }
WordHunterWoW_QuestEN[36001] = { title = "Tracking: Mill Treasure 14", description = "", objectives = "" }
WordHunterWoW_QuestEN[36002] = { title = "Nagrand - Treasure 072 - Genedar Debris", description = "", objectives = "" }
WordHunterWoW_QuestEN[36003] = { title = "Tracking: Mill Treasure 15", description = "", objectives = "" }
WordHunterWoW_QuestEN[36004] = { title = "Power Unleashed", description = "You've more than earned a reward, commander. I'll wrap things up here and meet you back at my tower - you can use my portal as a shortcut.\n\nSpeak to me when you arrive and I will use Kairoz's power with the crystals you gathered earlier to upgrade your ring!", objectives = "Speak with Archmage Khadgar at Khadgar's Tower in Zangarra, and allow him to upgrade your ring.", progress = "Do you slay a lot of dragons? You handled that like a professional.", completion = "How are you feeling? Can I get you a drink?\n\nI wish I could say that things will get easier from here, but we're just getting started. I must ask you to storm the very heart of the ogre empire... Are you ready?" }
WordHunterWoW_QuestEN[36005] = { title = "The Scrying Game", description = "We've learned everything we need from the ogres, {name}. Thanks to your efforts, I believe I can pierce the veil of secrecy that's cloaking Gul'dan.\n\nI WILL find him, {class}.\n\nOnce my spell is finished we should be ready to leap into action. I won't begin until you let me know you're ready.", objectives = "Speak with Khadgar and locate Gul'dan with his scrying spell.", completion = "Stabbed! He's been stabbed!\n\nWhy wasn't he more careful? We could've set up wards, we could've -\n\nIt doesn't matter now. We have to act fast." }
WordHunterWoW_QuestEN[36006] = { title = "Hunter: Hunted", description = "The weapon that stabbed the archmage was imbued with fel magic. He's slowly being poisoned!\n\n{name}, we don't have any time. Khadgar will be dead in minutes. I need you to track down Garona before she gets away - find that murder weapon and maybe we can find a cure!\n\nFollow the traces of fel energy she left behind. Track her down into the Zangarra lowlands and capture her with this Violet Hold Incarceration rune.\n\nHurry!", objectives = "Follow Garona's trail into the Zangarra lowlands. Find, defeat, and capture her.", progress = "Why are you wasting time? Find Garona!", completion = "The Kirin-Tor responded quickly. Jaina was here in minutes. But if you hadn't located Garona, the Archmage would've died for certain. Thank you, <name>!" }
WordHunterWoW_QuestEN[36007] = { title = "Touch of the Kirin-Tor", description = "<Khadgar's breathing is labored and his face is drained of color, but his eyes still flash with energy.>\n\nYou saved me, {name}. Once again I underestimated Gul'dan, and it nearly cost me everything.\n\nCome, help me up. While Jaina is here, the two of us can work together to upgrade your ring. You've earned it! Let me know when you're ready.", objectives = "Speak with Archmage Khadgar to upgrade your ring.", completion = "How are you feeling?\n\nThat ring of yours is now one of the most powerful artifacts on this world. Which is good. Because we're about to strike right at the heart of the enemy..." }
WordHunterWoW_QuestEN[36008] = { title = "Nagrand - Treasure 073 - Genedar Debris", description = "", objectives = "" }
WordHunterWoW_QuestEN[36009] = { title = "Heart of the Fury", description = "It is foolish to pursue Gul'dan with magical means alone. But thanks to you we have a prisoner: Garona. If we can break Gul'dan's mind-control over her, we will learn all his secrets.\n\nI can do it, but I'll need some powerful spell components.\n\nFirst on the list is the heart of an elemental fury. There's one imprisoned in the center of the Blackrock Foundry. Fight your way in, destroy the furnace, and slay the elemental within.", objectives = "Collect a Heart of the Fury from the elemental Fury encased within the furnace of the Blackrock Foundry.", progress = "Elemental \"furies\" appear to be unique to Draenor. It may be something about the primal nature of this world.", completion = "Careful, careful! Set it down gently. I'll take it from here.\n\nThe heart of a fury is nothing to toy with." }
WordHunterWoW_QuestEN[36010] = { title = "Flamebender's Tome", description = "The Iron Horde, and the Burning Blade clan in particular, have forged a unique relationship with Draenor's ancient elementals. They can work with iron and flame in ways that even I don't fully understand.\n\nYet.\n\n{name}, slay the Burning Blade's highest-ranking artisan: Flamebender Ka'graz. She is down in the very heart of the Black Forge of the Blackrock Foundry, an area known as the Burning Font. If we're lucky, her secrets are codified in a Flamebender's Tome.", objectives = "Retrieve the Flamebender's Tome from Flamebender Ka'graz in the Blackrock Foundry.", progress = "Do you have the Flamebender's Tome? Many legendary Burning Blade weapons owe their existence to this volume!", completion = "Let me see what we have here... very interesting! This runic language here seems similar to the ignan kalimag dialect spoken by Azeroth's fire elementals. A full translation may take years.\n\nBut these parts written in orcish - yes, these I can probably decipher. Not just to bend steel, but to bend elemental power itself to our will.\n\nGul'dan may be powerful, but if we continue to unlock the mysteries of Draenor, we will be able to counter his every move..." }
WordHunterWoW_QuestEN[36011] = { title = "Nagrand - Treasure 074 - Genedar Debris", description = "", objectives = "" }
WordHunterWoW_QuestEN[36012] = { title = "Reverse Piracy", description = "{name}, during the attack on Karabor Iron Horde dreadnaughts looted or sank most of the draenei eastern fleet. A priceless artifact was captured: A genuine Draenic Thaumaturgical Orb.\n\nI must have it! Those orcs don't know what they've got!\n\nMy sources indicate that the orb was aboard a ship that's being retrofitted down in the Dread Grotto beneath the Blackrock Foundry. Search the ship and the area nearby for the Sha'tari Vault that contained the orb. We've got to get it back!", objectives = "Acquire the Draenic Thaumaturgical Orb from the Dread Grotto in the Blackrock Foundry.", progress = "The orb! Tell me you've found the orb...?", completion = "You found it! I have heard stories of these orbs of power. How I craved to study them during my long exile in Outland. And now, at last, I have one. Show me...\n\n<Reverently, Khadgar opens your pack and looks inside. His face remains motionless for a long time. Finally, he speaks:>\n\n...I don't know what I expected." }
WordHunterWoW_QuestEN[36013] = { title = "Might of the Elemental Lords", description = "Somehow, the Blackrock Clan has forged an alliance with the creatures of fire and stone. I must know how!\n\nSearch the entirety of the Blackrock Foundry. We are looking for stone tablets dating back to the prehistory of Draenor. They will likely be broken apart into fragments that you'll need to assemble by hand. Look for elemental runes carried by high-ranking members of the Iron Horde.\n\nAssemble them and bring me those tablets, {name}. I will use their power to augment the powers of your ring!", objectives = "Collect 3 Elemental Tablets. Assemble the tablets by collecting Elemental Runes from bosses in the Blackrock Foundry.", progress = "I've been able to spend some time studying the prehistory of Draenor. Primal elemental forces competed with each other to shape the world in what is known as the Age of Colossals. Their descendants still fight to this day, especially in regions such as Gorgrond.\n\nThose tablets you're assembling will reveal the forces at work during the era... and more importantly, they will allow us to control and channel those forces, just as the Blackrock do today!", completion = "You've got the tablets. Good, good! It must've been very time-consuming to assemble these - not to mention dangerous. I am lucky to have you.\n\nI see no reason to delay. Show me your ring. Yes... I can do this. Let's put these tablets to use and enhance your power." }
WordHunterWoW_QuestEN[36014] = { title = "Blackhand's Secret", description = "{name}, you've given me a lot to think about. There's a section of the Flamebender's Tome that speaks about a \"sacrifice,\" and a more recent notation referring to \"the chieftain.\" I think it's talking about Warlord Blackhand.\n\nDid Blackhand sacrifice someone? Himself? A piece of himself? Is that why his hand is deformed?\n\nBefore I risk channeling these elements into a spell, I need to know. And there's only one way to find out.\n\nKill Warlord Blackhand. And bring me his severed arm.", objectives = "Slay Warlord Blackhand and acquire his severed arm in the Blackrock Foundry.", progress = "Well <name>? Are you armed?", completion = "What do we have here? The legends ARE true. Blackhand sacrificed his own arm to the elements. Now that he's dead, it's indistinguishable from stone. Or is it?\n\n<Khadgar utters a few incantations from the Flamebinder's Tome. The severed hand slowly clenches into a fist.>\n\nHmmmm. Yes. <name>, I'll be perfectly honest with you: This thing is extremely creepy." }
WordHunterWoW_QuestEN[36015] = { title = "Tracking: Mill Treasure 16", description = "", objectives = "" }
WordHunterWoW_QuestEN[36016] = { title = "The Unbroken Circle", description = "Reading these tablets is like stepping back in time to the moment of Draenor's creation. There is a power here greater than any I have dealt with since I was Medivh's apprentice. I believe I can control it, but - can you handle it?\n\nIf you think you are ready, prepare yourself. Hold your ring close to your heart. I will channel pure elemental energies into it.\n\nSpeak with me to begin!", objectives = "Speak with Archmage Khadgar to upgrade your ring.", progress = "Speak with me when you are ready!", completion = "<Khadgar is deeply distressed.>\n\nI am very sorry, commander. For a moment I thought we had lost you forever.\n\nThis ring will serve you well - I have never seen an artifact so powerful and pure of form. It may be possible to enhance it further but... I do not know at what cost.\n\nUse your ring wisely!" }
WordHunterWoW_QuestEN[36017] = { title = "Prisoner of the Mind", description = "I'd had some time to compare the Flamebinder's tome with the elemental tablets you collected. Where it gets interesting is when I cross-reference the incantations you obtained from the ogre felbreakers... I can see I'm losing you. I will get to the point: I believe I can cast a spell that will nullify Gul'dan's mind control over his assassin Garona.\n\nMind-controlled or not, she may be dangerous, so I won't begin the spell until you're with me. Let me know when you're ready!", objectives = "Speak with Khadgar and protect him while he casts his spell on Garona.", completion = "Gul'dan's magic is embedded deep within Garona's mind. The more time I spend with her, the more it becomes clear that we MUST free her from his control.\n\nI am not giving up on this, <name>." }
WordHunterWoW_QuestEN[36018] = { title = "We're Not Finished...", description = "{name}, I'm going to have to hit the books and do more research to figure out how to locate Gul'dan or untangle his mind control of Garona. It's not glamorous, but the life of a mage is often spent in long hours of grueling study.\n\nAs for you, there's much to do. Ensure that your garrison is fully upgraded, locate the best possible equipment, and continue fighting the Iron Horde.\n\nI will summon you when the next step of our journey is ready.", objectives = "Report to Archmage Khadgar at Khadgar's Tower in Zangarra.", completion = "My studies have gone well. I believe we are ready for the next step. You may not like it..." }
WordHunterWoW_QuestEN[36019] = { title = "Tracking: Mill Treasure 17", description = "", objectives = "" }
WordHunterWoW_QuestEN[36020] = { title = "Nagrand - Treasure 026 - Oshu'gun Fragment", description = "", objectives = "" }
WordHunterWoW_QuestEN[36021] = { title = "Nagrand - Treasure 036 - Pokhar's Thirteenth Axe", description = "", objectives = "" }
WordHunterWoW_QuestEN[36022] = { title = "Extrinsic Motivation", description = "The Shattered Hand aren't strangers to pain. They each cut off their own hand as a sign of their allegiance to Kargath.\n\nIf you're going to get them to talk, it might take more than my poison.\n\nSlaughter them all. We'll see how far they're willing to go for their beloved warlord.", objectives = "Kill 4 Shattered Sightless, 3 Shattered Harvesters, and 1 Shattered Blood-Singer.", completion = "Excellent work." }
WordHunterWoW_QuestEN[36023] = { title = "Extrinsic Motivation", description = "The Shattered Hand are nae strangers tae pain. They each cut off their own hand as a sign o' their allegiance to Kargath.\n\nIf you're going tae get the information we need, it might take more than my poison.\n\nSlaughter them all. We'll see how far they're willing tae go fer their beloved warlord.", objectives = "Kill 4 Shattered Sightless, 3 Shattered Harvesters, and 1 Shattered Blood-Singer.", completion = "They got what's comin' to 'em." }
WordHunterWoW_QuestEN[36024] = { title = "A Few Artifact Fragments", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Good work, <class>. We won't let you down." }
WordHunterWoW_QuestEN[36025] = { title = "A TON of Artifact Fragments", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Good work, <class>. We won't let you down." }
WordHunterWoW_QuestEN[36026] = { title = "A Bunch of Artifact Fragments", description = "", objectives = "The more, the better!", progress = "The more, the better!", completion = "That must of taken great effort to get back to us. You deserve this reward, friend." }
WordHunterWoW_QuestEN[36027] = { title = "The Staff of Archmage Vargoth", description = "", objectives = "Ah, <name>. It is wonderful to \"see\" you. As you are no doubt aware the state of Outland in our own timeline is constantly degrading.\n\nI wish to extend my remote services to your cause so that I might better investigate Draenor in the time before it was ripped asunder.\n\nThis projection may seem translucent, but I can assure you it acts as a perfect conduit for my own powers.\n\nWill you accept my service?" }
WordHunterWoW_QuestEN[36028] = { title = "Gardul Venomshiv", description = "We need to take out Gardul and take his poison recipe while we still have the element of surprise on our side. We need it to craft the antidote. This may be our only opportunity.\n\nIf what you learned is true, his camp is just south of here. You take him down, and I'll make sure none of his guards interfere.\n\nLet's get moving.", objectives = "Defeat Gardul Venomshiv in Shattered Rise.", completion = "We won't let him get away." }
WordHunterWoW_QuestEN[36029] = { title = "Gardul Venomshiv", description = "We need tae take out Gardul and take his poison recipe while we still have the element o' surprise on our side. We need the recipe tae figure out the antidote. This may be our only opportunity.\n\nIf what ye learned is true, his camp is just south of here. Ye take him down, and I'll make sure none of his guards interfere.", objectives = "Defeat Gardul Venomshiv in Shattered Rise.", completion = "We won't let him get away." }
WordHunterWoW_QuestEN[36030] = { title = "A Few Artifact Fragments", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Every little bit helps." }
WordHunterWoW_QuestEN[36031] = { title = "A Bunch of Artifact Fragments", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Good work, <class>. We won't let you down." }
WordHunterWoW_QuestEN[36032] = { title = "A TON of Artifact Fragments", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "Good work, <class>. We won't let you down." }
WordHunterWoW_QuestEN[36033] = { title = "Severed Night Elf Head", description = "", objectives = "THEIR HEAD! BRING ME THOSE NON-DAYLIGHT ELF HEADS!", progress = "THEIR HEAD! BRING ME THOSE NON-DAYLIGHT ELF HEADS!", completion = "IT'S SO PRETTTTY. WILL FIT NICE ON MY SPIKE OUTSIDE MY HUT. HAHAHA. HERE, TAKE THIS REWARD AND GET BACK OUT THERE." }
WordHunterWoW_QuestEN[36034] = { title = "Dwarf Spine", description = "", objectives = "THEY JUST SLIDE RIGHT OUT, DON'T THEY?", progress = "THEY JUST SLIDE RIGHT OUT, DON'T THEY?", completion = "OOOOH! THIS IS A LONG ONE. HE HE HAHAAH. HERE, TAKE THIS AS A REWARD." }
WordHunterWoW_QuestEN[36035] = { title = "Nagrand - Treasure 075 - Polished Saberon Skull", description = "", objectives = "" }
WordHunterWoW_QuestEN[36036] = { title = "Nagrand - Treasure 076 - Elemental Manacles", description = "", objectives = "" }
WordHunterWoW_QuestEN[36037] = { title = "A Centurion Without a Cause", description = "", objectives = "This jungle will kill me and I will not return to cower at the mercy of Mar'gok!\n\nI am a veteran of several wars and campaigned on two continents now. If you have a war worth joining, I will serve for a time.\n\nAt least until I can kill the Sorcerer-King!" }
WordHunterWoW_QuestEN[36038] = { title = "Pandaren Hide", description = "", objectives = "WAIT... YOU DIDN'T GET THIS HIDE FROM A HORDE PANDAREN, DID YOU?", progress = "WAIT... YOU DIDN'T GET THIS HIDE FROM A HORDE PANDAREN, DID YOU?", completion = "WHATEVER, WHO LIKES PANDAS ANYHOW! <Laughs> TAKE THIS REWARD AND GET BACK OUT THERE!" }
WordHunterWoW_QuestEN[36039] = { title = "Nagrand - Treasure 077 - Ogre Hammer", description = "", objectives = "" }
WordHunterWoW_QuestEN[36040] = { title = "Tuft of Gnome Hair", description = "", objectives = "IS THAT... A GNOME HEAD?", progress = "IS THAT... A GNOME HEAD?", completion = "WAIT, YOU JUST BROUGHT ME THEIR HAIR? UGH. I SAID I WANTED THEIR HEAD! UGHHH! <Stomps Feet> BUT I GUESS THIS IS ENOUGH TO PROVE YOU FOUGHT ONE IN BATTLE, SO TAKE YOUR REWARD. AND NEXT TIME, THEIR HEAD!" }
WordHunterWoW_QuestEN[36041] = { title = "Draenei Tail", description = "", objectives = "NOTHING I HATE MORE THAN THOSE BLUE GOATS! I MEAN, WHAT ARE THOSE THINGS ANYWAYS?", progress = "NOTHING I HATE MORE THAN THOSE BLUE GOATS! I MEAN, WHAT ARE THOSE THINGS ANYWAYS?", completion = "A TAIL! WELL, YOU SHOULDN'T HAVE! I'LL CHERISH IT FOREVER!" }
WordHunterWoW_QuestEN[36042] = { title = "Human Bone Chip", description = "", objectives = "HUMANS! UGH, THE PLAGUE OF AZEROTH! THERE'S JUST SO MANY OF THEM... MAKES ME SOOO ANGRY!", progress = "HUMANS! UGH, THE PLAGUE OF AZEROTH! THERE'S JUST SO MANY OF THEM... MAKES ME SOOO ANGRY!", completion = "GOOD WORK, BRING ME BACK MORE AND I'LL COOK YOU UP A CUP OF MY FAMOUS HUMAN BONE BROTH! HAHAH!" }
WordHunterWoW_QuestEN[36046] = { title = "Nagrand - Treasure 078 - Telaar Defender Shield", description = "", objectives = "" }
WordHunterWoW_QuestEN[36047] = { title = "We Have Him Now", description = "We have Gardul right where we want him, commander.\n\nYou're far more equipped to face him than I am. Dispose of him, take his formula from his corpse, and grab as many barrels of poison as you can.\n\nI'll guard this ramp and make sure no reinforcements come to his aid.", objectives = "Collect Venomshiv's Secret Formula and 6 Poison Barrels.", progress = "Do you have everything we need?", completion = "Excellent. I have a ride back to your outpost ready." }
WordHunterWoW_QuestEN[36048] = { title = "We Have Him Now", description = "We have Gardul right cornered, commander.\n\nYe have a much better chance against him than me. Take him out, grab the formula from his corpse, and grab as many barrels o' poison as ye can carry.\n\nI'll stay here and make sure nae reinforcements come to Gardul's aid.", objectives = "Collect Venomshiv's Secret Formula and 6 Poison Barrels.", progress = "I don't want to stick around here any longer than we need to.", completion = "Perfect work. I called in a ride for ye back to the outpost when yer ready." }
WordHunterWoW_QuestEN[36049] = { title = "Nagrand - Treasure 079 - Ogre Beads", description = "", objectives = "" }
WordHunterWoW_QuestEN[36050] = { title = "Nagrand - Treasure 028 - Adventurer's Pouch", description = "", objectives = "" }
WordHunterWoW_QuestEN[36051] = { title = "Nagrand - Treasure 035 - Grizzlemaw's Favorite Bone", description = "", objectives = "" }
WordHunterWoW_QuestEN[36052] = { title = "Nagrand - Treasure 037 - Misplaced Artifacts", description = "", objectives = "" }
WordHunterWoW_QuestEN[36053] = { title = "Treasure: Unused Wood Pile", description = "", objectives = "" }
WordHunterWoW_QuestEN[36054] = { title = "Sealing Fate: Gold", description = "Gold is indeed treasure, but additional treasure for gold?  That's the offer I present.  A Seal of Twisted Fate twists time, providing a burst of additional luck just when you need it.\n\nRemember, you can only obtain three Seals of Twisted Fate per week.  This counts as one of those three.  Next week, I may have others.", objectives = "Gold is indeed treasure, but additional treasure for gold?  That's the offer I present.  A Seal of Twisted Fate twists time, providing a burst of additional luck just when you need it.\n\nRemember, you can only obtain three Seals of Twisted Fate per week.  This counts as one of those three.  Next week, I may have others.", progress = "Gold is indeed treasure, but additional treasure for gold?  That's the offer I present.  A Seal of Twisted Fate twists time, providing a burst of additional luck just when you need it.\n\nRemember, you can only obtain three Seals of Twisted Fate per week.  This counts as one of those three.  Next week, I may have others.", completion = "A simple exchange with complex results.  That's the art of doing business." }
WordHunterWoW_QuestEN[36055] = { title = "Sealing Fate: Apexis Crystals", description = "You seem like the type who is always seeking power, no? These seals provide an investment, if you will, in your future power.\n\nI also seek power, but one that is a more immediate and tangible. If you manage to find some crystals, we can make a deal. \n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I may have others.", objectives = "You seem like the type who is always seeking power, no? These seals provide an investment, if you will, in your future power.\n\nI also seek power, but one that is a more immediate and tangible. If you manage to find some crystals, we can make a deal. \n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I may have others.", progress = "You seem like the type who is always seeking power, no? These seals provide an investment, if you will, in your future power.\n\nI also seek power, but one that is a more immediate and tangible. If you manage to find some crystals, we can make a deal. \n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I may have others.", completion = "Of course you agree." }
WordHunterWoW_QuestEN[36056] = { title = "Sealing Fate: Garrison Resources", description = "That extravagant fortification you built is impressive. Tell me, does it keep all the bad things away? Yes?  How about an exchange for a bit of fate? A wall can be thick enough, but one is never lucky enough. Besides, safety can be so overpriced...\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I may have others.", objectives = "That extravagant fortification you built is impressive. Tell me, does it keep all the bad things away? Yes?  How about an exchange for a bit of fate? A wall can be thick enough, but one is never lucky enough. Besides, safety can be so overpriced...\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I may have others.", progress = "That extravagant fortification you built is impressive. Tell me, does it keep all the bad things away? Yes?  How about an exchange for a bit of fate? A wall can be thick enough, but one is never lucky enough. Besides, safety can be so overpriced...\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I may have others.", completion = "Feeling safe, stranger?" }
WordHunterWoW_QuestEN[36057] = { title = "Sealing Fate: Honor", description = "To kill another for honor is peculiar...a relic of an older time, perhaps?  No matter, this seal is of no use to me.  It is far too burdened with power for me to control.\n\nRemember, you can only collect three seals per week.  This counts as one of those three.  Next week, I may have others.", objectives = "To kill another for honor is peculiar...a relic of an older time, perhaps?  No matter, this seal is of no use to me.  It is far too burdened with power for me to control.\n\nRemember, you can only collect three seals per week.  This counts as one of those three.  Next week, I may have others.", progress = "To kill another for honor is peculiar...a relic of an older time, perhaps?  No matter, this seal is of no use to me.  It is far too burdened with power for me to control.\n\nRemember, you can only collect three seals per week.  This counts as one of those three.  Next week, I may have others.", completion = "A bloody price to pay just to play with luck.  Let's hope it was worth it." }
WordHunterWoW_QuestEN[36058] = { title = "Seal of Tempered Fate: Armory", description = "", objectives = "" }
WordHunterWoW_QuestEN[36059] = { title = "A Worthy Vessel", description = "The time has come, {name}.\n\nAwaken the Talon King from his long slumber. Call him into this world so that he may destroy our enemies!", objectives = "Awaken the Talon King.", completion = "You fight well." }
WordHunterWoW_QuestEN[36060] = { title = "Seal of Tempered Fate: Apexis Crystals", description = "", objectives = "" }
WordHunterWoW_QuestEN[36062] = { title = "Kimzee Pinchwhistle", description = "", objectives = "Ya know, I've been thinking.\n\nWith uncle Krixel back that now frees me up to take some time off from running the Gearworks for a bit.\n\nIf you have the room in your garrison I'd be glad to come join you, I could even teach you some tricks I've learned to keep your accounts in order and the books cooked!" }
