WordHunterWoW_QuestEN[36064] = { title = "A Bunch of Artifact Fragments", description = "", objectives = "Every little bit counts.", progress = "Every little bit counts.", completion = "That must of taken great effort to get back to us. Once we've collected enough artifacts we'll summon the Mage portals back to Warspear within Ashran." }
