WordHunterWoW_QuestEN[36075] = { title = "Proof of Strength: Ogron Horn", description = "This horn is proof of your strength at slaying ogron and your gladiator friend has born witness!\n\nTake the horn back to Jonaa and claim your accolades!", objectives = "Take the proof to Rangari Jonaa at Highpass in Gorgrond.\n\nProvided item:", completion = "It is hard to admit that there is a creature more brutal than an ogre, but the ogron definitely fit that description. Facing a captured ogron in the arena is no mean feat. Facing one in their own lair is something even more dangerous. Hail to thee champion!" }
WordHunterWoW_QuestEN[36076] = { title = "Proof of Strength: Ogron Horn", description = "This horn is proof of your strength at slaying ogron and your gladiator friend has born witness!\n\nTake the horn back to Limbflayer and claim your accolades!", objectives = "Take the proof to Limbflayer at Beastwatch in Gorgrond.\n\nProvided item:", completion = "There is a creature more brutal than an ogre. Facing a captured ogron in the arena is no mean feat. Facing one in their own lair is something even more dangerous. I like your style." }
WordHunterWoW_QuestEN[36077] = { title = "Nagrand - Treasure 063 - Adventurer's Mace", description = "", objectives = "" }
WordHunterWoW_QuestEN[36078] = { title = "Proof of Strength: Gronnling Scale", description = "This scale is proof of your strength at slaying ogron and your gladiator friend has born witness!\n\nTake the scale back to Jonaa and claim your accolades!", objectives = "Take the proof to Rangari Jonaa at Highpass in Gorgrond.\n\nProvided item:", completion = "A gladiator saw you tear this off the back of a gronnling, which I am sure did not part with it easily. It is more like a stone than a true scale though as these brutes are part stone it seems. Not an easy trophy to collect!" }
WordHunterWoW_QuestEN[36079] = { title = "A Hero's Welcome", description = "You have arrived in Frostfire Ridge. Farseer Drek'Thar can guide you from here.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Farseer Drek'Thar at Glacier Bay in Frostfire Ridge.You have arrived in Frostfire Ridge. Farseer Drek'Thar can guide you from here.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[36080] = { title = "Proof of Strength: Gronnling Scale", description = "This scale is proof of your strength at slaying ogron and your gladiator friend has born witness!\n\nTake the scale back to Limbflayer and claim your accolades!", objectives = "Take the proof to Limbflayer at Beastwatch in Gorgrond.\n\nProvided item:", completion = "A gladiator saw you tear this off the back of a gronnling, which I am sure did not part with it easily. It is more like a stone than a true scale though as these brutes are part stone it seems. Not an easy trophy to collect!" }
WordHunterWoW_QuestEN[36081] = { title = "Proof of Strength: Gronn Eye", description = "This eye is proof of your strength at slaying ogron and your gladiator friend has born witness!\n\nTake the eye back to Jonaa and claim your accolades!", objectives = "Take the proof to Rangari Jonaa at Highpass in Gorgrond.\n\nProvided item:", completion = "A gronn's eye is not something they part with alive. Your gladiator described a fight hard won and this trophy is a testament to your abilities.  Well done!" }
WordHunterWoW_QuestEN[36082] = { title = "Nagrand - Treasure 068 - Lost Pendant", description = "", objectives = "" }
WordHunterWoW_QuestEN[36083] = { title = "Proof of Strength: Gronn Eye", description = "This eye is proof of your strength at slaying ogron and your gladiator friend has born witness!\n\nTake the eye back to Limbflayer and claim your accolades!", objectives = "Take the proof to Limbflayer at Beastwatch in Gorgrond.\n\nProvided item:", completion = "A gronn's eye is not something they part with alive. Your gladiator described a fight hard won and this trophy is a testament to your abilities.  Well done!" }
WordHunterWoW_QuestEN[36084] = { title = "Proof of Strength: Botani Bloom", description = "This bloom is proof of your strength at slaying botani and your gladiator friend has born witness!\n\nTake the bloom back to Jonaa and claim your accolades!", objectives = "Take the proof to Rangari Jonaa at Highpass in Gorgrond.\n\nProvided item:", completion = "The botani are nothing to be trifled with. They are incredibly cunning and their powers are strong on their home land. Taking one of their blooms is an true example of your fighting skill!" }
WordHunterWoW_QuestEN[36085] = { title = "On Ebon Wings", description = "Now we bring our fight to the Adherents. Raastok is certain his new invention will give us control of the Apexis weapons, but we must get close - very close.\n\nKa'alu and her ravens will fly us to the Windswept Terrace. We shall gain a foothold there before pressing on to the Terrace of Dawn.", objectives = "Slay 8 Adherents and Windkeeper Koreyx. Speak with Ka'alu for a ride to Windswept Terrace.", progress = "Quickly, we must not let this opportunity pass.", completion = "Good work!\n\nNow, it is time for the next phase of our plan." }
WordHunterWoW_QuestEN[36086] = { title = "Proof of Strength: Botani Bloom", description = "This bloom is proof of your strength at slaying botani and your gladiator friend has born witness!\n\nTake the bloom back to Limbflayer and claim your accolades!", objectives = "Take the proof to Limbflayer at Beastwatch in Gorgrond.\n\nProvided item:", completion = "The botani are nothing to be trifled with. They are incredibly cunning and their powers are strong on their home land. Taking one of their blooms is an true example of your fighting skill!" }
WordHunterWoW_QuestEN[36088] = { title = "Nagrand - Treasure 068 - Adventurer's Pouch", description = "", objectives = "" }
WordHunterWoW_QuestEN[36089] = { title = "Nagrand - Treasure 070 - Abu'Gar's Reel", description = "", objectives = "" }
WordHunterWoW_QuestEN[36090] = { title = "Proof of Strength: Orc Thorn", description = "This thorn is proof of your strength at slaying the infested and your gladiator friend has born witness!\n\nTake the thorn back to Jonaa and claim your accolades!", objectives = "Take the proof to Rangari Jonaa at Highpass in Gorgrond.\n\nProvided item:", completion = "The infested appear to be mere husks animated by plant life. They are slow but very strong. Slaying even one is a strong demonstration of your own skill!" }
WordHunterWoW_QuestEN[36091] = { title = "Proof of Strength: Orc Thorn", description = "This thorn is proof of your strength at slaying the infested and your gladiator friend has born witness!\n\nTake the thorn back to Limbflayer and claim your accolades!", objectives = "Take the proof to Limbflayer at Beastwatch in Gorgrond.\n\nProvided item:", completion = "Sometimes we don't get turned into mulch for the jungle.  Sometimes we get back up, filled with plants. The Infested are hard to kill. Slaying even one is a strong demonstration of your own skill!" }
WordHunterWoW_QuestEN[36092] = { title = "Proof of Strength: Ancient Branch", description = "This branch is proof of your strength at slaying ancients and your gladiator friend has born witness!\n\nTake the branch back to Jonaa and claim your accolades!", objectives = "Take the proof to Rangari Jonaa at Highpass in Gorgrond.\n\nProvided item:", completion = "Ancients here tend to be guardians and tenders, but that does not make them any less dangerous. An enraged ancient is something to be behold. Taking a branch from one is a worthy deed!" }
WordHunterWoW_QuestEN[36094] = { title = "Proof of Strength: Ancient Branch", description = "This branch is proof of your strength at slaying ancients and your gladiator friend has born witness!\n\nTake the branch back to Limbflayer and claim your accolades!", objectives = "Take the proof to Limbflayer at Beastwatch in Gorgrond.\n\nProvided item:", completion = "Ancients here tend to be guardians and tenders, but that does not make them any less dangerous. An enraged ancient is something to be behold. Taking a branch from one is a worthy deed!" }
WordHunterWoW_QuestEN[36095] = { title = "Azuka Bladefury", description = "Agent Springslip is dead. A fire smolders inside a large wound where his heart used to be.\n\nFlipping through a report you find on his corpse you are able to piece together some basic information. Azuka has betrayed the ogres, she has killed Ugbright and taken his power for herself.\n\nYou should report this information to Bodrick at once.", objectives = "Return to Bodrick Grey at your garrison in Shadowmoon Valley.Agent Springslip is dead. A fire smolders inside a large wound where his heart used to be.\n\nFlipping through a report you find on his corpse you are able to piece together some basic information. Azuka has betrayed the ogres, she has killed Ugbright and taken his power for herself.\n\nYou should report this information to Bodrick at once.", completion = "I'm sorry to hear Springslip didn't make it. He was a good agent.\n\nThis news of Azuka gaining even more power is troubling to say the least." }
WordHunterWoW_QuestEN[36096] = { title = "Proof of Strength: Ravager Claw", description = "This claw is proof of your strength at slaying ancients and your gladiator friend has born witness!\n\nTake the claw back to Jonaa and claim your accolades!", objectives = "Take the proof to Rangari Jonaa at Highpass in Gorgrond.\n\nProvided item:", completion = "Even the insects of Gorgrond are larger and meaner than other parts of the world I have been to! Killing them, which you have obviously done, takes a great deal of strength and skill." }
WordHunterWoW_QuestEN[36097] = { title = "Proof of Strength: Ravager Claw", description = "This claw is proof of your strength at slaying ancients and your gladiator friend has born witness!\n\nTake the claw back to Limbflayer and claim your accolades!", objectives = "Take the proof to Limbflayer at Beastwatch in Gorgrond.\n\nProvided item:", completion = "Even the insects of Gorgrond are larger and meaner than other parts of the world I have been to! Killing them, which you have obviously done, takes a great deal of strength and skill." }
WordHunterWoW_QuestEN[36098] = { title = "Proof of Strength: Wasp Stinger", description = "This stinger is proof of your strength at slaying ancients and your gladiator friend has born witness!\n\nTake the stinger back to Jonaa and claim your accolades!", objectives = "Take the proof to Rangari Jonaa at Highpass in Gorgrond.\n\nProvided item:", completion = "As you can see, the venom Gorgrond wasps have is extremely powerful. To face one is to possibly face your own death. I would refrain from harvesting more of these, one enough to prove your strength here!" }
WordHunterWoW_QuestEN[36099] = { title = "Nagrand - Treasure 046 - Goblin Keg", description = "", objectives = "" }
WordHunterWoW_QuestEN[36100] = { title = "Building for Professions", description = "I see that you have acquired the blueprints for a profession building! Use the Architect Table to build in a small plot.", objectives = "Build any profession building.", progress = "How is it coming along?", completion = "Congratulations!" }
WordHunterWoW_QuestEN[36101] = { title = "Proof of Strength: Wasp Stinger", description = "This stinger is proof of your strength at slaying ancients and your gladiator friend has born witness!\n\nTake the stinger back to Limbflayer and claim your accolades!", objectives = "Take the proof to Limbflayer at Beastwatch in Gorgrond.\n\nProvided item:", completion = "As you can see, the venom Gorgrond wasps have is extremely powerful. To face one is to possibly face your own death. I would refrain from harvesting more of these, one enough to prove your strength here!" }
WordHunterWoW_QuestEN[36102] = { title = "Nagrand - Treasure 045 - Saberon Stash", description = "", objectives = "" }
WordHunterWoW_QuestEN[36103] = { title = "Proof of Strength: Basilisk Scale", description = "This scale is proof of your strength at slaying basilisks and your gladiator friend has born witness!\n\nTake the scale back to Jonaa and claim your accolades!", objectives = "Take the proof to Rangari Jonaa at Highpass in Gorgrond.\n\nProvided item:", completion = "A gruesome trophy from a gruesome beast. To be frozen and eaten slowly is not a death I would choose. The world is better with less of these basilisks in it!" }
WordHunterWoW_QuestEN[36104] = { title = "Proof of Strength: Basilisk Scale", description = "This scale is proof of your strength at slaying basilisks and your gladiator friend has born witness!\n\nTake the scale back to Limbflayer and claim your accolades!", objectives = "Take the proof to Limbflayer at Beastwatch in Gorgrond.\n\nProvided item:", completion = "A gruesome trophy from a gruesome beast. To be frozen and eaten slowly is not a death I would choose. The world is better with less of these basilisks in it!" }
WordHunterWoW_QuestEN[36105] = { title = "Proof of Strength: Elemental Crystal", description = "This crystal is proof of your strength at slaying elementals and your gladiator friend has born witness!\n\nTake the crystal back to Jonaa and claim your accolades!", objectives = "Take the proof to Rangari Jonaa at Highpass in Gorgrond.\n\nProvided item:", completion = "I have seen no elementals elsewhere in Draenor that compare in ferocity to those in Gorgrond. I wonder what caused them to be so angry. That crystal was hard-won I am sure!" }
WordHunterWoW_QuestEN[36106] = { title = "Proof of Strength: Elemental Crystal", description = "This crystal is proof of your strength at slaying elementals and your gladiator friend has born witness!\n\nTake the crystal back to Limbflayer and claim your accolades!", objectives = "Take the proof to Limbflayer at Beastwatch in Gorgrond.\n\nProvided item:", completion = "I have seen no elementals elsewhere in Draenor that compare in ferocity to those in Gorgrond. I wonder what caused them to be so angry. That crystal was hard-won I am sure!" }
WordHunterWoW_QuestEN[36107] = { title = "Trophy Hunter of Gorgrond", description = "", objectives = "I believe I speak for all of us when I say you are among the fiercest predators in Gorgrond! You have faced and slain Gorgrond's most dangerous creatures on their home ground and lived to bring something of them back here.\n\nThe gladiators have come together found something that will show the world your might! Bask in the glory champion!" }
WordHunterWoW_QuestEN[36108] = { title = "Trophy Hunter of Gorgrond", description = "", objectives = "I believe I speak for all of us when I say you are among the fiercest predators in Gorgrond! You have faced and slain Gorgrond's most dangerous creatures on their home ground and lived to bring something of them back here.\n\nThe gladiators have come together found something that will show the world your might! Bask in the glory champion!" }
