WordHunterWoW_QuestEN[36112] = { title = "Flight Home", description = "", objectives = "" }
WordHunterWoW_QuestEN[36115] = { title = "Nagrand - Treasure 017 - Pale Elixir", description = "", objectives = "" }
WordHunterWoW_QuestEN[36116] = { title = "Nagrand - Treasure 061 - Bag of Herbs", description = "", objectives = "" }
WordHunterWoW_QuestEN[36117] = { title = "Garrison Campaign: The Broken Precipice", description = "Hey there! You're the commander of this keep, right? I represent the Steamwheedle Preservation Society.\n\nWe've been trying to get a very important excavation up and running in Nagrand. Unfortunately, we've had trouble with ogres in the area.\n\nIn fact, one of our best preservationists recently went missing while surveying the area. He's the third society member we've lost up there this week!\n\nWe aren't really equipped for a rescue mission... so whad'ya say? We could really use the help.", objectives = "Find Greblin Fastfizzle.", completion = "You're looking for what now? I mean, yeah sure... whatever. Just get me down alright?" }
WordHunterWoW_QuestEN[36118] = { title = "Treasure: Pile of Rubble", description = "", objectives = "" }
WordHunterWoW_QuestEN[36119] = { title = "Welcome to Ashran", description = "Greetings, and welcome to Ashran. \n\nReport to Commander Anne Dunworthy in Stormshield for your briefing.", objectives = "Speak to Commander Anne Dunworthy in Stormshield.", completion = "You've just now showed up? Well, better late than never." }
WordHunterWoW_QuestEN[36123] = { title = "Into The Wilderness", description = "The Road of Glory is not just the only field of strife in this land, <name>. We must go into the wilderness here to uncover the artifacts.\n\nVenture forth and kill a member of the Horde you find in the outskirt areas and bring me back a piece of their armor to prove your worth.", objectives = "Chris Clarkie in Stormshield Stronghold wants you to kill a member of the Horde outside of the main road and recover a piece of their armor.", progress = "That was fast, did you bring me a piece of their armor as proof?", completion = "Fantastic. You can always bring me back tokens you find on Horde corpses for a bonus reward." }
WordHunterWoW_QuestEN[36124] = { title = "Jared's Test Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[36125] = { title = "The Road of Glory", description = "The Horde intends to force us out of Ashran, <name>. We can't let them succeed. March into the Road of Glory and thin their ranks by at least five.", objectives = "Chris Clarkie in Stormshield wants you to kill 5 members of the Horde within the Road of Glory.", completion = "Nice work, <name>. You're a natural." }
WordHunterWoW_QuestEN[36127] = { title = "Survey Ashran", description = "As a Farseer, I can peer into the far corners of Ashran while within Stormshield. But you must go forth and see it for yourself, <name>.", objectives = "Farseer Kylanda in Stormshield wants you to explore The Road of Glory, The Molten Quarry, Brute's Rise, The Amphitheater Of Annihilation and The Ashmaul Burial Grounds in Ashran.", completion = "I can see you have the spirit of a true adventurer, <name>. Come visit me anytime and you can see Ashran through my eyes, even from Stormshield." }
WordHunterWoW_QuestEN[36128] = { title = "Sabermaw - Saberon Vignette Boss", description = "", objectives = "" }
WordHunterWoW_QuestEN[36129] = { title = "Vignette: Nas Dunberlin", description = "", objectives = "" }
WordHunterWoW_QuestEN[36130] = { title = "Reporting For Duty", description = "Front and center, <name>! No time to waste, go speak with these fellows and they'll fill you in.", objectives = "Speak to Misirin Stouttoe, Farseer Kylanda and Chris Clarkie.", completion = "Yes yes, it's the real Harrison Jones. Why is he such a celebrity all of a sudden?" }
WordHunterWoW_QuestEN[36131] = { title = "Proving Your Worth", description = "Now that you have proven yourself as a warrior, let's see how your fishing skills hold up. I have fashioned a bait out of the icespine stingers you brought me. Use it to catch the Zangar eels in these coastal waters.", objectives = "Prove your worth to Mokugg Lagerpounder by catching 5 Zangar Eels using the supplied bait.", progress = "Catch those eels?", completion = "I see you are both a fisherman and a warrior.  I will do what I can to help you." }
WordHunterWoW_QuestEN[36132] = { title = "Anglin' In Our Garrison", description = "You have proven your worth, traveler.  Now take this frostwolf fishing journal back to your garrison and study up.  You will be catching all you can eat in no time.", objectives = "Return to Mak'jin with the Frostwolf Fishing Journal.", progress = "We can use that as bait?!", completion = "Look at all the bait ideas in this thing! Great job <name>!" }
WordHunterWoW_QuestEN[36133] = { title = "Uncovering the Artifact Fragments", description = "The Artifact Fragments seem to come from any creature we've found in the outskirts of Ashran. Go out and kill any you find and bring at least five to Ecilam the Mage near the campfire in Stormshield Stronghold.", objectives = "Misirin Stouttoe in Stormshield Stronghold wants you to go kill creatures in the outskirts of Ashran outside of the main road and bring back 5 Artifact Fragments to Ecilam.", progress = "Are those Artifact Fragments, I see?", completion = "Good work. If you happen to find anymore Artifact Fragments, bring them to me or the others in need of them to contribute to the war effort." }
WordHunterWoW_QuestEN[36134] = { title = "Garrison Campaign: Awakening", description = "We've tracked Warlord Bladefury and the stolen artifact to the salt fields of western Gorgrond.\n\nThisalee Crow will meet you there with an advance scouting team.\n\nThe entire garrison is on high alert. We must be ready to intercept the enemy if necessary.", objectives = "Speak to Thisalee Crow at Gorgorek's Rest in Gorgrond.", progress = "This isn't looking good.", completion = "I've never seen a magnaron of that size before. This is bad, <name>." }
WordHunterWoW_QuestEN[36135] = { title = "Rosa is bad", description = "TextYou will receive:\n\nUpon completion of this quest you will gain:", objectives = "Retrieve Rulga's lost inscription papers." }
WordHunterWoW_QuestEN[36136] = { title = "Garrison Campaign: Awakening", description = "We've tracked Warlord Bladefury an' da stolen artifact ta northern Gorgrond.\n\nCholuna be dere wit a scouting team.\n\nI got dey entire garrison on high alert. Go, meet wit her, and intercept da enemy if necessary.", objectives = "Speak to Choluna at Gorgorek's Rest in Gorgrond.", completion = "I've never seen a magnaron of that size before. This is bad, <name>." }
WordHunterWoW_QuestEN[36137] = { title = "Easing into Lumberjacking", description = "Sir, we're going to need a lot of lumber if we're going to build this garrison into a suitable fortress. That means we're going to have to do a little work.\n\nWhile I certainly wouldn't ask you to dirty your hands with manual labor, I do need you to go out and find timber for our mill. Once you mark a tree an able-bodied lazy-good-for-nothing peon will come and chop it down and give you the timber.\n\nFrostfire isn't the best place for timber, but I did see a suitable small tree nearby.", objectives = "Harvest a Timber Sample from Small Timber and return it to Lumber Lord Oktron.", progress = "This garrison isn't going to build itself, commander! We need timber!", completion = "You're going to make a fine overseer, sir! Keep those peons in line!\n\nNow you know the basics of logging and finding timber. Time to put them to good use for the good of your garrison." }
WordHunterWoW_QuestEN[36138] = { title = "Turning Timber into Profit", description = "Now that you know how to put peons to work harvesting timber, we're going to create a work order for your mill.\n\nBut first we're going to need some timber to process!\n\nAll around Draenor are juicy trees ripe for the chopping. Go out and find suitable timber for the lumber mill. Come back here when you have enough and we'll get started on a work order.\n\nAnd as usual, let the peons do the hard work. Just keep 'em protected. Draenor's a dangerous place!", objectives = "Collect 10 pieces of Timber from around Draenor and then Place a Work Order at your Garrison's Lumber Mill.", progress = "We need lots and lots of timber, commander!", completion = "That's how it's done, commander!\n\nWe're now fully operational. Any time you have enough timber to place a work order, come on back to me and we'll get started.\n\nThis garrison ain't gonna build itself!" }
